export const VIT: Record<'en' | 'fr', VitLang> = {"en":{"hero":{"title":"What you can buy on ArcHive.","acc":"buy","lede":"ArcHive is a market for services that run inside sealed Intel TDX machines. AI agents and apps buy private AI that answers with a signed receipt, 0.01 USDC a call with x402 or 0.10 USDC per 1,000 tokens in a prepaid session. Protocols buy bug bounties that pay only for an exploit a machine has replayed. Before any USDC moves, a contract on Arc checks the machine itself, with no verification service in between."},"shop":{"k1":"The shop window","k2":"5 products on Arc, in three families, and two stories from v2.1","note":"Green means a verified enclave runs it now, amber that none does, both read live on Arc. Every past payment and proof stays readable on Arc."},"rows":[{"id":"bounty","lamp":"amber","name":"Sealed Bounty","word":"Not running","price":"your tier + 15%","line":"DeFi protocols pay hunters only for exploits replayed inside an enclave. The report reaches the protocol alone."},{"id":"private-ai","lamp":"amber","name":"Private AI","word":"Not running","price":"0.01 USDC a call","line":"For apps and AI agents: answers from gpt-oss-120b with a signed receipt, the prompt sealed for one verified enclave."},{"id":"attested-copilot","lamp":"amber","name":"Attested Copilot","word":"Not running","price":"free","line":"Your browser checks the copilot’s enclave key on Arc before you type, so even our web server sees only ciphertext."},{"id":"refutation","lamp":"red","name":"Cheating costs","word":"Bond seized","price":"demo","line":"On 10 Nov an enclave built to lie was caught by two others, and the contract seized its operator’s 1.00 USDC bond."},{"id":"retired","lamp":"off","name":"Retired","word":"v2.1: replaced by #7","price":"never paid","line":"On v2.1: switched off on 10 Nov by our own security review, before it paid anything. Product #7 replaced it; on v3 the verified bounty is #5."}],"faces":[{"id":"bounty","title":"Sealed Bounty","word":"Not running","lamp":"amber","units":"#2 #5"},{"id":"private-ai","title":"Private AI","word":"Not running","lamp":"amber","units":"#1 #3"},{"id":"attested-copilot","title":"Attested Copilot","word":"Not running","lamp":"amber","units":"#4"},{"id":"refutation","title":"Cheating costs","word":"Bond seized","lamp":"red","units":"v2.1 #5"},{"id":"retired","title":"Retired","word":"v2.1: replaced by #7","lamp":"off","units":"v2.1 #6"}],"hint":"Point at a sled to pull it out, click to read its sheet.","state":{"text":"On Arc testnet, the verified enclaves of products #1, #2, #3, #4 and #5 run on the v3 stack, so these services can be used now. Every past payment and proof stays readable on Arc.","link":"Watch a real run, replayed"},"chapters":[{"id":"offers","cls":"vit-shop","k":"The offer","t":"The offer","plain":"Three products to buy, one rule behind them.","units":"","body":"<h2 class=\"vit-shop-h\" id=\"vit-shop-h\">Three products to buy, one rule behind them.</h2><ol class=\"vit-board\"><li class=\"vit-offer\"><a data-vt-ch=\"bounty\" class=\"vit-offer-face\" href=\"?c=bounty\"><span class=\"blade vit-face\" data-led=\"amber\" data-long=\"0\" aria-hidden=\"true\"><span class=\"blade-face\"><span class=\"bl-led\"><i></i></span><span class=\"bl-title\">Sealed Bounty</span><span class=\"bl-word\">Not running</span><span class=\"bl-u\">#2 #5</span></span></span></a><h3 class=\"vit-offer-p\"><a data-vt-ch=\"bounty\" href=\"?c=bounty\">Pay only for exploits that are proven.</a></h3><div class=\"vit-offer-r\"><p class=\"lbl vit-k\">For</p><p class=\"vit-v\">DeFi protocols on Arc, and the security researchers who hunt their bugs.</p></div><div class=\"vit-offer-r vit-offer-price\"><p class=\"lbl vit-k\">Price</p><p class=\"mono tnum vit-price\">Tier + 15%</p><p class=\"vit-v vit-price-s\">From your own pool, and only when an exploit is proven. The hunter gets the whole tier.</p></div><div class=\"vit-offer-r\"><p class=\"lbl vit-k\">Why a sealed machine</p><p class=\"vit-v\">The exploit stays secret until it is paid, and nothing is paid before proof. A sealed machine both sides can check does both.</p></div><div class=\"vit-offer-r\"><p class=\"lbl vit-k\">Today</p><p class=\"vit-v vit-today\"><span class=\"led led-amber\" aria-hidden=\"true\"></span>Running on the v3 stack. Last paid run on Arc: 9 November.</p></div><div class=\"vit-offer-go\"><a data-vt-ch=\"bounty\" class=\"btn btn-line btn-s\" href=\"?c=bounty\"><span>See the Sealed Bounty</span></a></div></li><li class=\"vit-offer\"><a data-vt-ch=\"private-ai\" class=\"vit-offer-face\" href=\"?c=private-ai\"><span class=\"blade vit-face\" data-led=\"amber\" data-long=\"0\" aria-hidden=\"true\"><span class=\"blade-face\"><span class=\"bl-led\"><i></i></span><span class=\"bl-title\">Private AI</span><span class=\"bl-word\">Not running</span><span class=\"bl-u\">#1 #3</span></span></span></a><h3 class=\"vit-offer-p\"><a data-vt-ch=\"private-ai\" href=\"?c=private-ai\">Private AI with a receipt for every answer.</a></h3><div class=\"vit-offer-r\"><p class=\"lbl vit-k\">For</p><p class=\"vit-v\">Apps that handle legal, finance or health text, and AI agents that pay per call.</p></div><div class=\"vit-offer-r vit-offer-price\"><p class=\"lbl vit-k\">Price</p><p class=\"mono tnum vit-price\">0.01 USDC</p><p class=\"vit-v vit-price-s\">per call, or 0.10 USDC per 1,000 tokens in a prepaid session. Testnet prices.</p></div><div class=\"vit-offer-r\"><p class=\"lbl vit-k\">Why a sealed machine</p><p class=\"vit-v\">Your prompt must stay unreadable by the operator who runs the machine, and by us.</p></div><div class=\"vit-offer-r\"><p class=\"lbl vit-k\">Today</p><p class=\"vit-v vit-today\"><span class=\"led led-amber\" aria-hidden=\"true\"></span>Running on the v3 stack. Last paid call on Arc: 10 November.</p></div><div class=\"vit-offer-go\"><a data-vt-ch=\"private-ai\" class=\"btn btn-line btn-s\" href=\"?c=private-ai\"><span>See Private AI</span></a></div></li><li class=\"vit-offer\"><a data-vt-ch=\"attested-copilot\" class=\"vit-offer-face\" href=\"?c=attested-copilot\"><span class=\"blade vit-face\" data-led=\"amber\" data-long=\"0\" aria-hidden=\"true\"><span class=\"blade-face\"><span class=\"bl-led\"><i></i></span><span class=\"bl-title\">Attested Copilot</span><span class=\"bl-word\">Not running</span><span class=\"bl-u\">#4</span></span></span></a><h3 class=\"vit-offer-p\"><a data-vt-ch=\"attested-copilot\" href=\"?c=attested-copilot\">An assistant you can verify.</a></h3><div class=\"vit-offer-r\"><p class=\"lbl vit-k\">For</p><p class=\"vit-v\">Anyone who wants help with ArcHive without trusting our server.</p></div><div class=\"vit-offer-r vit-offer-price\"><p class=\"lbl vit-k\">Price</p><p class=\"mono tnum vit-price\">Free</p><p class=\"vit-v vit-price-s\">No wallet needed to ask.</p></div><div class=\"vit-offer-r\"><p class=\"lbl vit-k\">Why a sealed machine</p><p class=\"vit-v\">Its instructions are measured, so they cannot change in silence, and the conversation is sealed from our web server.</p></div><div class=\"vit-offer-r\"><p class=\"lbl vit-k\">Today</p><p class=\"vit-v vit-today\"><span class=\"led led-amber\" aria-hidden=\"true\"></span>Running in its own enclave, on the v3 stack. It answers as AskHive, in the corner of every page.</p></div><div class=\"vit-offer-go\"><a data-vt-ch=\"attested-copilot\" class=\"btn btn-line btn-s\" href=\"?c=attested-copilot\"><span>See the copilot</span></a></div></li></ol><div class=\"vit-rule\"><a data-vt-ch=\"refutation\" class=\"vit-rule-face\" href=\"?c=refutation\"><span class=\"blade vit-face\" data-led=\"red\" data-long=\"0\" aria-hidden=\"true\"><span class=\"blade-face\"><span class=\"bl-led\"><i></i></span><span class=\"bl-title\">Cheating costs</span><span class=\"bl-word\">Bond seized</span><span class=\"bl-u\">v2.1 #5</span></span></span></a><div class=\"vit-rule-b\"><h3 class=\"vit-rule-h\">Behind all three: a lie costs the bond.</h3><p class=\"vit-rule-d\">On 10 November an enclave built to lie claimed a 2&#160;USDC loss. Two other operators replayed the exploit, proved the real loss was 1&#160;USDC, and the contract seized the liar’s whole bond. 16&#160;seconds passed between the lie being accepted and the bond being seized.</p><a data-vt-ch=\"refutation\" class=\"tlink\" href=\"?c=refutation\">See the refutation</a></div></div><p class=\"vit-retired-line\"><span class=\"led\" aria-hidden=\"true\"></span><span>Retired on v2.1: #6, the first verified bounty. Our own security review found a flaw in its chip check, so it was switched off and replaced by #7, the verified bounty that is #5 on v3. <a data-vt-ch=\"retired\" class=\"tlink\" href=\"?c=retired\">Read the story</a></span></p>"},{"id":"notary","cls":"vit-sec vit-notary","k":"Why trust it","t":"Why trust it","plain":"Why you can trust a stranger’s machine.","units":"","body":"<div class=\"vit-notary-hd\"><h2 aria-label=\"Why you can trust a stranger’s machine.\" class=\"vt-h vit-h2\" id=\"vit-notary-h\">Why you can trust a <span class=\"vt-acc\">stranger’s</span> <span class=\"vt-acc\">machine</span>.<span class=\"ttl-rule\" aria-hidden=\"true\"></span></h2><p class=\"lede vit-notary-l\">Arc is the notary. No platform, committee or verification service stands between the buyer and the machine: contracts on Arc check it, hold the money and punish a lie.</p></div><ol class=\"vit-notary-p\"><li class=\"row\"><h3 class=\"vit-notary-t\">Intel signs, Arc checks.</h3><p class=\"vit-notary-d\">Each machine proves which code it runs with a quote signed by Intel. Before admitting it, a contract on Arc verifies that signature and replays the machine’s boot log byte by byte. It costs about 0.17&#160;USDC of gas, and no fee.</p><code class=\"mono vit-code\">EnclaveRegistry, TdxAttestationModule, Automata DCAP</code></li><li class=\"row\"><h3 class=\"vit-notary-t\">The contract that pays is the one that checks.</h3><p class=\"vit-notary-d\">A receipt, a call or a bounty claim is paid only if a key that Arc admitted signed it, for that product, at a recent block. Deposits and bounty pools wait in the contract, never with us.</p><code class=\"mono vit-code\">SessionPay, X402Settler, SealedBounty</code></li><li class=\"row\"><h3 class=\"vit-notary-t\">A lie costs the bond.</h3><p class=\"vit-notary-d\">Every operator locks USDC. When a lie is proven, by a second replay for a bounty or by two conflicting receipts for AI, the contract seizes the whole bond, half to whoever proved it and half to the victim, and bans the operator. A dispute is a second replay, not a vote.</p><code class=\"mono vit-code\">OperatorBond.slash</code></li></ol><div class=\"vit-notary-f\"><p class=\"vit-notary-c\">13 of our contracts are in service on Arc. We deployed 51 in all, counting earlier versions and the 15 contracts of Automata’s verifier for Intel’s signatures. 253&#160;tests.</p><a class=\"btn btn-main\" href=\"/doc.html\"><span>See how Arc checks a machine</span></a></div>"},{"id":"bounty","cls":"vit-sec vit-fam","k":"Products #2 and #5","t":"Sealed Bounty","plain":"Sealed Bounty","units":"#2 #5","body":"<header class=\"vit-fam-hd is-arc\"><h2 aria-label=\"Sealed Bounty\" class=\"vt-h vit-fam-name\" id=\"bounty-h\">Sealed Bounty<span class=\"ttl-rule\" aria-hidden=\"true\"></span></h2><p class=\"vit-fam-head\">Pay only for exploits that are proven.</p><p class=\"lede vit-fam-sub\">A hunter seals an exploit. An enclave that Arc has verified replays it on a copy of Arc and measures the loss. Only a real loss gets paid, and the report goes to you alone, in the same transaction.</p></header><ul class=\"vit-tiers\"><li class=\"vit-tier\" data-pid=\"2\"><span class=\"blade vit-face\" data-led=\"amber\" data-long=\"0\" aria-hidden=\"true\"><span class=\"blade-face\"><span class=\"bl-led\"><i></i></span><span class=\"bl-title\">Sealed Bounty</span><span class=\"bl-word\">Not running</span><span class=\"bl-u\">#2</span></span></span><h3 class=\"vit-tier-n\">Open level</h3><dl class=\"kv-list vit-kv\"><div class=\"kv-row\"><dt>Who can sign a claim</dt><dd>Any enclave that Arc has admitted for this product, run by an operator with a bond.</dd></div><div class=\"kv-row\"><dt>For</dt><dd>Any protocol on Arc, from its first pool.</dd></div><div class=\"kv-row\"><dt>Contract</dt><dd><a class=\"tlink vit-addr\" href=\"https://explorer.testnet.arc.io/address/0xaA229Eda6b535DF6aEe0B4D892f39e0EC006d308\" target=\"_blank\" rel=\"noreferrer\"><span>SealedBounty</span> <span class=\"mono\">0xaA22…d308</span></a></dd></div><div class=\"kv-row\"><dt>Today</dt><dd>Running on the v3 stack. Paid once on Arc, on 9 November, on v2.1.</dd></div></dl><div class=\"vit-tier-go\"><a class=\"btn btn-main btn-s\" href=\"/space.html?tab=bounties\"><span>Post a bounty</span></a><p class=\"lbl vit-tier-note\">Posting works now, and claims are replayed by the running machines.</p></div></li><li class=\"vit-tier\" data-pid=\"5\"><span class=\"blade vit-face\" data-led=\"amber\" data-long=\"1\" aria-hidden=\"true\"><span class=\"blade-face\"><span class=\"bl-led\"><i></i></span><span class=\"bl-title\">Sealed Bounty, verified</span><span class=\"bl-word\">Not running</span><span class=\"bl-u\">#5</span></span></span><h3 class=\"vit-tier-n\">Verified level</h3><dl class=\"kv-list vit-kv\"><div class=\"kv-row\"><dt>Who can sign a claim</dt><dd>Only enclaves on a chip that Intel’s certificate identifies, declared in an inspected datacenter by the Proof of Cloud alliance. Arc checks both.</dd></div><div class=\"kv-row\"><dt>For</dt><dd>Larger pools, and buyers who accept certified hardware only.</dd></div><div class=\"kv-row\"><dt>Contract</dt><dd><a class=\"tlink vit-addr\" href=\"https://explorer.testnet.arc.io/address/0x8958EA25c9cF7bbee39B32C43187d854B5d73ee6\" target=\"_blank\" rel=\"noreferrer\"><span>SealedBountyVerified</span> <span class=\"mono\">0x8958…3ee6</span></a><span class=\"lbl muted vit-same\">same code as SealedBounty</span></dd></div><div class=\"kv-row\"><dt>Today</dt><dd data-live-v=\"p7today\">Authorized to pay since 19 November, 20:37 UTC, wired with the rest of the v3 stack: no 8-day wait.</dd></div></dl><div class=\"vit-tier-go\"><a class=\"btn btn-line btn-s\" href=\"/service.html?p=5\"><span>See the verified level</span></a></div></li></ul><div class=\"vit-fam-body\"><div class=\"vit-fam-main\"><h3 class=\"vit-h3\">How it works</h3><ol class=\"path vit-steps\"><li class=\"row path-s\"><span class=\"path-n mono\" aria-hidden=\"true\">01</span><div class=\"path-b\"><h4 class=\"path-t\">The protocol posts a bounty</h4><p class=\"path-d\">A USDC pool, a loss rule a machine can check (for example, the USDC balance of contract X drops by at least T), payout tiers and its encryption key. Optionally, a contract the bounty may pause.</p><p class=\"vit-step-c\"><code class=\"mono vit-code\">SealedBounty.createBounty</code></p></div></li><li class=\"row path-s\"><span class=\"path-n mono\" aria-hidden=\"true\">02</span><div class=\"path-b\"><h4 class=\"path-t\">The hunter seals the exploit</h4><p class=\"path-d\">It is encrypted for the enclave alone. Inside Intel TDX, the enclave replays it on a fork of Arc at a recent block with Circle’s arc-anvil, measures the loss and signs a claim.</p><p class=\"vit-step-c\"><code class=\"mono vit-code\">EIP-712 claim</code></p></div></li><li class=\"row path-s\"><span class=\"path-n mono\" aria-hidden=\"true\">03</span><div class=\"path-b\"><h4 class=\"path-t\">Arc checks the claim</h4><p class=\"path-d\">Accepted only if an enclave Arc admitted for this product signed it, the block is recent, the tier matches the rule and this exploit was never paid. The payout is reserved and the target paused.</p><p class=\"vit-step-c\"><code class=\"mono vit-code\">SealedBounty.acceptClaim</code></p></div></li><li class=\"row path-s\"><span class=\"path-n mono\" aria-hidden=\"true\">04</span><div class=\"path-b\"><h4 class=\"path-t\">Paid and delivered in one transaction</h4><p class=\"path-d\">The report reaches the protocol, encrypted for it alone. The hunter gets the tier, the network 10%, the verifying operators 5%, and an ERC-8004 verdict is written.</p><p class=\"vit-step-c\"><code class=\"mono vit-code\">SealedBounty.deliver</code></p></div></li><li class=\"row path-s\"><span class=\"path-n mono\" aria-hidden=\"true\">05</span><div class=\"path-b\"><h4 class=\"path-t\">Three days to contest</h4><p class=\"path-d\">Two other operators can refute a claim by replaying the exploit. If the claim was a lie, its operator loses the whole bond.</p><p class=\"vit-step-c\"><code class=\"mono vit-code\">SealedBounty.refute</code></p></div></li></ol><h3 class=\"vit-h3\">Proof on Arc</h3><p class=\"lbl muted vit-h3-l\">Real transactions on Arc testnet, made on the v2.1 stack before the switch to v3. Each one opens on the explorer.</p><div class=\"vit-rcpts\"><figure class=\"vit-rcpt is-arc\"><figcaption class=\"vit-rcpt-h\"><span class=\"vit-rcpt-t\">Payout receipt</span><span class=\"mono tnum vit-rcpt-d\">9 Nov 2026, 19:04:58 UTC</span></figcaption><dl class=\"vit-rcpt-l\"><div><dt>Hunter, the whole tier</dt><dd class=\"mono tnum\">0.500<span class=\"vit-u\"> USDC</span></dd></div><div><dt>Network, plus 10%</dt><dd class=\"mono tnum\">0.050<span class=\"vit-u\"> USDC</span></dd></div><div><dt>Verifying operator, plus 5%</dt><dd class=\"mono tnum\">0.025<span class=\"vit-u\"> USDC</span></dd></div><div class=\"is-total\"><dt>Paid from the protocol’s pool</dt><dd class=\"mono tnum\">0.575<span class=\"vit-u\"> USDC</span></dd></div><div class=\"is-extra\"><dt>Report, encrypted for the protocol</dt><dd class=\"mono tnum\">delivered</dd></div><div class=\"is-extra\"><dt>ERC-8004 verdict</dt><dd class=\"mono tnum\">100</dd></div></dl><p class=\"vit-rcpt-n\">One transaction, 4&#160;seconds after the claim was accepted. The exploit had been replayed inside a production TDX machine in 6.3&#160;seconds.</p><p class=\"vit-rcpt-x\"><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0xecbd089a092edd939ff646fae8d22c0f2616b6a92f58a49928c231c770bb807e\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Open on the explorer: 0xecbd089a092edd939ff646fae8d22c0f2616b6a92f58a49928c231c770bb807e\">0xecbd089a…807e</a></p></figure></div><ol class=\"vit-proofs\"><li class=\"vit-proof\"><span class=\"mono tnum vit-proof-at\">9 Nov, 19:04:42 UTC</span><span class=\"vit-proof-w\">Bounty posted: 1&#160;USDC pool, one tier of 0.5&#160;USDC for a loss of at least 1&#160;USDC</span><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0x1c8e42400950540f7ffc1f8f18bc4e4860f7108d18c0e978cead4a5580a1d4e2\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Open on the explorer: 0x1c8e42400950540f7ffc1f8f18bc4e4860f7108d18c0e978cead4a5580a1d4e2\">0x1c8e4240…d4e2</a></li><li class=\"vit-proof\"><span class=\"mono tnum vit-proof-at\">9 Nov, 19:04:54 UTC</span><span class=\"vit-proof-w\">Claim accepted: exploit replayed in TDX in 6.3 s, target paused</span><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0xfe46faea86254ae63eedfb3c859d928b1d08a9352b851c6b88ab262bcb7ea5d8\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Open on the explorer: 0xfe46faea86254ae63eedfb3c859d928b1d08a9352b851c6b88ab262bcb7ea5d8\">0xfe46faea…a5d8</a></li><li class=\"vit-proof\"><span class=\"mono tnum vit-proof-at\">9 Nov, 19:04:58 UTC</span><span class=\"vit-proof-w\">Hunter paid, report delivered, verdict written</span><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0xecbd089a092edd939ff646fae8d22c0f2616b6a92f58a49928c231c770bb807e\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Open on the explorer: 0xecbd089a092edd939ff646fae8d22c0f2616b6a92f58a49928c231c770bb807e\">0xecbd089a…807e</a></li><li class=\"vit-proof\"><span class=\"mono tnum vit-proof-at\">10 Nov, 23:01:50 UTC</span><span class=\"vit-proof-w\">Verified level: Proof of Cloud declaration checked on Arc (Ed25519), valid 7&#160;days</span><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0x3e2aa32251a7a7cfa7ee69c3fa653cac6dd4272db2ae92d1b4ed760178fdcd35\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Open on the explorer: 0x3e2aa32251a7a7cfa7ee69c3fa653cac6dd4272db2ae92d1b4ed760178fdcd35\">0x3e2aa322…cd35</a></li><li class=\"vit-proof\"><span class=\"mono tnum vit-proof-at\">11 Nov, 17:34:49 UTC</span><span class=\"vit-proof-w\">Verified level: enclave bound to its chip, ID read from Intel’s certificate on Arc</span><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0xd6928088d90f8bbc2585d04564c4a574312593f3f19792a1cdbf819437bb5f4f\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Open on the explorer: 0xd6928088d90f8bbc2585d04564c4a574312593f3f19792a1cdbf819437bb5f4f\">0xd6928088…5f4f</a></li><li class=\"vit-proof\"><span class=\"mono tnum vit-proof-at\">11 Nov, 17:36:09 UTC</span><span class=\"vit-proof-w\">Verified level: first bounty funded with 1&#160;USDC</span><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0x52278630d5f4118034d542101467102ce40befdd52d347faaf74cea6f6ee49fb\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Open on the explorer: 0x52278630d5f4118034d542101467102ce40befdd52d347faaf74cea6f6ee49fb\">0x52278630…49fb</a></li></ol><h3 class=\"vit-h3\">What people would use it for</h3><ul class=\"vit-uses\"><li>A perpetuals exchange on Arc funds a 20,000&#160;USDC pool on its vault contracts and pays only for exploits that replay. Zero reports to triage, its current programme unchanged.</li><li>A young Arc protocol posts a pool of 1,000 to 5,000&#160;USDC: the cheapest security it can buy, since it pays only if a flaw is proven.</li><li>A lending protocol accepts only verified-level machines for payouts above 10,000&#160;USDC, signed by two distinct operators.</li></ul></div><aside class=\"vit-side\"><div class=\"vit-side-b\"><h3 class=\"vit-h4\">Why a sealed machine</h3><p class=\"vit-side-why\">The hunter will not reveal the exploit before being paid, and the protocol will not pay before seeing proof. A sealed machine that both can check on Arc runs the exploit, then releases the payment and the report together. Nobody holds either side in between.</p></div><div class=\"vit-side-b\"><h3 class=\"vit-h4\">Price and who pays</h3><dl class=\"kv-list vit-kv vit-kv-side\"><div class=\"kv-row\"><dt>Who pays</dt><dd>The protocol, from a USDC pool it funds on Arc.</dd></div><div class=\"kv-row\"><dt>Per proven exploit</dt><dd>The tier, plus 10% to the network and 5% to the verifying operators. The hunter gets the whole tier.</dd></div><div class=\"kv-row\"><dt>Example</dt><dd>A 10,000&#160;USDC tier costs 11,500&#160;USDC, once, for a proven exploit. No proof, no payment.</dd></div><div class=\"kv-row\"><dt>Testnet demo</dt><dd>Pool 1&#160;USDC, one tier of 0.5&#160;USDC for a loss of at least 1&#160;USDC.</dd></div><div class=\"kv-row\"><dt>Pilot terms, a proposal</dt><dd>Pool 20,000&#160;USDC, tiers from 100 to 10,000&#160;USDC for losses from 1,000 to 100,000&#160;USDC.</dd></div></dl></div><div class=\"vit-side-b\"><h3 class=\"vit-h4\">Today</h3><p class=\"vit-side-today\"><span class=\"led led-amber\" aria-hidden=\"true\"></span>Running on the v3 stack: a proven claim can be replayed and paid now.</p><p class=\"lbl vit-k\">What still works</p><ul class=\"vit-still\"><li>Posting a bounty on Arc, which needs no machine.</li><li>The full paid run of 9 November, on the explorer.</li></ul></div><div class=\"vit-side-acts\"><a class=\"btn btn-main btn-s\" href=\"/space.html?tab=bounties\"><span>Post a bounty</span></a><a class=\"btn btn-line btn-s\" href=\"/network.html?focus=demo\"><span>Watch the replay</span></a><a class=\"tlink\" href=\"/doc.html?c=notary-robot\">How Arc checks it, in detail</a><a data-vt-ch=\"build\" class=\"tlink\" href=\"?c=build\">For developers</a></div></aside></div><div class=\"vit-fam-more\"><p class=\"lbl vit-k vit-more-k\">In detail</p><details class=\"vit-more\"><summary><span class=\"vit-more-t\">The problem, in numbers</span><span class=\"mono vit-more-n\">6</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><ul class=\"vit-list\"><li>Reports to Immunefi programmes rose 135% in 2025, and half of them were noise on triaged programmes.</li><li>At Cantina, 60 to 80% of submissions are invalid.</li><li>Immunefi audit contests were paid 26 to 63&#160;days after they closed.</li><li>$1.25B was stolen in the third quarter of 2026, about $270 for every $1 Immunefi paid in bounties that quarter.</li><li>The hunter must reveal the exploit before being paid, and the protocol must trust the report before paying.</li><li>$107.7M arrived on Arc with one exchange on 22 October, and none of Immunefi’s 219 public programmes mentioned Arc.</li></ul><p class=\"lbl muted vit-src-l\">Source: Our research of 1 November 2026: Immunefi, Cantina, DefiLlama.</p></div></details><details class=\"vit-more\"><summary><span class=\"vit-more-t\">Who buys it, and the evidence</span><span class=\"mono vit-more-n\">4</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><dl class=\"vit-personas\"><div><dt>Protocols on Arc that hold USDC in contracts</dt><dd>$107.7M arrived on Arc with one exchange in October. A pool turns a security budget into payouts for proven flaws only.</dd></div><div><dt>Security researchers</dt><dd>More than 85,000 on Immunefi. 160 of 180 programmes already require testing on a local fork only, which is exactly what the enclave does.</dd></div><div><dt>The Arc ecosystem</dt><dd>Arc runs its own bug bounty, up to $1M. The Sealed Bounty is the automatic version, paid in seconds.</dd></div><div><dt>Insurers and buyers who require datacenter-grade custody (verified level)</dt><dd>The product’s author sets the minimum operator level and the accepted auditors.</dd></div></dl></div></details><details class=\"vit-more\"><summary><span class=\"vit-more-t\">What is guaranteed, and by which check</span><span class=\"mono vit-more-n\">11</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><ul class=\"vit-guar\"><li><p class=\"vit-guar-w\">Paid only if an enclave Arc admitted for this product signed the claim, anchored on a recent real block.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Checked by</span> <code class=\"mono vit-code\">SealedBounty.acceptClaim, EnclaveRegistry.activeOperatorAt, History.blockHashAt (EIP-2935)</code></p></li><li><p class=\"vit-guar-w\">One exploit is paid once. A second payout needs a strictly higher tier and a later anchor.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Checked by</span> <code class=\"mono vit-code\">fingerprintPaid, TierAlreadyPaid, AnchorBeforeLastPayout</code></p></li><li><p class=\"vit-guar-w\">Above the bounty’s single cap, several distinct operators must sign the same claim.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Checked by</span> <code class=\"mono vit-code\">NeedMoreEnclaves (k, singleCap)</code></p></li><li><p class=\"vit-guar-w\">The report reaches the protocol encrypted, in the same transaction as the payment. A refused transfer becomes a credit to withdraw, never a failure.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Checked by</span> <code class=\"mono vit-code\">SealedBounty.deliver, ExploitDelivered, BountyPaid</code></p></li><li><p class=\"vit-guar-w\">What can be paid on enclaves’ word is capped: each signing operator’s even share counts, over any 24 hours, against half of its available bond (its bond minus any pending withdrawal) and against the product’s cap.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Checked by</span> <code class=\"mono vit-code\">OperatorBond.consumeExposure</code></p></li><li><p class=\"vit-guar-w\">A false claim can be refuted for 3&#160;days by at least 2 other operators: bond seized, payout cancelled, verdict 0.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Checked by</span> <code class=\"mono vit-code\">SealedBounty.refute, OperatorBond.slash</code></p></li><li><p class=\"vit-guar-w\">Nothing runs on the real chain: the exploit replays on a fork. Pausing the target is gas-bounded and cannot block the payout.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Checked by</span> <code class=\"mono vit-code\">_pauseTarget, capped at 100,000 gas</code></p></li><li><p class=\"vit-guar-w\">Verified level: only enclaves whose chip is bound and declared by an accepted auditor count, checked when the claim settles.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Checked by</span> <code class=\"mono vit-code\">PolicyEnclaves, MachineRegistry.meetsPolicy</code></p></li><li><p class=\"vit-guar-w\">Verified level: the chip ID is read from Intel’s own certificate, decoded exactly like Automata’s verifier.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Checked by</span> <code class=\"mono vit-code\">PckChip.chipOf, MachineRegistry.bindMachine</code></p></li><li><p class=\"vit-guar-w\">Verified level: the alliance’s signature is verified on Arc, not trusted from whoever submits it.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Checked by</span> <code class=\"mono vit-code\">ProofOfCloudAuditor, Ed25519Verifier</code></p></li><li><p class=\"vit-guar-w\">A new payment contract waits 8&#160;days before it can touch bonds or write verdicts, so operators can leave first.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Checked by</span> <code class=\"mono vit-code\">OperatorBond.SETTLEMENT_DELAY, VerdictLog.CALLER_DELAY</code></p></li></ul></div></details><details class=\"vit-more\"><summary><span class=\"vit-more-t\">Limits, said plainly</span><span class=\"mono vit-more-n\">6</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><ul class=\"vit-list\"><li>The fork’s state is read through a relay that re-hashes every block header and chains it to the anchor, but the state itself is not proven yet. State proofs are coded and tested (23&#160;tests), and switch on with an archive node.</li><li>Deterministic work only: an exploit replays identically, an AI answer does not.</li><li>One operator today, so one signature per claim in practice. Capacity follows bonds: 1&#160;USDC of bond covers 0.5&#160;USDC of payouts per 24 hours.</li><li>No KYC at payout yet, which many programmes require.</li><li>The demo target is our own deliberately vulnerable vault. No outside protocol has funded a pool yet.</li><li>Verified level: all verified enclaves sit on one machine for now.</li></ul></div></details></div>"},{"id":"private-ai","cls":"vit-sec vit-fam","k":"Products #1 and #3","t":"Private AI","plain":"Private AI","units":"#1 #3","body":"<header class=\"vit-fam-hd is-arc\"><h2 aria-label=\"Private AI\" class=\"vt-h vit-fam-name\" id=\"private-ai-h\">Private AI<span class=\"ttl-rule\" aria-hidden=\"true\"></span></h2><p class=\"vit-fam-head\">Private AI with a receipt for every answer.</p><p class=\"lede vit-fam-sub\">Chat with gpt-oss-120b through an enclave that Arc has verified. Your messages are encrypted for that enclave, so neither the operator nor ArcHive can read them. Pay by the session or by the call, in USDC, only for what you use.</p></header><ul class=\"vit-tiers\"><li class=\"vit-tier\" data-pid=\"1\"><span class=\"blade vit-face\" data-led=\"amber\" data-long=\"0\" aria-hidden=\"true\"><span class=\"blade-face\"><span class=\"bl-led\"><i></i></span><span class=\"bl-title\">Private AI</span><span class=\"bl-word\">Not running</span><span class=\"bl-u\">#1</span></span></span><h3 class=\"vit-tier-n\">Prepaid session</h3><dl class=\"kv-list vit-kv\"><div class=\"kv-row\"><dt>For</dt><dd>Apps and teams that ask many questions.</dd></div><div class=\"kv-row\"><dt>Price</dt><dd><span class=\"mono tnum vit-tag\">0.10 USDC per 1,000 tokens</span><span class=\"lbl muted vit-same\">testnet demo price</span></dd></div><div class=\"kv-row\"><dt>How you pay</dt><dd>One deposit, signed once. The operator is paid from signed receipts, and the rest comes back when you close.</dd></div><div class=\"kv-row\"><dt>Contract</dt><dd><a class=\"tlink vit-addr\" href=\"https://explorer.testnet.arc.io/address/0x606c379cd8758E3562e7ECC9972d0feF693F0763\" target=\"_blank\" rel=\"noreferrer\"><span>SessionPay</span> <span class=\"mono\">0x606c…0763</span></a></dd></div></dl><div class=\"vit-tier-go\"><a class=\"btn btn-main btn-s\" href=\"/space.html?tab=sessions&amp;p=1\"><span>Open a session</span></a></div></li><li class=\"vit-tier\" data-pid=\"3\"><span class=\"blade vit-face\" data-led=\"amber\" data-long=\"1\" aria-hidden=\"true\"><span class=\"blade-face\"><span class=\"bl-led\"><i></i></span><span class=\"bl-title\">Private AI, per call</span><span class=\"bl-word\">Not running</span><span class=\"bl-u\">#3</span></span></span><h3 class=\"vit-tier-n\">Pay per call, x402</h3><dl class=\"kv-list vit-kv\"><div class=\"kv-row\"><dt>For</dt><dd>AI agents, bots and scripts.</dd></div><div class=\"kv-row\"><dt>Price</dt><dd><span class=\"mono tnum vit-tag\">0.01 USDC per call</span><span class=\"lbl muted vit-same\">read on Arc</span></dd></div><div class=\"kv-row\"><dt>How you pay</dt><dd>One signature per call. No account, no deposit, no gas: the operator settles on Arc about 20&#160;seconds later.</dd></div><div class=\"kv-row\"><dt>Contract</dt><dd><a class=\"tlink vit-addr\" href=\"https://explorer.testnet.arc.io/address/0x89B0381B18536f680fD952a0E7D375d7a4EC3fe6\" target=\"_blank\" rel=\"noreferrer\"><span>X402Settler</span> <span class=\"mono\">0x89B0…3fe6</span></a></dd></div></dl><div class=\"vit-tier-go\"><a class=\"btn btn-main btn-s\" href=\"/network.html?focus=use&amp;p=3\"><span>Make a paid call</span></a></div></li></ul><div class=\"vit-fam-body\"><div class=\"vit-fam-main\"><h3 class=\"vit-h3\">How it works</h3><ol class=\"path vit-steps\"><li class=\"row path-s\"><span class=\"path-n mono\" aria-hidden=\"true\">01</span><div class=\"path-b\"><h4 class=\"path-t\">Pay once, or per call</h4><p class=\"path-d\">A session takes one deposit, signed once, with no approval step. A call carries its own signed authorization for the exact price. Price and model are fixed when you start.</p><p class=\"vit-step-c\"><code class=\"mono vit-code\">SessionPay.openSession, X402Settler (EIP-3009)</code></p></div></li><li class=\"row path-s\"><span class=\"path-n mono\" aria-hidden=\"true\">02</span><div class=\"path-b\"><h4 class=\"path-t\">Your app checks the machine on Arc</h4><p class=\"path-d\">It reads the enclave’s key on Arc, where only machines verified through Intel and running an allowed image are listed, and encrypts the question for it. The operator and our server only relay ciphertext.</p><p class=\"vit-step-c\"><code class=\"mono vit-code\">EnclaveRegistry, HPKE</code></p></div></li><li class=\"row path-s\"><span class=\"path-n mono\" aria-hidden=\"true\">03</span><div class=\"path-b\"><h4 class=\"path-t\">The enclave checks the model, then answers</h4><p class=\"path-d\">Before each call it verifies the model provider’s own enclave and pins its key. Then it calls gpt-oss-120b and seals the answer for you, with a receipt signed by a key born inside the enclave.</p><p class=\"vit-step-c\"><code class=\"mono vit-code\">EIP-712 receipt</code></p></div></li><li class=\"row path-s\"><span class=\"path-n mono\" aria-hidden=\"true\">04</span><div class=\"path-b\"><h4 class=\"path-t\">The operator settles from receipts</h4><p class=\"path-d\">One transaction pays everything owed so far, split 95% to the operator and 5% to the network. A call settles about 20&#160;seconds after its answer.</p><p class=\"vit-step-c\"><code class=\"mono vit-code\">SessionPay.settle, X402Settler.settle</code></p></div></li><li class=\"row path-s\"><span class=\"path-n mono\" aria-hidden=\"true\">05</span><div class=\"path-b\"><h4 class=\"path-t\">Close: refund and verdict</h4><p class=\"path-d\">The unused deposit comes back, and an ERC-8004 verdict is written for the operator, in the same transaction.</p><p class=\"vit-step-c\"><code class=\"mono vit-code\">SessionPay.closeSession, VerdictLog</code></p></div></li></ol><h3 class=\"vit-h3\">Proof on Arc</h3><p class=\"lbl muted vit-h3-l\">Real transactions on Arc testnet, made on the v2.1 stack before the switch to v3. Each one opens on the explorer.</p><div class=\"vit-rcpts is-two\"><figure class=\"vit-rcpt is-arc\"><figcaption class=\"vit-rcpt-h\"><span class=\"vit-rcpt-t\">Session receipt</span><span class=\"mono tnum vit-rcpt-d\">9 Nov 2026, 19:12:01 UTC</span></figcaption><dl class=\"vit-rcpt-l\"><div><dt>Deposit</dt><dd class=\"mono tnum\">1.0000<span class=\"vit-u\"> USDC</span></dd></div><div><dt>Used: 994 tokens at 0.10 USDC per 1,000</dt><dd class=\"mono tnum\">0.0994<span class=\"vit-u\"> USDC</span></dd></div><div class=\"is-sub\"><dt>of which operator, 95%</dt><dd class=\"mono tnum\">0.09443<span class=\"vit-u\"> USDC</span></dd></div><div class=\"is-sub\"><dt>of which network, 5%</dt><dd class=\"mono tnum\">0.00497<span class=\"vit-u\"> USDC</span></dd></div><div class=\"is-total\"><dt>Refunded at close</dt><dd class=\"mono tnum\">0.9006<span class=\"vit-u\"> USDC</span></dd></div><div class=\"is-extra\"><dt>ERC-8004 verdict</dt><dd class=\"mono tnum\">100</dd></div></dl><p class=\"vit-rcpt-n\">3 encrypted answers, settled by the operator without the client. Closed with refund and verdict in one transaction.</p><p class=\"vit-rcpt-x\"><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0x9430e16a5cff9bd099c0a7a5f2b11dc87e4c11ad6444a0cd9c87f71ee72f1bb4\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Open on the explorer: 0x9430e16a5cff9bd099c0a7a5f2b11dc87e4c11ad6444a0cd9c87f71ee72f1bb4\">0x9430e16a…1bb4</a><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0xb8299f0698992da535648b14fe1cdd59231ade96b70a515acd7314afc2c8d62f\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Open on the explorer: 0xb8299f0698992da535648b14fe1cdd59231ade96b70a515acd7314afc2c8d62f\">0xb8299f06…d62f</a></p></figure><figure class=\"vit-rcpt is-arc\"><figcaption class=\"vit-rcpt-h\"><span class=\"vit-rcpt-t\">Call receipt</span><span class=\"mono tnum vit-rcpt-d\">9 Nov 2026, 19:25:38 UTC</span></figcaption><dl class=\"vit-rcpt-l\"><div><dt>Operator, 95%</dt><dd class=\"mono tnum\">0.0095<span class=\"vit-u\"> USDC</span></dd></div><div><dt>Network, 5%</dt><dd class=\"mono tnum\">0.0005<span class=\"vit-u\"> USDC</span></dd></div><div class=\"is-total\"><dt>One call, signed in the browser</dt><dd class=\"mono tnum\">0.0100<span class=\"vit-u\"> USDC</span></dd></div></dl><p class=\"vit-rcpt-n\">Settled by the operator about 20&#160;seconds after the answer. The payer paid no gas.</p><p class=\"vit-rcpt-x\"><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0xa41f1276a9f0b0af98d1991ae1ab06e5f1afb3d9bed71bca486ccea7255c15d9\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Open on the explorer: 0xa41f1276a9f0b0af98d1991ae1ab06e5f1afb3d9bed71bca486ccea7255c15d9\">0xa41f1276…15d9</a></p></figure></div><ol class=\"vit-proofs\"><li class=\"vit-proof\"><span class=\"mono tnum vit-proof-at\">9 Nov, 18:57:24 UTC</span><span class=\"vit-proof-w\">Inference enclave admitted: Arc verified Intel’s signature and replayed its boot log, for 0.1717&#160;USDC of gas</span><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0x199c985dee537cfe2948f6c721ad1bdd448d538ff08bc8e93a79036a25f33499\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Open on the explorer: 0x199c985dee537cfe2948f6c721ad1bdd448d538ff08bc8e93a79036a25f33499\">0x199c985d…3499</a></li><li class=\"vit-proof\"><span class=\"mono tnum vit-proof-at\">9 Nov, 19:04:13 UTC</span><span class=\"vit-proof-w\">Session opened with a 1&#160;USDC deposit</span><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0x63f6a544d36766b6cb01aab313b223739a04c706c24255ca6d38358b3ed2afd6\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Open on the explorer: 0x63f6a544d36766b6cb01aab313b223739a04c706c24255ca6d38358b3ed2afd6\">0x63f6a544…afd6</a></li><li class=\"vit-proof\"><span class=\"mono tnum vit-proof-at\">9 Nov, 19:12:01 UTC</span><span class=\"vit-proof-w\">3 answers settled: 0.0994&#160;USDC</span><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0x9430e16a5cff9bd099c0a7a5f2b11dc87e4c11ad6444a0cd9c87f71ee72f1bb4\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Open on the explorer: 0x9430e16a5cff9bd099c0a7a5f2b11dc87e4c11ad6444a0cd9c87f71ee72f1bb4\">0x9430e16a…1bb4</a></li><li class=\"vit-proof\"><span class=\"mono tnum vit-proof-at\">9 Nov, 19:25:38 UTC</span><span class=\"vit-proof-w\">A paid call from the browser: 0.01&#160;USDC</span><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0xa41f1276a9f0b0af98d1991ae1ab06e5f1afb3d9bed71bca486ccea7255c15d9\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Open on the explorer: 0xa41f1276a9f0b0af98d1991ae1ab06e5f1afb3d9bed71bca486ccea7255c15d9\">0xa41f1276…15d9</a></li><li class=\"vit-proof\"><span class=\"mono tnum vit-proof-at\">9 Nov, 21:04:29 UTC</span><span class=\"vit-proof-w\">Session closed: 0.9006&#160;USDC refunded, verdict 100</span><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0xb8299f0698992da535648b14fe1cdd59231ade96b70a515acd7314afc2c8d62f\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Open on the explorer: 0xb8299f0698992da535648b14fe1cdd59231ade96b70a515acd7314afc2c8d62f\">0xb8299f06…d62f</a></li><li class=\"vit-proof\"><span class=\"mono tnum vit-proof-at\">10 Nov, 21:43:14 UTC</span><span class=\"vit-proof-w\">Enclave admitted again with the image that verifies the model provider before each call</span><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0xbd5cb0616dae27f9b614ffa6c6eea28423030932c017f9f910099b0129e19a75\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Open on the explorer: 0xbd5cb0616dae27f9b614ffa6c6eea28423030932c017f9f910099b0129e19a75\">0xbd5cb061…9a75</a></li><li class=\"vit-proof\"><span class=\"mono tnum vit-proof-at\">10 Nov, 21:45:24 UTC</span><span class=\"vit-proof-w\">A paid call through that enclave</span><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0x1995e88440bf443b32b9df7c1975c7a94ea003bc465999b34cc440570ea978ed\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Open on the explorer: 0x1995e88440bf443b32b9df7c1975c7a94ea003bc465999b34cc440570ea978ed\">0x1995e884…78ed</a></li></ol><h3 class=\"vit-h3\">What people would use it for</h3><ul class=\"vit-uses\"><li>A law firm summarises 40 confidential contracts: prompts encrypted for a verified enclave, one receipt per answer, 5&#160;USDC prepaid, the rest refunded at close.</li><li>A DeFi credit protocol runs underwriting questions on borrower files. Each decision carries an enclave-signed receipt it can show an auditor or a regulator.</li><li>A research agent buys three private answers for 0.03&#160;USDC in total while comparing providers: no API key, no sign-up.</li></ul></div><aside class=\"vit-side\"><div class=\"vit-side-b\"><h3 class=\"vit-h4\">Why a sealed machine</h3><p class=\"vit-side-why\">Your prompt must stay unreadable by the operator who runs the machine, and by us. Only hardware isolation, plus an attestation the contract checks, gives that. And the receipt ties each payment to that verified machine.</p></div><div class=\"vit-side-b\"><h3 class=\"vit-h4\">Price and who pays</h3><dl class=\"kv-list vit-kv vit-kv-side\"><div class=\"kv-row\"><dt>Session</dt><dd><span class=\"mono tnum vit-tag\">0.10 USDC per 1,000 tokens</span><span class=\"lbl muted vit-same\">testnet demo price, set high so every payment shows on the explorer</span></dd></div><div class=\"kv-row\"><dt>Per call, x402</dt><dd><span class=\"mono tnum vit-tag\">0.01 USDC per call</span><span class=\"lbl muted vit-same\">read on Arc</span></dd></div><div class=\"kv-row\"><dt>Split</dt><dd>95% operator, 5% network</dd></div><div class=\"kv-row\"><dt>Who pays</dt><dd>The user or the agent, from its own wallet. A deposit stays in the contract and the unused part comes back.</dd></div><div class=\"kv-row\"><dt>Planned mainnet price, a proposal</dt><dd>About $0.20 per million input tokens and $0.80 per million output tokens. Calls from 0.10&#160;USDC, below that a session.</dd></div></dl></div><div class=\"vit-side-b\"><h3 class=\"vit-h4\">Today</h3><p class=\"vit-side-today\"><span class=\"led led-amber\" aria-hidden=\"true\"></span>Running on the v3 stack: sessions and per-call payments can be made now.</p><p class=\"lbl vit-k\">What still works</p><ul class=\"vit-still\"><li>The proof chain (GET /api/proof) and receipt checks (POST /api/verify-receipt).</li><li>Every contract and past payment, on the explorer.</li><li>The SDK client code, in the repository.</li></ul></div><div class=\"vit-side-acts\"><a class=\"btn btn-main btn-s\" href=\"/space.html?tab=sessions&amp;p=1\"><span>Open a session</span></a><a class=\"btn btn-line btn-s\" href=\"/network.html?focus=demo\"><span>Watch the replay</span></a><a class=\"tlink\" href=\"/doc.html?c=privacy\">How Arc checks it, in detail</a><a data-vt-ch=\"build\" class=\"tlink\" href=\"?c=build\">For developers</a></div></aside></div><div class=\"vit-fam-more\"><p class=\"lbl vit-k vit-more-k\">In detail</p><details class=\"vit-more\"><summary><span class=\"vit-more-t\">The problem, in numbers</span><span class=\"mono vit-more-n\">4</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><ul class=\"vit-list\"><li>Legal files, health records, credit files and unreleased code cannot go to an ordinary AI API: nobody can check who reads the prompt, and nothing proves what was paid for.</li><li>Apple, Google and Meta made attested confidential AI the norm for their own users. An independent developer cannot buy the same thing per use, in USDC, with a contract that checks it.</li><li>In the EU, credit-scoring AI must log its events automatically from 2 December 2027 (AI Act, article 12).</li><li>Agents cannot open accounts or type card numbers. x402 lets them pay per request, but they still get no proof that a verified machine served the call.</li></ul><p class=\"lbl muted vit-src-l\">Source: Our research of 1 November 2026: provider pages, the EU AI Act.</p></div></details><details class=\"vit-more\"><summary><span class=\"vit-more-t\">Who buys it, and the evidence</span><span class=\"mono vit-more-n\">4</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><dl class=\"vit-personas\"><div><dt>Law firms and legal teams</dt><dd>They must keep client documents privileged. Enclave AI providers already sell to them, and they name privacy as the biggest barrier to using more AI.</dd></div><div><dt>Credit, KYC and fraud teams, DeFi credit included</dt><dd>In the EU their AI must log its decisions from December 2027. Two 2026 Arc hackathon winners already ran underwriting AI in rented enclaves.</dd></div><div><dt>Auditors and developers with private code</dt><dd>They want an LLM to read code that nobody, not even the host, can see.</dd></div><div><dt>Builders of AI agents</dt><dd>One signature per call, no account and no deposit: an agent can pay on its own.</dd></div></dl></div></details><details class=\"vit-more\"><summary><span class=\"vit-more-t\">What is guaranteed, and by which check</span><span class=\"mono vit-more-n\">8</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><ul class=\"vit-guar\"><li><p class=\"vit-guar-w\">Only an enclave admitted by Arc (Intel signature, allowed image, bonded operator) can sign a receipt that gets paid.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Checked by</span> <code class=\"mono vit-code\">SessionPay.settle, EnclaveRegistry.activeOperatorAt</code></p></li><li><p class=\"vit-guar-w\">A session is tied to one enclave and one operator. Price, model and billing unit are frozen when it opens.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Checked by</span> <code class=\"mono vit-code\">WrongEnclave, WrongOperator, ModelMismatch</code></p></li><li><p class=\"vit-guar-w\">You can never be charged more than your deposit. The rest comes back at close.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Checked by</span> <code class=\"mono vit-code\">SessionPay.settle, SessionPay.closeSession</code></p></li><li><p class=\"vit-guar-w\">Two different receipts for the same step prove cheating: the whole bond is seized, half to the reporter and half to the victim, and the operator is banned.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Checked by</span> <code class=\"mono vit-code\">SessionPay.reportEquivocation, OperatorBond.slash</code></p></li><li><p class=\"vit-guar-w\">What an operator can collect on its enclaves’ word alone is capped: half its available bond (its bond minus any pending withdrawal) over any 24 hours, and 10&#160;USDC per product over the same 24 hours on testnet.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Checked by</span> <code class=\"mono vit-code\">OperatorBond.consumeExposure</code></p></li><li><p class=\"vit-guar-w\">One signed authorization pays exactly one call, for exactly its price, and cannot be replayed.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Checked by</span> <code class=\"mono vit-code\">X402Settler.settle, receiveWithAuthorization</code></p></li><li><p class=\"vit-guar-w\">Your app refuses to encrypt for a key Arc does not know.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Checked by</span> <code class=\"mono vit-code\">the SDK reads EnclaveRegistry first</code></p></li><li class=\"is-not\"><p class=\"vit-guar-w\">Not guaranteed: that the AI’s answer is right. A machine cannot check an answer, so it is never grounds for seizing a bond.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Checked by</span> <code class=\"mono vit-code\">by design</code></p></li></ul></div></details><details class=\"vit-more\"><summary><span class=\"vit-more-t\">Limits, said plainly</span><span class=\"mono vit-more-n\">6</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><ul class=\"vit-list\"><li>The model does not run inside our enclave. Our enclave verifies the model provider’s own enclave (RedPill’s gateway, gpt-oss-120b served by Tinfoil) before each call. Still trusted: that gateway’s code, its own check upstream, Phala’s collateral service and the key custody of its stack.</li><li>The testnet price, 100&#160;USDC per million tokens, is about 500 times our planned mainnet price for input tokens.</li><li>One operator on one physical machine: not decentralised yet.</li><li>Every payer so far is our own wallet. No outside customer has paid yet.</li><li>A receipt inflated by a forged enclave cannot be proven false: the bond caps the damage per 24 hours, it does not refund it.</li><li>Standard x402 clients cannot call it, because the request is encrypted: use the ArcHive SDK.</li></ul></div></details></div>"},{"id":"attested-copilot","cls":"vit-sec vit-fam","k":"Product #4","t":"Attested Copilot","plain":"Attested Copilot","units":"#4","body":"<header class=\"vit-fam-hd is-arc\"><h2 aria-label=\"Attested Copilot\" class=\"vt-h vit-fam-name\" id=\"copilot-h\">Attested Copilot<span class=\"ttl-rule\" aria-hidden=\"true\"></span></h2><p class=\"vit-fam-head\">An assistant you can verify.</p><p class=\"lede vit-fam-sub\">AskHive, the ArcHive assistant, in its own enclave. Your browser checks its key on Arc and encrypts the whole conversation for it, so our web server only relays ciphertext. It is free.</p></header><ul class=\"vit-tiers is-one\"><li class=\"vit-tier\" data-pid=\"4\"><span class=\"blade vit-face\" data-led=\"amber\" data-long=\"0\" aria-hidden=\"true\"><span class=\"blade-face\"><span class=\"bl-led\"><i></i></span><span class=\"bl-title\">Copilot</span><span class=\"bl-word\">Not running</span><span class=\"bl-u\">#4</span></span></span><h3 class=\"vit-tier-n\">Attested Copilot</h3><dl class=\"kv-list vit-kv\"><div class=\"kv-row\"><dt>For</dt><dd>Anyone who wants help on ArcHive without trusting our server.</dd></div><div class=\"kv-row\"><dt>What it does</dt><dd>It explains, shows you the site and prepares what you sign. Nothing is spent without your signature.</dd></div><div class=\"kv-row\"><dt>Price</dt><dd>Free, product price 0 on Arc</dd></div><div class=\"kv-row\"><dt>Contract</dt><dd><a class=\"tlink vit-addr\" href=\"https://explorer.testnet.arc.io/address/0xc854ebA7C28f4b53f50018EAcF40D617Ba76e38E\" target=\"_blank\" rel=\"noreferrer\"><span>EnclaveRegistry</span> <span class=\"mono\">0xc854…e38E</span></a></dd></div></dl><div class=\"vit-tier-go\"><a data-vt-copilot=\"\" class=\"btn btn-main btn-s\" href=\"#copilot\"><span>Ask the copilot</span></a></div></li></ul><div class=\"vit-fam-body\"><div class=\"vit-fam-main\"><h3 class=\"vit-h3\">How it works</h3><ol class=\"path vit-steps\"><li class=\"row path-s\"><span class=\"path-n mono\" aria-hidden=\"true\">01</span><div class=\"path-b\"><h4 class=\"path-t\">Your browser reads the copilot on Arc</h4><p class=\"path-d\">It reads product 4’s enclave on Arc, its image fingerprint and its operator, and checks its key.</p><p class=\"vit-step-c\"><code class=\"mono vit-code\">EnclaveRegistry</code></p></div></li><li class=\"row path-s\"><span class=\"path-n mono\" aria-hidden=\"true\">02</span><div class=\"path-b\"><h4 class=\"path-t\">It encrypts your question for that key</h4><p class=\"path-d\">The site’s proxy only forwards ciphertext, and the enclave accepts questions only through that proxy.</p><p class=\"vit-step-c\"><code class=\"mono vit-code\">HPKE</code></p></div></li><li class=\"row path-s\"><span class=\"path-n mono\" aria-hidden=\"true\">03</span><div class=\"path-b\"><h4 class=\"path-t\">The enclave answers, sealed for you</h4><p class=\"path-d\">It verifies the model provider first, answers, and seals the reply for your browser.</p><p class=\"vit-step-c\"><code class=\"mono vit-code\">RedPill gateway</code></p></div></li><li class=\"row path-s\"><span class=\"path-n mono\" aria-hidden=\"true\">04</span><div class=\"path-b\"><h4 class=\"path-t\">Its instructions cannot change in silence</h4><p class=\"path-d\">New instructions mean a new image, a new fingerprint and a new registration on Arc.</p><p class=\"vit-step-c\"><code class=\"mono vit-code\">ProductRegistry.isWorkloadAllowed</code></p></div></li></ol><h3 class=\"vit-h3\">Proof on Arc</h3><p class=\"lbl muted vit-h3-l\">Real transactions on Arc testnet, made on the v2.1 stack before the switch to v3. Each one opens on the explorer.</p><div class=\"vit-rcpts\"><figure class=\"vit-rcpt is-arc\"><figcaption class=\"vit-rcpt-h\"><span class=\"vit-rcpt-t\">Admission on Arc</span><span class=\"mono tnum vit-rcpt-d\">10 Nov 2026, 22:01:26 UTC</span></figcaption><dl class=\"vit-rcpt-l\"><div><dt>Intel’s signature on the machine</dt><dd class=\"mono tnum\">verified</dd></div><div><dt>Boot log, byte by byte</dt><dd class=\"mono tnum\">replayed</dd></div><div><dt>Image fingerprint</dt><dd class=\"mono tnum\">allowed</dd></div><div class=\"is-total\"><dt>Gas, paid by the operator</dt><dd class=\"mono tnum\">6,849,050</dd></div></dl><p class=\"vit-rcpt-n\">The copilot’s enclave, with the image that verifies its model provider. End to end on 9 November: key checked on Arc, encrypted question, sealed answer, in English and French.</p><p class=\"vit-rcpt-x\"><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0xad8b9780689513b1f68b8aba1a99f1b3156b4038a86aff46cad5ff96e294005e\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Open on the explorer: 0xad8b9780689513b1f68b8aba1a99f1b3156b4038a86aff46cad5ff96e294005e\">0xad8b9780…005e</a></p></figure></div><ol class=\"vit-proofs\"><li class=\"vit-proof\"><span class=\"mono tnum vit-proof-at\">10 Nov, 22:01:26 UTC</span><span class=\"vit-proof-w\">Copilot enclave admitted through Intel’s signature and a replay of its boot log</span><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0xad8b9780689513b1f68b8aba1a99f1b3156b4038a86aff46cad5ff96e294005e\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Open on the explorer: 0xad8b9780689513b1f68b8aba1a99f1b3156b4038a86aff46cad5ff96e294005e\">0xad8b9780…005e</a></li><li class=\"vit-proof\"><span class=\"mono tnum vit-proof-at\">19 Nov, 22:37:58 UTC</span><span class=\"vit-proof-w\">AskHive’s enclave admitted again, the same way</span><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0xde9628b23d0483bb666a0cd13c55c4f32a1204151323a80da9451b0aeb330176\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Open on the explorer: 0xde9628b23d0483bb666a0cd13c55c4f32a1204151323a80da9451b0aeb330176\">0xde9628b2…0176</a></li></ol><h3 class=\"vit-h3\">What people would use it for</h3><ul class=\"vit-uses\"><li>A user asks whether an enclave is verified and what a bond would cost, without the site learning their strategy.</li><li>A DAO help desk runs the same pattern: members can check which prompt and knowledge base they are talking to.</li><li>Operator and author onboarding: the copilot explains each step and prepares the transaction, the human signs.</li></ul></div><aside class=\"vit-side\"><div class=\"vit-side-b\"><h3 class=\"vit-h4\">Why a sealed machine</h3><p class=\"vit-side-why\">The assistant’s instructions are measured, so they cannot change in silence, and the conversation is sealed from our web server.</p></div><div class=\"vit-side-b\"><h3 class=\"vit-h4\">Price and who pays</h3><dl class=\"kv-list vit-kv vit-kv-side\"><div class=\"kv-row\"><dt>Price</dt><dd>Free: product 4 has a price of 0 on Arc.</dd></div><div class=\"kv-row\"><dt>Who pays</dt><dd>Nobody. No wallet is needed to ask.</dd></div></dl></div><div class=\"vit-side-b\"><h3 class=\"vit-h4\">Today</h3><p class=\"vit-side-today\"><span class=\"led led-amber\" aria-hidden=\"true\"></span>AskHive, the assistant in the corner of every page, runs in this enclave. It shows pages while it explains, and it prepares operations you sign with your own wallet.</p><p class=\"lbl vit-k\">Where to find it</p><ul class=\"vit-still\"><li>AskHive, in the corner of every page.</li><li>Its registration and its image, readable on Arc.</li></ul></div><div class=\"vit-side-acts\"><a data-vt-copilot=\"\" class=\"btn btn-main btn-s\" href=\"#copilot\"><span>Ask the copilot</span></a><a class=\"btn btn-line btn-s\" href=\"/network.html?focus=demo\"><span>Watch the replay</span></a><a class=\"tlink\" href=\"/doc.html\">How Arc checks it, in detail</a><a data-vt-ch=\"build\" class=\"tlink\" href=\"?c=build\">For developers</a></div></aside></div><div class=\"vit-fam-more\"><p class=\"lbl vit-k vit-more-k\">In detail</p><details class=\"vit-more\"><summary><span class=\"vit-more-t\">The problem, in numbers</span><span class=\"mono vit-more-n\">1</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><ul class=\"vit-list\"><li>A website’s assistant sees everything you type, and the site can change what it says. You can check neither.</li></ul><p class=\"lbl muted vit-src-l\">Source: Our analysis.</p></div></details><details class=\"vit-more\"><summary><span class=\"vit-more-t\">Who buys it, and the evidence</span><span class=\"mono vit-more-n\">3</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><dl class=\"vit-personas\"><div><dt>Wallet and dApp users with sensitive questions</dt><dd>The server in between sees ciphertext only.</dd></div><div><dt>Teams that want a support assistant they can audit</dt><dd>The copilot’s image, its prompt included, is pinned on Arc by its fingerprint. Each change of prompt has meant a new image.</dd></div><div><dt>Judges and developers exploring ArcHive</dt><dd>Free, and in the corner of every page.</dd></div></dl></div></details><details class=\"vit-more\"><summary><span class=\"vit-more-t\">What is guaranteed, and by which check</span><span class=\"mono vit-more-n\">4</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><ul class=\"vit-guar\"><li><p class=\"vit-guar-w\">Your browser talks only to a key Arc admitted for product 4, with an allowed image.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Checked by</span> <code class=\"mono vit-code\">EnclaveRegistry, read by your browser</code></p></li><li><p class=\"vit-guar-w\">Our web server cannot read the conversation.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Checked by</span> <code class=\"mono vit-code\">HPKE, to the enclave’s key</code></p></li><li><p class=\"vit-guar-w\">Changing its instructions means a new image, a new fingerprint and a new registration on Arc.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Checked by</span> <code class=\"mono vit-code\">ProductRegistry.isWorkloadAllowed</code></p></li><li class=\"is-not\"><p class=\"vit-guar-w\">Not guaranteed: that answers are right. The model provider’s attested enclaves see the conversation.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Checked by</span> <code class=\"mono vit-code\">by design</code></p></li></ul></div></details><details class=\"vit-more\"><summary><span class=\"vit-more-t\">Limits, said plainly</span><span class=\"mono vit-more-n\">2</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><ul class=\"vit-list\"><li>It explains and prepares, it never signs.</li><li>Its knowledge can lag behind the product.</li></ul></div></details></div>"},{"id":"refutation","cls":"vit-sec vit-fam is-red","k":"v2.1 product #5","t":"Cheating costs","plain":"Cheating costs","units":"v2.1 #5","body":"<header class=\"vit-fam-hd is-red\"><h2 aria-label=\"Cheating costs\" class=\"vt-h vit-fam-name\" id=\"refutation-h\">Cheating costs<span class=\"ttl-rule\" aria-hidden=\"true\"></span></h2><p class=\"vit-fam-head\">Cheat, and the bond is gone.</p><p class=\"lede vit-fam-sub\">A real test on Arc, on the v2.1 stack, where it was product 5: an enclave built to lie inflated a loss. Two other enclaves replayed the exploit and proved the claim false. Nothing was paid, the liar’s whole bond was seized and its operator banned.</p></header><div class=\"vit-refute\" data-pid=\"v21-5\"><span class=\"blade vit-face\" data-led=\"red\" data-long=\"0\" aria-hidden=\"true\"><span class=\"blade-face\"><span class=\"bl-led\"><i></i></span><span class=\"bl-title\">Caught lying</span><span class=\"bl-word\">Bond seized</span><span class=\"bl-u\">v2.1 #5</span></span></span><div class=\"vit-tl-w\"><p class=\"lbl vit-k\">Four transactions, 10 November 2026, UTC</p><ol class=\"vit-tl\"><li class=\"row\"><span class=\"mono tnum vit-tl-at\">00:06:17</span><div class=\"vit-tl-b\"><h3 class=\"vit-tl-t\">The liar is admitted like any other</h3><p class=\"vit-tl-d\">Its faulty image is measured by Intel and Arc, not hidden. Three operators with a 1&#160;USDC bond each: one lies, two are honest.</p><p class=\"vit-tl-x\"><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0xd73094e863eccd11500410b8041ba696b7a63d0628d9ac8d077d89434b98a23e\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Open on the explorer: 0xd73094e863eccd11500410b8041ba696b7a63d0628d9ac8d077d89434b98a23e\">0xd73094e8…a23e</a></p></div></li><li class=\"row\"><span class=\"mono tnum vit-tl-at\">00:07:12</span><div class=\"vit-tl-b\"><h3 class=\"vit-tl-t\">A bounty is posted</h3><p class=\"vit-tl-d\">Pool 1&#160;USDC, tier 0.5&#160;USDC for a loss of at least 1&#160;USDC, on a demo vault holding 1&#160;USDC.</p><p class=\"vit-tl-x\"><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0x1b8511cc75871cf79e09b011a0598fc333cba4a0900155ce6c7acbaafaa2de99\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Open on the explorer: 0x1b8511cc75871cf79e09b011a0598fc333cba4a0900155ce6c7acbaafaa2de99\">0x1b8511cc…de99</a></p></div></li><li class=\"row\"><span class=\"mono tnum vit-tl-at\">00:07:24</span><div class=\"vit-tl-b\"><h3 class=\"vit-tl-t\">The lie is accepted</h3><p class=\"vit-tl-d\">The liar claims a 2&#160;USDC loss. Arc checks its signature and accepts the claim: the payout is reserved, not paid.</p><p class=\"vit-tl-x\"><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0x6aee80e974458ba251d75d7d82f8bfe361006fc328fc1416816221a2e76eb0ea\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Open on the explorer: 0x6aee80e974458ba251d75d7d82f8bfe361006fc328fc1416816221a2e76eb0ea\">0x6aee80e9…b0ea</a><span class=\"lbl muted\">block 71,620,107</span></p></div></li><li class=\"row\"><span class=\"mono tnum vit-tl-at\">00:07:40</span><div class=\"vit-tl-b\"><h3 class=\"vit-tl-t\">Refuted, 16&#160;seconds later</h3><p class=\"vit-tl-d\">The two honest enclaves replay the exploit at the same block and find a 1&#160;USDC loss. The contract seizes the liar’s whole bond, bans its operator, restores the pool and writes verdict 0.</p><p class=\"vit-tl-x\"><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0x0ffca5433186735bf5525e525995f3589d842681da8ffcaa82acb5993025051f\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Open on the explorer: 0x0ffca5433186735bf5525e525995f3589d842681da8ffcaa82acb5993025051f\">0x0ffca543…051f</a><span class=\"lbl muted\">block 71,620,138</span></p></div></li></ol></div></div><div class=\"vit-fam-body\"><div class=\"vit-fam-main\"><h3 class=\"vit-h3\">Proof on Arc</h3><p class=\"lbl muted vit-h3-l\">Real transactions on Arc testnet, made on the v2.1 stack before the switch to v3. Each one opens on the explorer.</p><div class=\"vit-rcpts\"><figure class=\"vit-rcpt is-red\"><figcaption class=\"vit-rcpt-h\"><span class=\"vit-rcpt-t\">Refutation receipt</span><span class=\"mono tnum vit-rcpt-d\">10 Nov 2026, 00:07:40 UTC</span></figcaption><dl class=\"vit-rcpt-l\"><div><dt>Loss claimed by the liar</dt><dd class=\"mono tnum\">2.00<span class=\"vit-u\"> USDC</span></dd></div><div><dt>Real loss, replayed by 2 other operators</dt><dd class=\"mono tnum\">1.00<span class=\"vit-u\"> USDC</span></dd></div><div><dt>Paid to the liar</dt><dd class=\"mono tnum\">0.00<span class=\"vit-u\"> USDC</span></dd></div><div class=\"is-total\"><dt>Bond seized</dt><dd class=\"mono tnum\">1.00<span class=\"vit-u\"> USDC</span></dd></div><div class=\"is-extra\"><dt>to whoever proved it</dt><dd class=\"mono tnum\">0.50&#160;USDC</dd></div><div class=\"is-extra\"><dt>to the victim</dt><dd class=\"mono tnum\">0.50&#160;USDC</dd></div><div class=\"is-extra\"><dt>Operator</dt><dd class=\"mono tnum\">banned</dd></div><div class=\"is-extra\"><dt>ERC-8004 verdict</dt><dd class=\"mono tnum\">0</dd></div></dl><p class=\"vit-rcpt-n\">16&#160;seconds from the accepted lie to the seized bond. The whole run is 29 transactions on Arc.</p><p class=\"vit-rcpt-x\"><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0x0ffca5433186735bf5525e525995f3589d842681da8ffcaa82acb5993025051f\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Open on the explorer: 0x0ffca5433186735bf5525e525995f3589d842681da8ffcaa82acb5993025051f\">0x0ffca543…051f</a></p></figure></div><h3 class=\"vit-h3\">What people would use it for</h3><ul class=\"vit-uses\"><li>An insurer pays claims on losses replayed by enclaves, because a false claim can be overturned within 3&#160;days and the liar loses its bond.</li><li>A protocol requires two distinct operators to sign its large tiers.</li><li>Any buyer reads an operator’s public ERC-8004 record before trusting it. The liar scores 0.</li></ul></div><aside class=\"vit-side\"><div class=\"vit-side-b\"><h3 class=\"vit-h4\">Why it matters</h3><p class=\"vit-side-why\">Enclaves can be attacked by someone with physical access to the server. So a result is trusted because a lie is caught and costs money, not because the hardware is perfect.</p></div><div class=\"vit-side-b\"><h3 class=\"vit-h4\">Price and who pays</h3><dl class=\"kv-list vit-kv vit-kv-side\"><div class=\"kv-row\"><dt>Price</dt><dd>Not for sale. A demonstration kept on Arc as evidence. Its rule applies to every product.</dd></div><div class=\"kv-row\"><dt>The bond rule</dt><dd>The whole bond, half to whoever proves the fault and half to the victim. Withdrawing a bond takes 7&#160;days, so an operator cannot run first.</dd></div><div class=\"kv-row\"><dt>The cap</dt><dd>On its enclaves’ word alone, an operator collects at most half its available bond (its bond minus any pending withdrawal) in any 24 hours, and at most the product’s cap. A forged enclave can take no more before it loses everything.</dd></div></dl></div><div class=\"vit-side-b\"><h3 class=\"vit-h4\">Today</h3><p class=\"vit-side-today\"><span class=\"led led-red\" aria-hidden=\"true\"></span>Done on 10 November, readable forever on Arc. A live re-run needs three machines.</p><p class=\"lbl vit-k\">What still works</p><ul class=\"vit-still\"><li>The four transactions, on the explorer.</li><li>The liar, shown as caught lying in the console’s Hive and in the 3D room.</li></ul></div><div class=\"vit-side-acts\"><a class=\"btn btn-main btn-s\" href=\"https://explorer.testnet.arc.io/tx/0x0ffca5433186735bf5525e525995f3589d842681da8ffcaa82acb5993025051f\" target=\"_blank\" rel=\"noreferrer\"><span>Open the refutation on Arc</span></a><a class=\"btn btn-line btn-s\" href=\"@hive\"><span>See the liar in the Hive</span></a><a class=\"tlink\" href=\"/doc.html?c=stakes\">How Arc checks it, in detail</a><a class=\"tlink\" href=\"@dc\">Watch it in the 3D room</a></div></aside></div><div class=\"vit-fam-more\"><p class=\"lbl vit-k vit-more-k\">In detail</p><details class=\"vit-more\"><summary><span class=\"vit-more-t\">The problem, in numbers</span><span class=\"mono vit-more-n\">2</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><ul class=\"vit-list\"><li>Attacks with physical access forged enclave attestations in 2025 and 2026 (TEE.fail, Battering RAM, Wiretap), one of them with under $200 of hardware.</li><li>Buyers need to know that a lie is detected and punished, not just that the hardware is trusted.</li></ul><p class=\"lbl muted vit-src-l\">Source: Our research of 1 November 2026, published attacks.</p></div></details><details class=\"vit-more\"><summary><span class=\"vit-more-t\">Who buys it, and the evidence</span><span class=\"mono vit-more-n\">3</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><dl class=\"vit-personas\"><div><dt>Protocols and insurers deciding whether to rely on enclave results</dt><dd>The whole fault-proof path, end to end, on Arc.</dd></div><div><dt>Operators</dt><dd>It shows the rule they accept when they post a bond.</dd></div><div><dt>Judges</dt><dd>The whole run is 29 transactions on Arc.</dd></div></dl></div></details><details class=\"vit-more\"><summary><span class=\"vit-more-t\">What is guaranteed, and by which check</span><span class=\"mono vit-more-n\">3</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><ul class=\"vit-guar\"><li><p class=\"vit-guar-w\">A refutation needs at least 2 distinct operators, more than the claim’s signers and none of them a signer, within 3&#160;days.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Checked by</span> <code class=\"mono vit-code\">SealedBounty.refute, REFUTE_QUORUM, REFUTE_WINDOW</code></p></li><li><p class=\"vit-guar-w\">The whole bond is seized and the operator is banned from bonding again.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Checked by</span> <code class=\"mono vit-code\">OperatorBond.slash, banned</code></p></li><li><p class=\"vit-guar-w\">An undelivered payout is cancelled and the pool made whole.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Checked by</span> <code class=\"mono vit-code\">SealedBounty.refute, delivery blocked</code></p></li></ul></div></details><details class=\"vit-more\"><summary><span class=\"vit-more-t\">Limits, said plainly</span><span class=\"mono vit-more-n\">2</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><ul class=\"vit-list\"><li>All three operators were demo keys run by our team, under separate addresses.</li><li>Distinct operators, not yet distinct machines: all three enclaves ran on the same physical server.</li></ul></div></details></div>"},{"id":"retired","cls":"vit-sec vit-fam is-off","k":"v2.1 product #6","t":"Retired","plain":"Retired","units":"v2.1 #6","body":"<header class=\"vit-fam-hd is-off\"><h2 aria-label=\"Retired\" class=\"vt-h vit-fam-name\" id=\"retired-h\">Retired<span class=\"ttl-rule\" aria-hidden=\"true\"></span></h2><p class=\"vit-fam-head\">The first verified bounty, switched off by our own review.</p><p class=\"lede vit-fam-sub\">Our own security review hardened its chip check, and the corrected contracts were redeployed within hours. A product’s payment contract can never change, so product 6 was switched off on 10 November and the verified bounty came back as product 7, on the v2.1 stack. On the v3 stack, deployed on 19 November, it is product 5.</p></header><div class=\"vit-retired\" data-pid=\"v21-6\"><ol class=\"path vit-steps\"><li class=\"row path-s\"><span class=\"path-n mono\" aria-hidden=\"true\">01</span><div class=\"path-b\"><h4 class=\"path-t\">The flaw</h4><p class=\"path-d\">A forged, unsigned piece of Intel’s certificate could make the contract read a chip ID of the attacker’s choice, and pass for a machine in a known datacenter.</p><p class=\"vit-step-c\"><code class=\"mono vit-code\">PckChip</code></p></div></li><li class=\"row path-s\"><span class=\"path-n mono\" aria-hidden=\"true\">02</span><div class=\"path-b\"><h4 class=\"path-t\">The fix</h4><p class=\"path-d\">The chip check now decodes the certificate exactly like Intel’s verifier and accepts exactly one certificate. Three adversarial agents attacked the fix again and found no new bug.</p><p class=\"vit-step-c\"><code class=\"mono vit-code\">test_chip_rejectsForgedPpid</code></p></div></li><li class=\"row path-s\"><span class=\"path-n mono\" aria-hidden=\"true\">03</span><div class=\"path-b\"><h4 class=\"path-t\">The switch</h4><p class=\"path-d\">Product 6’s policy now points to a dead auditor, so no machine can ever qualify for it. It never paid anything, and no bond was ever at risk.</p><p class=\"vit-step-c\"><code class=\"mono vit-code\">meetsPolicy(6, any) = false</code></p></div></li></ol><div class=\"vit-retired-side\"><span class=\"blade vit-face\" data-led=\"off\" data-long=\"1\" aria-hidden=\"true\"><span class=\"blade-face\"><span class=\"bl-led\"><i></i></span><span class=\"bl-title\">Sealed Bounty, verified</span><span class=\"bl-word\">v2.1: replaced by #7</span><span class=\"bl-u\">v2.1 #6</span></span></span><ol class=\"vit-proofs\"><li class=\"vit-proof\"><span class=\"mono tnum vit-proof-at\">10 Nov</span><span class=\"vit-proof-w\">Product 6 proposed</span><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0x5c1afdd6147572257c9627b349b9472b548453025e161bcbd5bfc8f30115c545\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Open on the explorer: 0x5c1afdd6147572257c9627b349b9472b548453025e161bcbd5bfc8f30115c545\">0x5c1afdd6…c545</a></li><li class=\"vit-proof\"><span class=\"mono tnum vit-proof-at\">10 Nov</span><span class=\"vit-proof-w\">Switch-off proposed: its policy set to a dead auditor</span><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0xf91db064e176beafcecfec37f578898919526daed11e1b1fb181b8da86685be3\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Open on the explorer: 0xf91db064e176beafcecfec37f578898919526daed11e1b1fb181b8da86685be3\">0xf91db064…5be3</a></li><li class=\"vit-proof\"><span class=\"mono tnum vit-proof-at\">10 Nov</span><span class=\"vit-proof-w\">Switch-off applied: no machine can qualify</span><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0x190d464ee073cb9582c303c291c120aa53c48f9b00b127a1487c0dd08484b4cb\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Open on the explorer: 0x190d464ee073cb9582c303c291c120aa53c48f9b00b127a1487c0dd08484b4cb\">0x190d464e…b4cb</a></li></ol><p class=\"lbl muted vit-retired-n\">The registry still lists it as active, because a product’s state cannot be changed by re-wiring. Its policy is what switches it off.</p><a class=\"btn btn-line btn-s\" href=\"/service.html?p=5\"><span>Use product 5 instead, on v3</span></a></div></div>"},{"id":"compare","cls":"vit-sec vit-compare","k":"Compare","t":"Compare","plain":"ArcHive next to what exists.","units":"","body":"<h2 aria-label=\"ArcHive next to what exists.\" class=\"vt-h vit-h2\" id=\"compare-h\">ArcHive next to what exists.<span class=\"ttl-rule\" aria-hidden=\"true\"></span></h2><p class=\"lede vit-sec-l\">Honest both ways. From our research of 1 November 2026.</p><div class=\"tbl-w vit-cmp-w\"><table class=\"tbl vit-cmp\"><thead><tr><th scope=\"col\"><span class=\"sr-only\">Criterion</span></th><th scope=\"col\" class=\"is-us\"><span class=\"vit-cmp-t\">ArcHive</span><span class=\"lbl muted vit-cmp-s\">on Arc testnet</span></th><th scope=\"col\"><span class=\"vit-cmp-t\">Centralised AI APIs</span><span class=\"lbl muted vit-cmp-s\">an ordinary model API</span></th><th scope=\"col\"><span class=\"vit-cmp-t\">Enclave clouds and markets</span><span class=\"lbl muted vit-cmp-s\">Phala, 0G, Marlin, iExec, Oasis</span></th><th scope=\"col\"><span class=\"vit-cmp-t\">Bug-bounty platforms</span><span class=\"lbl muted vit-cmp-s\">Immunefi, Cantina</span></th></tr></thead><tbody><tr><th scope=\"row\">Who checks the machine</th><td class=\"is-us\" data-l=\"ArcHive\">A contract on Arc verifies Intel’s signature itself, before any payment.</td><td data-l=\"Centralised AI APIs\">Nobody you can see. You take the provider’s word.</td><td data-l=\"Enclave clouds and markets\">Their own service: a key manager, a router or their own chain. Often optional.</td><td data-l=\"Bug-bounty platforms\">No machine: people triage the reports.</td></tr><tr><th scope=\"row\">How you pay</th><td class=\"is-us\" data-l=\"ArcHive\">USDC per use on Arc. The contract splits each payment in the same transaction. No token.</td><td data-l=\"Centralised AI APIs\">An account, an API key and a card.</td><td data-l=\"Enclave clouds and markets\">An account by card or crypto, or their own token.</td><td data-l=\"Bug-bounty platforms\">After triage. Immunefi contests paid 26 to 63&#160;days after closing.</td></tr><tr><th scope=\"row\">If the result is false</th><td class=\"is-us\" data-l=\"ArcHive\">A second replay or two conflicting receipts prove it, and the operator’s whole bond is seized.</td><td data-l=\"Centralised AI APIs\">A support ticket.</td><td data-l=\"Enclave clouds and markets\">No bond tied to a result.</td><td data-l=\"Bug-bounty platforms\">At the programme’s discretion.</td></tr><tr><th scope=\"row\">Proof you can keep</th><td class=\"is-us\" data-l=\"ArcHive\">A receipt signed by the enclave for each answer, and a public ERC-8004 verdict.</td><td data-l=\"Centralised AI APIs\">An invoice.</td><td data-l=\"Enclave clouds and markets\">An attestation report, checked off-chain.</td><td data-l=\"Bug-bounty platforms\">The platform’s records.</td></tr><tr><th scope=\"row\">Where they are ahead today</th><td class=\"is-us\" data-l=\"ArcHive\">We are on testnet, with one operator and no outside customer yet.</td><td data-l=\"Centralised AI APIs\">Scale and choice of models.</td><td data-l=\"Enclave clouds and markets\">In production with paying customers: Phala made about $3.1M in 2025 with 398 of them. GPUs too.</td><td data-l=\"Bug-bounty platforms\">$144.7M paid by Immunefi, more than 85,000 researchers, KYC at payout.</td></tr></tbody></table></div><p class=\"vit-cmp-edge\">What we found nobody else doing on 1 November: on Arc, the contract that pays is the one that verifies the enclave. It checks Intel’s signature, pays in USDC when the result is accepted, and seizes the bond when the result is proven false.</p><p class=\"lbl muted vit-cmp-also\">Also compared: Chainlink CRE, whose contracts trust Chainlink’s signatures rather than the hardware. UMA and Kleros, where disputes go to token votes or jurors. Zero-knowledge provers, which in our reading cannot yet re-execute an EVM transaction against live state at this cost.</p>"},{"id":"market","cls":"mk","k":"The market","t":"Market","plain":"Who pays whom.","units":"","body":"<header class=\"mk-head\"><p class=\"lbl mk-kick\">The market</p><h2 aria-label=\"Who pays whom.\" class=\"vt-h mk-h\" id=\"market-h\">Who pays <span class=\"vt-acc\">whom</span>.<span class=\"ttl-rule\" aria-hidden=\"true\"></span></h2><div class=\"mk-head-g\"><p class=\"lede mk-lede\">ArcHive is a market with no token, settled in USDC on Arc. Buyers pay per use. Operators rent out sealed Intel TDX machines and lock a bond they lose if they cheat. Authors publish services and set their own share. The contract that checks the machine is the one that pays, and it splits each payment in the same transaction.</p><div class=\"verdict-w cote-in mk-thesis\"><span class=\"cote-l\" aria-hidden=\"true\"></span><p class=\"verdict-l cote-v\">Enclaves for products, not enclaves for enclaves. Checking a machine is free: the network earns only when a product is paid.</p><p data-live-v=\"shares\" class=\"lbl mk-live\"></p><p class=\"lbl mk-tok\">Every share, product by product, and the bond rules: <a class=\"tlink\" href=\"/doc.html?c=tokenomics\">Tokenomics, in the Doc</a></p></div></div><nav class=\"mk-nav\" aria-label=\"In this section\"><a data-vt-in=\"market-sides\" class=\"mk-nav-a\" href=\"#market-sides\"><span class=\"mono\" aria-hidden=\"true\">01</span>Three sides</a><a data-vt-in=\"market-flows\" class=\"mk-nav-a\" href=\"#market-flows\"><span class=\"mono\" aria-hidden=\"true\">02</span>Follow the money</a><a data-vt-in=\"market-so\" class=\"mk-nav-a\" href=\"#market-so\"><span class=\"mono\" aria-hidden=\"true\">03</span>Money so far</a><a data-vt-in=\"market-rules\" class=\"mk-nav-a\" href=\"#market-rules\"><span class=\"mono\" aria-hidden=\"true\">04</span>The rules</a><a data-vt-in=\"market-why\" class=\"mk-nav-a\" href=\"#market-why\"><span class=\"mono\" aria-hidden=\"true\">05</span>Why enclaves</a><a data-vt-in=\"market-first\" class=\"mk-nav-a\" href=\"#market-first\"><span class=\"mono\" aria-hidden=\"true\">06</span>First buyers</a><a data-vt-in=\"market-grow\" class=\"mk-nav-a\" href=\"#market-grow\"><span class=\"mono\" aria-hidden=\"true\">07</span>How it grows</a><a data-vt-in=\"market-main\" class=\"mk-nav-a\" href=\"#market-main\"><span class=\"mono\" aria-hidden=\"true\">08</span>Mainnet numbers</a><a data-vt-in=\"market-not\" class=\"mk-nav-a\" href=\"#market-not\"><span class=\"mono\" aria-hidden=\"true\">09</span>Before mainnet</a></nav></header><section class=\"mk-b\" id=\"market-sides\" aria-labelledby=\"market-sides-h\"><header class=\"mk-bhd\"><h3 class=\"mk-bh\" id=\"market-sides-h\"><span class=\"mk-bn mono\" aria-hidden=\"true\">01</span><span>Three sides, one contract</span></h3><p class=\"mk-blede\">They meet on Arc and never need to trust each other, or us: the contract checks the machine, holds the bond and pays.</p></header><ol class=\"mk-sides\"><li class=\"row mk-side\"><h4 class=\"mk-side-n\">Buyers</h4><dl class=\"mk-side-l\"><div><dt class=\"lbl\">Who</dt><dd>People, apps and AI agents that need private AI. Protocols that want an exploit proven before they pay.</dd></div><div><dt class=\"lbl\">Pays</dt><dd>Per use, in USDC: a prepaid session, one signature per call, or a bounty pool that pays only a proven exploit.</dd></div><div><dt class=\"lbl\">Gets</dt><dd>An answer signed by an enclave Arc verified, with a receipt, and the unused deposit back. A protocol gets the exploit report, encrypted for it alone.</dd></div></dl><p class=\"mk-side-tag\"><span class=\"lbl\">Read on Arc</span> <span data-live-v=\"p3price\" class=\"mono tnum\">0.01 USDC per call, #3</span></p></li><li class=\"row mk-side\"><h4 class=\"mk-side-n\">Operators</h4><dl class=\"mk-side-l\"><div><dt class=\"lbl\">Who</dt><dd>Anyone with an Intel TDX machine, a cloud VM or their own server. One-line install, paired with their wallet.</dd></div><div><dt class=\"lbl\">Pays</dt><dd>A bond in USDC, locked and never spent unless they cheat, back 7 days after they ask. The gas to register each enclave, about 0.14 to 0.17 USDC a day.</dd></div><div><dt class=\"lbl\">Gets</dt><dd>95% of each paid use, less the author’s share on someone else’s service, plus 5% on top of each bounty their enclaves signed.</dd></div></dl><p class=\"mk-side-tag\"><span class=\"lbl\">Read on Arc</span> <span data-live-v=\"op\" class=\"mono tnum\">95%</span></p></li><li class=\"row mk-side\"><h4 class=\"mk-side-n\">Authors</h4><dl class=\"mk-side-l\"><div><dt class=\"lbl\">Who</dt><dd>Anyone with a service to sell. Publishing on Arc is open, with no review and no gatekeeper.</dd></div><div><dt class=\"lbl\">Pays</dt><dd>Only the gas to publish. No machine needed: operators run the service.</dd></div><div><dt class=\"lbl\">Gets</dt><dd>The share they set, from 0 to 30%, a place in the catalog, USDC billing done for them and verification at cost. They choose the operator level allowed to run it.</dd></div></dl><p class=\"mk-side-tag\"><span class=\"lbl\">Read on Arc</span> <span data-live-v=\"au\" class=\"mono tnum\">0%</span></p></li></ol><div class=\"mk-sides-more\"><p><i class=\"mk-sw t-net\" aria-hidden=\"true\"></i>The network keeps 5% of each paid use and 10% on top of each bounty paid. Registering and checking an enclave carries no fee.</p><p><i class=\"mk-sw t-hunt\" aria-hidden=\"true\"></i>Two more people are paid by the rules: the hunter gets the whole bounty tier in the payout transaction, and whoever proves that an operator cheated gets half of its bond.</p></div></section><section class=\"mk-b\" id=\"market-flows\" aria-labelledby=\"market-flows-h\"><header class=\"mk-bhd\"><h3 class=\"mk-bh\" id=\"market-flows-h\"><span class=\"mk-bn mono\" aria-hidden=\"true\">02</span><span>Follow the money</span></h3><p class=\"mk-blede\">Three payments made on Arc, drawn to scale. Each one is a single transaction you can open on the explorer.</p></header><div class=\"mk-flows\"><article class=\"mk-flow\" id=\"market-flow-ai\" aria-labelledby=\"market-flow-ai-t\"><div class=\"mk-flow-t\"><h4 class=\"mk-ft\" id=\"market-flow-ai-t\">A paid AI answer</h4><p class=\"mk-fd\">Private AI, by the call or by the session. The contract pays only against a receipt signed by an enclave Arc verified, and splits the payment in that same transaction.</p><p class=\"mk-ex\"><span class=\"lbl mk-exl\">Example</span> One call at the price on Arc</p></div><div class=\"mk-flow-d\"><div class=\"mk-dia\"><svg class=\"mk-svg\" width=\"672\" height=\"378\" viewBox=\"0 0 672 378\" role=\"img\" aria-label=\"App or agent, 0.01 USDC: Operator 0.0095 USDC, Author 0.00 USDC, Network 0.0005 USDC\"><g class=\"mk-grow\"><rect class=\"mk-band t-src\" x=\"8\" y=\"99.6\" width=\"198\" height=\"176\" /><path class=\"mk-dash t-src\" d=\"M8,187.6 L206,187.6\" style=\"stroke-width: 2;\" /></g><g class=\"mk-o\"><rect class=\"mk-hit\" x=\"456\" y=\"42\" width=\"216\" height=\"175.2\" /><g class=\"mk-grow\"><path class=\"mk-band t-op\" d=\"M218,99.6 C343,99.6 343,46 468,46 L468,213.2 C343,213.2 343,266.79999999999995 218,266.79999999999995 Z\" /><path class=\"mk-dash t-op\" d=\"M218,183.2 C343,183.2 343,129.6 468,129.6\" style=\"stroke-width: 2;\" /></g><rect class=\"mk-node t-op\" x=\"468\" y=\"46\" width=\"8\" height=\"167.2\" /><g class=\"mk-fade\"><text class=\"mk-tl\" x=\"486\" y=\"125.6\">OPERATOR 95%</text><text class=\"mk-tv\" x=\"486\" y=\"142.6\">0.0095 USDC</text></g></g><g class=\"mk-o\"><rect class=\"mk-hit\" x=\"456\" y=\"221.2\" width=\"216\" height=\"54\" /><g class=\"mk-grow\"><path class=\"mk-zero\" d=\"M218,266.79999999999995 C343,266.79999999999995 343,248.2 468,248.2\" /></g><rect class=\"mk-node t-au\" x=\"468\" y=\"247.7\" width=\"8\" height=\"1\" /><g class=\"mk-fade\"><text class=\"mk-tl\" x=\"486\" y=\"244.2\">AUTHOR 0%</text><text class=\"mk-tv\" x=\"486\" y=\"261.2\">0.00 USDC</text></g></g><g class=\"mk-o\"><rect class=\"mk-hit\" x=\"456\" y=\"279.2\" width=\"216\" height=\"54\" /><g class=\"mk-grow\"><path class=\"mk-band t-net\" d=\"M218,266.79999999999995 C343,266.79999999999995 343,301.8 468,301.8 L468,310.6 C343,310.6 343,275.59999999999997 218,275.59999999999997 Z\" /><path class=\"mk-dash t-net\" d=\"M218,271.19999999999993 C343,271.19999999999993 343,306.2 468,306.2\" style=\"stroke-width: 2;\" /></g><rect class=\"mk-node t-net\" x=\"468\" y=\"301.8\" width=\"8\" height=\"8.8\" /><g class=\"mk-fade\"><text class=\"mk-tl\" x=\"486\" y=\"302.2\">NETWORK 5%</text><text class=\"mk-tv\" x=\"486\" y=\"319.2\">0.0005 USDC</text></g></g><rect class=\"mk-node t-src\" x=\"0\" y=\"99.6\" width=\"8\" height=\"176\" /><g class=\"mk-fade\"><text class=\"mk-tl\" x=\"0\" y=\"297.6\">APP OR AGENT</text><text class=\"mk-tv\" x=\"0\" y=\"314.6\">0.01 USDC</text></g><rect class=\"mk-via\" x=\"206\" y=\"99.6\" width=\"12\" height=\"176\" /><text class=\"mk-tk\" x=\"212\" y=\"73.6\" text-anchor=\"middle\">ON ARC</text><text class=\"mk-tn\" x=\"212\" y=\"89.6\" text-anchor=\"middle\">X402Settler</text></svg></div></div><div class=\"mk-flow-v\"><dl class=\"mk-list\" aria-label=\"Who gets what\"><div class=\"mk-li\" tabindex=\"0\"><dt><i class=\"mk-sw t-op\" aria-hidden=\"true\"></i>Operator</dt><dd><span class=\"mono tnum\">0.0095 USDC</span><span class=\"mk-sh\">95%</span></dd></div><div class=\"mk-li\" tabindex=\"0\"><dt><i class=\"mk-sw t-au\" aria-hidden=\"true\"></i>Author</dt><dd><span class=\"mono tnum\">0.00 USDC</span><span class=\"mk-sh\">0%</span></dd></div><div class=\"mk-li\" tabindex=\"0\"><dt><i class=\"mk-sw t-net\" aria-hidden=\"true\"></i>Network</dt><dd><span class=\"mono tnum\">0.0005 USDC</span><span class=\"mk-sh\">5%</span></dd></div></dl><p class=\"lbl mk-st\">Shares as read on Arc on 20 November, on the v3 stack: the same as on v2.1. The operator pays the settlement gas, about 0.005 USDC at today’s testnet gas price.</p><p class=\"mk-proof\"><span class=\"lbl mk-pl\">Proof</span><span><a class=\"tlink mono mk-tx\" href=\"https://explorer.testnet.arc.io/tx/0xa41f1276a9f0b0af98d1991ae1ab06e5f1afb3d9bed71bca486ccea7255c15d9\" target=\"_blank\" rel=\"noreferrer\">0xa41f12…15d9</a> Paid on 9 Nov from a browser: 0.0095 USDC to the operator, 0.0005 USDC to the network.</span></p></div></article><article class=\"mk-flow\" id=\"market-flow-bounty\" aria-labelledby=\"market-flow-bounty-t\"><div class=\"mk-flow-t\"><h4 class=\"mk-ft\" id=\"market-flow-bounty-t\">A proven exploit</h4><p class=\"mk-fd\">Sealed Bounty. The protocol’s pool pays only when an admitted enclave has replayed the exploit on a copy of Arc and measured the loss. The hunter gets the whole tier, and the fees come on top.</p></div><div class=\"mk-flow-d\"><div class=\"mk-dia\"><svg class=\"mk-svg\" width=\"672\" height=\"364\" viewBox=\"0 0 672 364\" role=\"img\" aria-label=\"Protocol’s pool, 0.575 USDC: Hunter 0.5 USDC, Network, +10% 0.05 USDC, Operators who signed, +5% 0.025 USDC\"><g class=\"mk-grow\"><rect class=\"mk-band t-src\" x=\"8\" y=\"92.52173913043478\" width=\"198\" height=\"176\" /><path class=\"mk-dash t-src\" d=\"M8,180.52173913043478 L206,180.52173913043478\" style=\"stroke-width: 2;\" /></g><g class=\"mk-o\"><rect class=\"mk-hit\" x=\"456\" y=\"42\" width=\"216\" height=\"161.04347826086956\" /><g class=\"mk-grow\"><path class=\"mk-band t-hunt\" d=\"M218,92.52173913043478 C343,92.52173913043478 343,46 468,46 L468,199.04347826086956 C343,199.04347826086956 343,245.56521739130434 218,245.56521739130434 Z\" /><path class=\"mk-dash t-hunt\" d=\"M218,169.04347826086956 C343,169.04347826086956 343,122.52173913043478 468,122.52173913043478\" style=\"stroke-width: 2;\" /></g><rect class=\"mk-node t-hunt\" x=\"468\" y=\"46\" width=\"8\" height=\"153.04347826086956\" /><g class=\"mk-fade\"><text class=\"mk-tl\" x=\"486\" y=\"118.52173913043478\">HUNTER</text><text class=\"mk-tv\" x=\"486\" y=\"135.52173913043478\">0.5 USDC</text></g></g><g class=\"mk-o\"><rect class=\"mk-hit\" x=\"456\" y=\"207.04347826086956\" width=\"216\" height=\"54\" /><g class=\"mk-grow\"><path class=\"mk-band t-net\" d=\"M218,245.56521739130434 C343,245.56521739130434 343,226.3913043478261 468,226.3913043478261 L468,241.69565217391306 C343,241.69565217391306 343,260.8695652173913 218,260.8695652173913 Z\" /><path class=\"mk-dash t-net\" d=\"M218,253.2173913043478 C343,253.2173913043478 343,234.04347826086956 468,234.04347826086956\" style=\"stroke-width: 2;\" /></g><rect class=\"mk-node t-net\" x=\"468\" y=\"226.3913043478261\" width=\"8\" height=\"15.304347826086957\" /><g class=\"mk-fade\"><text class=\"mk-tl\" x=\"486\" y=\"230.04347826086956\">NETWORK +10%</text><text class=\"mk-tv\" x=\"486\" y=\"247.04347826086956\">0.05 USDC</text></g></g><g class=\"mk-o\"><rect class=\"mk-hit\" x=\"456\" y=\"265.04347826086956\" width=\"216\" height=\"54\" /><g class=\"mk-grow\"><path class=\"mk-band t-ops\" d=\"M218,260.8695652173913 C343,260.8695652173913 343,288.2173913043478 468,288.2173913043478 L468,295.8695652173913 C343,295.8695652173913 343,268.5217391304348 218,268.5217391304348 Z\" /><path class=\"mk-dash t-ops\" d=\"M218,264.69565217391306 C343,264.69565217391306 343,292.04347826086956 468,292.04347826086956\" style=\"stroke-width: 2;\" /></g><rect class=\"mk-node t-ops\" x=\"468\" y=\"288.2173913043478\" width=\"8\" height=\"7.6521739130434785\" /><g class=\"mk-fade\"><text class=\"mk-tl\" x=\"486\" y=\"288.04347826086956\">OPERATORS +5%</text><text class=\"mk-tv\" x=\"486\" y=\"305.04347826086956\">0.025 USDC</text></g></g><rect class=\"mk-node t-src\" x=\"0\" y=\"92.52173913043478\" width=\"8\" height=\"176\" /><g class=\"mk-fade\"><text class=\"mk-tl\" x=\"0\" y=\"290.52173913043475\">PROTOCOL’S POOL</text><text class=\"mk-tv\" x=\"0\" y=\"307.52173913043475\">0.575 USDC</text></g><rect class=\"mk-via\" x=\"206\" y=\"92.52173913043478\" width=\"12\" height=\"176\" /><text class=\"mk-tk\" x=\"212\" y=\"66.52173913043478\" text-anchor=\"middle\">ON ARC</text><text class=\"mk-tn\" x=\"212\" y=\"82.52173913043478\" text-anchor=\"middle\">SealedBounty</text></svg></div></div><div class=\"mk-flow-v\"><dl class=\"mk-list\" aria-label=\"Who gets what\"><div class=\"mk-li\" tabindex=\"0\"><dt><i class=\"mk-sw t-hunt\" aria-hidden=\"true\"></i>Hunter</dt><dd><span class=\"mono tnum\">0.5 USDC</span></dd></div><div class=\"mk-li\" tabindex=\"0\"><dt><i class=\"mk-sw t-net\" aria-hidden=\"true\"></i>Network, +10%</dt><dd><span class=\"mono tnum\">0.05 USDC</span></dd></div><div class=\"mk-li\" tabindex=\"0\"><dt><i class=\"mk-sw t-ops\" aria-hidden=\"true\"></i>Operators who signed, +5%</dt><dd><span class=\"mono tnum\">0.025 USDC</span></dd></div></dl><p class=\"mk-proof\"><span class=\"lbl mk-pl\">Proof</span><span><a class=\"tlink mono mk-tx\" href=\"https://explorer.testnet.arc.io/tx/0xecbd089a092edd939ff646fae8d22c0f2616b6a92f58a49928c231c770bb807e\" target=\"_blank\" rel=\"noreferrer\">0xecbd08…807e</a> Paid on 9 Nov, with the encrypted report and the ERC-8004 verdict in the same transaction.</span></p><p class=\"mk-note\">The verified level (#5) has the same fees. Its payouts have been authorized on Arc since 19 Nov at 20:37 UTC, when the v3 stack was initialized.</p></div></article><article class=\"mk-flow\" id=\"market-flow-slash\" aria-labelledby=\"market-flow-slash-t\"><div class=\"mk-flow-t\"><h4 class=\"mk-ft\" id=\"market-flow-slash-t\">A proven lie</h4><p class=\"mk-fd\">Cheating costs the bond. On 10 Nov an enclave built to lie inflated a loss. The enclaves of two other operators replayed the exploit and refuted it. Nothing was paid out, the liar’s whole bond was seized and its operator banned.</p></div><div class=\"mk-flow-d\"><div class=\"mk-dia\"><svg class=\"mk-svg\" width=\"672\" height=\"302\" viewBox=\"0 0 672 302\" role=\"img\" aria-label=\"Liar’s bond, 1.00 USDC, Banned: Whoever proved it 0.5 USDC, Victim, or the treasury 0.5 USDC\"><g class=\"mk-grow\"><rect class=\"mk-band t-src\" x=\"8\" y=\"52\" width=\"198\" height=\"176\" /><path class=\"mk-dash t-src\" d=\"M8,140 L206,140\" style=\"stroke-width: 2;\" /></g><g class=\"mk-o\"><rect class=\"mk-hit\" x=\"456\" y=\"42\" width=\"216\" height=\"96\" /><g class=\"mk-grow\"><path class=\"mk-band t-rep\" d=\"M218,52 C343,52 343,46 468,46 L468,134 C343,134 343,140 218,140 Z\" /><path class=\"mk-dash t-rep\" d=\"M218,96 C343,96 343,90 468,90\" style=\"stroke-width: 2;\" /></g><rect class=\"mk-node t-rep\" x=\"468\" y=\"46\" width=\"8\" height=\"88\" /><g class=\"mk-fade\"><text class=\"mk-tl\" x=\"486\" y=\"86\">PROVER 50%</text><text class=\"mk-tv\" x=\"486\" y=\"103\">0.5 USDC</text></g></g><g class=\"mk-o\"><rect class=\"mk-hit\" x=\"456\" y=\"142\" width=\"216\" height=\"96\" /><g class=\"mk-grow\"><path class=\"mk-band t-vic\" d=\"M218,140 C343,140 343,146 468,146 L468,234 C343,234 343,228 218,228 Z\" /><path class=\"mk-dash t-vic\" d=\"M218,184 C343,184 343,190 468,190\" style=\"stroke-width: 2;\" /></g><rect class=\"mk-node t-vic\" x=\"468\" y=\"146\" width=\"8\" height=\"88\" /><g class=\"mk-fade\"><text class=\"mk-tl\" x=\"486\" y=\"186\">VICTIM 50%</text><text class=\"mk-tv\" x=\"486\" y=\"203\">0.5 USDC</text></g></g><rect class=\"mk-node t-src\" x=\"0\" y=\"52\" width=\"8\" height=\"176\" /><g class=\"mk-fade\"><text class=\"mk-tl\" x=\"0\" y=\"250\">LIAR’S BOND</text><text class=\"mk-tv\" x=\"0\" y=\"267\">1.00 USDC</text><rect class=\"mk-led-red\" x=\"0\" y=\"279\" width=\"18\" height=\"5\" /><text class=\"mk-tl mk-red\" x=\"26\" y=\"285\">BANNED</text></g><rect class=\"mk-via\" x=\"206\" y=\"52\" width=\"12\" height=\"176\" /><text class=\"mk-tk\" x=\"212\" y=\"26\" text-anchor=\"middle\">ON ARC</text><text class=\"mk-tn\" x=\"212\" y=\"42\" text-anchor=\"middle\">OperatorBond</text></svg></div></div><div class=\"mk-flow-v\"><dl class=\"mk-list\" aria-label=\"Who gets what\"><div class=\"mk-li\" tabindex=\"0\"><dt><i class=\"mk-sw t-rep\" aria-hidden=\"true\"></i>Whoever proved it</dt><dd><span class=\"mono tnum\">0.5 USDC</span><span class=\"mk-sh\">50%</span></dd></div><div class=\"mk-li\" tabindex=\"0\"><dt><i class=\"mk-sw t-vic\" aria-hidden=\"true\"></i>Victim, or the treasury</dt><dd><span class=\"mono tnum\">0.5 USDC</span><span class=\"mk-sh\">50%</span></dd></div></dl><p class=\"mk-proof\"><span class=\"lbl mk-pl\">Proof</span><span><a class=\"tlink mono mk-tx\" href=\"https://explorer.testnet.arc.io/tx/0x0ffca5433186735bf5525e525995f3589d842681da8ffcaa82acb5993025051f\" target=\"_blank\" rel=\"noreferrer\">0x0ffca5…051f</a> Refuted and seized on 10 Nov, 16 s after the lie was accepted.</span></p><p class=\"mk-note\">Only for a fault a machine can prove: two receipts for the same step, two claims for the same inputs, or a claim refuted by at least 2 other operators within 3 days. Never for a wrong AI answer.</p></div></article></div></section><section class=\"mk-b\" id=\"market-so\" aria-labelledby=\"market-so-h\"><header class=\"mk-bhd\"><h3 class=\"mk-bh\" id=\"market-so-h\"><span class=\"mk-bn mono\" aria-hidden=\"true\">03</span><span>Money so far</span></h3><p class=\"mk-blede\">Read live from the ArcHive index of events on Arc.</p></header><dl class=\"mk-figs\"><div class=\"row\"><dt class=\"lbl\">Paid for private AI</dt><dd data-live-v=\"settled\" class=\"mk-fig\">0.1494 USDC</dd><dd class=\"lbl mk-fig-d\">to operators and the network</dd></div><div class=\"row\"><dt class=\"lbl\">Paid to a hunter</dt><dd data-live-v=\"bounty\" class=\"mk-fig\">0.5 USDC</dd><dd class=\"lbl mk-fig-d\">the whole tier, fees on top</dd></div><div class=\"row\"><dt class=\"lbl\">Paid calls (x402)</dt><dd data-live-v=\"x402\" class=\"mk-fig\">5</dd><dd class=\"lbl mk-fig-d\">one signature each</dd></div><div class=\"row\"><dt class=\"lbl\">Prepaid sessions</dt><dd data-live-v=\"sessions\" class=\"mk-fig\">1</dd><dd class=\"lbl mk-fig-d\">unused deposit refunded</dd></div><div class=\"row\"><dt class=\"lbl\">ERC-8004 verdicts</dt><dd data-live-v=\"verdicts\" class=\"mk-fig\">3</dd><dd class=\"lbl mk-fig-d\">public scores in Circle’s registry</dd></div><div class=\"row\"><dt class=\"lbl\">Network income</dt><dd class=\"mk-fig\">0.05747 USDC</dd><dd class=\"lbl mk-fig-d\">on v2.1, computed from explorer transfers on 18 November</dd></div><div class=\"row\"><dt class=\"lbl\">Bond seized</dt><dd class=\"mk-fig\">1.00 USDC</dd><dd class=\"lbl mk-fig-d\">from the enclave caught lying</dd></div></dl><p class=\"mk-honest\">All of it came from our own test wallets, on testnet. No outside customer has paid yet: this is customer number 0.</p></section><section class=\"mk-b\" id=\"market-rules\" aria-labelledby=\"market-rules-h\"><header class=\"mk-bhd\"><h3 class=\"mk-bh\" id=\"market-rules-h\"><span class=\"mk-bn mono\" aria-hidden=\"true\">04</span><span>The rules, written in the contracts</span></h3><p class=\"mk-blede\">Prices, shares and bonds are parameters on Arc that anyone can read. The fee floor and the caps are constants in the code.</p></header><div class=\"tbl-w\"><table class=\"tbl mk-rules\"><thead><tr><th scope=\"col\">Rule</th><th scope=\"col\">What the code says</th><th scope=\"col\">Today on Arc</th><th scope=\"col\">Enforced by</th></tr></thead><tbody><tr><th scope=\"row\" data-l=\"Rule\">Network share</th><td data-l=\"What the code says\">At least 5% of each paid use.</td><td data-l=\"Today on Arc\" class=\"mk-now\">5% on all 5 products</td><td data-l=\"Enforced by\" class=\"mono mk-where\">ProductRegistry, MIN_NETWORK_BPS</td></tr><tr><th scope=\"row\" data-l=\"Rule\">Author share</th><td data-l=\"What the code says\">Set by the author, 30% at most.</td><td data-l=\"Today on Arc\" class=\"mk-now\">0%, all 5 products are ours</td><td data-l=\"Enforced by\" class=\"mono mk-where\">ProductRegistry, MAX_AUTHOR_BPS</td></tr><tr><th scope=\"row\" data-l=\"Rule\">Operator share</th><td data-l=\"What the code says\">The rest of each paid use.</td><td data-l=\"Today on Arc\" class=\"mk-now\">95%</td><td data-l=\"Enforced by\" class=\"mono mk-where\">ProductRegistry</td></tr><tr><th scope=\"row\" data-l=\"Rule\">Bounty payout</th><td data-l=\"What the code says\">The hunter gets the whole tier. On top, from the same pool, 10% to the network and 5% to the operators who signed.</td><td data-l=\"Today on Arc\" class=\"mk-now\">1,000 and 500 basis points, on both bounty contracts</td><td data-l=\"Enforced by\" class=\"mono mk-where\">SealedBounty, SealedBountyVerified, fixed at deployment</td></tr><tr><th scope=\"row\" data-l=\"Rule\">Checking a machine</th><td data-l=\"What the code says\">No fee. Registering an enclave costs only its gas.</td><td data-l=\"Today on Arc\" class=\"mk-now\">About 0.14 to 0.17 USDC</td><td data-l=\"Enforced by\" class=\"mono mk-where\">EnclaveRegistry</td></tr><tr><th scope=\"row\" data-l=\"Rule\">Bond</th><td data-l=\"What the code says\">Locked, not spent. On its enclaves’ word alone, an operator never collects more than half of its available bond (its bond minus any pending withdrawal) in any 24 hours, nor more than a product’s cap. It comes back 7 days after the request, once nothing depends on it.</td><td data-l=\"Today on Arc\" class=\"mk-now\">From 1.00 USDC per enclave, cap 10.00 USDC per 24 h (testnet values)</td><td data-l=\"Enforced by\" class=\"mono mk-where\">OperatorBond, UNBOND_DELAY</td></tr><tr><th scope=\"row\" data-l=\"Rule\">Proven fault</th><td data-l=\"What the code says\">The whole bond is seized: half to whoever proved it, half to the victim. The operator is banned.</td><td data-l=\"Today on Arc\" class=\"mk-now\">1 USDC seized on 10 Nov</td><td data-l=\"Enforced by\" class=\"mono mk-where\">OperatorBond, slash</td></tr><tr><th scope=\"row\" data-l=\"Rule\">Publishing</th><td data-l=\"What the code says\">Open to anyone, with no review. A new product or version goes live only after its timelock.</td><td data-l=\"Today on Arc\" class=\"mk-now\">0 on testnet, 48 h planned on mainnet</td><td data-l=\"Enforced by\" class=\"mono mk-where\">ProductRegistry, propose</td></tr><tr><th scope=\"row\" data-l=\"Rule\">Sessions</th><td data-l=\"What the code says\">A prepaid deposit and no bond for the buyer. What is not used comes back at close.</td><td data-l=\"Today on Arc\" class=\"mk-now\">10 min to 30 days</td><td data-l=\"Enforced by\" class=\"mono mk-where\">SessionPay</td></tr><tr><th scope=\"row\" data-l=\"Rule\">A new payment contract</th><td data-l=\"What the code says\">Waits 8 days before it can touch a bond, so operators can leave first. Removing one is immediate.</td><td data-l=\"Today on Arc\" class=\"mk-now\">8 days</td><td data-l=\"Enforced by\" class=\"mono mk-where\">OperatorBond, SETTLEMENT_DELAY</td></tr></tbody></table></div></section><section class=\"mk-b\" id=\"market-why\" aria-labelledby=\"market-why-h\"><header class=\"mk-bhd\"><h3 class=\"mk-bh\" id=\"market-why-h\"><span class=\"mk-bn mono\" aria-hidden=\"true\">05</span><span>Why the products need enclaves, and the enclaves need a market</span></h3></header><div class=\"mk-why\"><div class=\"mk-why-p\"><h4 class=\"mk-sub\">Each product needs a sealed machine</h4><dl class=\"mk-why-l\"><div class=\"row\"><dt>Sealed Bounty</dt><dd>The hunter will not show the exploit before being paid, and the protocol will not pay before proof. A sealed machine that both can check on Arc runs the exploit, then releases the payment and the report together: a fair exchange with no middleman.</dd></div><div class=\"row\"><dt>Private AI</dt><dd>The prompt must stay unreadable to the operator and to us. Only hardware isolation, with an attestation the contract checks, gives that. Each receipt ties the payment to that one machine.</dd></div><div class=\"row\"><dt>Attested Copilot</dt><dd>Its instructions are measured, and the conversation is sealed from our own web server.</dd></div><div class=\"row\"><dt>Cheating costs</dt><dd>It makes an enclave’s word usable for money: a lie a machine can prove costs the whole bond.</dd></div></dl></div><div class=\"mk-why-m\"><h4 class=\"mk-sub\">Enclaves alone do not sell</h4><p class=\"mk-blede\">Checking machines finds few users on its own. Services that people pay for do.</p><div class=\"mk-vs\"><div class=\"mk-vs-c mk-vs-a\"><p class=\"lbl mk-vs-h\">Verification alone</p><ul><li><span class=\"mk-vs-n\">Automata’s DCAP entry point on Ethereum</span><span class=\"mk-vs-v\">used once in four months</span></li><li><span class=\"mk-vs-n\">Marlin Oyster Serverless</span><span class=\"mk-vs-v\">0 events in 56 hours</span></li><li><span class=\"mk-vs-n\">Sui Nautilus</span><span class=\"mk-vs-v\">519 checks in 17 months</span></li><li><span class=\"mk-vs-n\">Boundless proof market</span><span class=\"mk-vs-v\">stopped after 0.12% use</span></li></ul></div><div class=\"mk-vs-c mk-vs-b\"><p class=\"lbl mk-vs-h\">Paid services</p><ul><li><span class=\"mk-vs-n\">Phala</span><span class=\"mk-vs-v\">about 3.1 M$ of revenue in 2025, 398 paying customers</span></li><li><span class=\"mk-vs-n\">Chutes</span><span class=\"mk-vs-v\">3.7 M$ of fees</span></li><li><span class=\"mk-vs-n\">Targon</span><span class=\"mk-vs-v\">10.4 M$ a year, self-declared</span></li></ul></div></div><p class=\"mk-so\">So ArcHive gives the check away and earns on the products.</p><p class=\"lbl muted mk-src\">Our research of 1 Nov 2026, from public sources. Some revenue figures are self-declared.</p></div></div></section><section class=\"mk-b\" id=\"market-first\" aria-labelledby=\"market-first-h\"><header class=\"mk-bhd\"><h3 class=\"mk-bh\" id=\"market-first-h\"><span class=\"mk-bn mono\" aria-hidden=\"true\">06</span><span>Who buys first</span></h3><p class=\"mk-blede\">We open with the Sealed Bounty, the one product whose buyer already pays for security. Then private AI, for teams that cannot use AI without confidentiality.</p></header><dl class=\"mk-big\"><div class=\"row\"><dt class=\"mk-big-v\">144.7 M$</dt><dd class=\"mk-big-d\">paid to hunters on Immunefi, in total</dd></div><div class=\"row\"><dt class=\"mk-big-v\">1.25 B$</dt><dd class=\"mk-big-d\">stolen in Q3 2026, about 270 $ for each 1 $ of bounty paid</dd></div><div class=\"row\"><dt class=\"mk-big-v\">+135%</dt><dd class=\"mk-big-d\">bug reports in 2025, and 60 to 80% invalid on Cantina</dd></div></dl><ol class=\"mk-who\"><li class=\"row mk-who-c\"><span class=\"mk-who-n mono\" aria-hidden=\"true\">01</span><h4 class=\"mk-who-t\">Protocols on Arc</h4><p class=\"mk-who-d\">A pilot pool on one or two contracts, beside their current bounty. 107.7 M$ reached Arc with Extended in October, and none of the 219 public Immunefi programmes names Arc.</p></li><li class=\"row mk-who-c\"><span class=\"mk-who-n mono\" aria-hidden=\"true\">02</span><h4 class=\"mk-who-t\">AI agent builders</h4><p class=\"mk-who-d\">Pay per call with one signature, no account and no deposit. A few USDC of credit let a team try it from its agent.</p></li><li class=\"row mk-who-c\"><span class=\"mk-who-n mono\" aria-hidden=\"true\">03</span><h4 class=\"mk-who-t\">Teams with private data</h4><p class=\"mk-who-d\">Legal, credit, KYC and fraud teams that need a private model and a record of each answer. The EU AI Act asks credit-scoring AI to log events automatically from December 2027.</p></li><li class=\"row mk-who-c\"><span class=\"mk-who-n mono\" aria-hidden=\"true\">04</span><h4 class=\"mk-who-t\">Machine owners</h4><p class=\"mk-who-d\">Owners of Intel TDX machines, in the cloud or on site, who want paid demand for them.</p></li></ol><p class=\"mk-honest\">No outside payer has said yes yet. A named pilot is our next step.</p><p class=\"lbl muted mk-src\">Market figures: our research of 1 Nov 2026 (Immunefi, DefiLlama, Cantina).</p></section><section class=\"mk-b\" id=\"market-grow\" aria-labelledby=\"market-grow-h\"><header class=\"mk-bhd\"><h3 class=\"mk-bh\" id=\"market-grow-h\"><span class=\"mk-bn mono\" aria-hidden=\"true\">07</span><span>How it grows</span></h3><p class=\"mk-blede\">Our reading of the loop. The capacity rule of step 3 is in the code.</p></header><div class=\"mk-fly\"><svg class=\"mk-fly-svg\" viewBox=\"0 0 320 320\" role=\"img\" aria-label=\"A loop of four steps: more products, more paid use, more bonds, more trust, then more products again.\"><circle class=\"mk-fly-ring\" cx=\"160\" cy=\"160\" r=\"116\" /><circle class=\"mk-fly-run\" cx=\"160\" cy=\"160\" r=\"116\" pathLength=\"360\" /><g class=\"mk-fly-arc\"><path d=\"M190.02300923189242,47.952604150468076 A116,116 0 0 1 272.04739584953194,129.97699076810758\" /><polygon points=\"273.85912916524956,136.73847155213107 276.10056784566973,125.78511806372778 266.441309582779,128.37330851475298\" /></g><g class=\"mk-fly-arc\"><path d=\"M272.04739584953194,190.02300923189242 A116,116 0 0 1 190.02300923189242,272.04739584953194\" /><polygon points=\"183.26152844786893,273.85912916524956 194.2148819362722,276.10056784566973 191.62669148524702,266.441309582779\" /></g><g class=\"mk-fly-arc\"><path d=\"M129.97699076810758,272.04739584953194 A116,116 0 0 1 47.95260415046809,190.02300923189244\" /><polygon points=\"46.140870834750444,183.26152844786895 43.89943215433031,194.21488193627223 53.558690417221,191.62669148524705\" /></g><g class=\"mk-fly-arc\"><path d=\"M47.95260415046806,129.97699076810764 A116,116 0 0 1 129.9769907681076,47.952604150468076\" /><polygon points=\"136.7384715521311,46.14087083475043 125.78511806372781,43.89943215433029 128.373308514753,53.55869041722098\" /></g><g class=\"mk-fly-node\"><rect x=\"143\" y=\"27\" width=\"34\" height=\"34\" /><text x=\"160\" y=\"48.5\" text-anchor=\"middle\">01</text></g><g class=\"mk-fly-node\"><rect x=\"259\" y=\"143\" width=\"34\" height=\"34\" /><text x=\"276\" y=\"164.5\" text-anchor=\"middle\">02</text></g><g class=\"mk-fly-node\"><rect x=\"143\" y=\"259\" width=\"34\" height=\"34\" /><text x=\"160\" y=\"280.5\" text-anchor=\"middle\">03</text></g><g class=\"mk-fly-node\"><rect x=\"27\" y=\"143\" width=\"34\" height=\"34\" /><text x=\"44\" y=\"164.5\" text-anchor=\"middle\">04</text></g><text class=\"mk-fly-c1\" x=\"160\" y=\"156\" text-anchor=\"middle\">PAID IN USDC</text><text class=\"mk-fly-c2\" x=\"160\" y=\"175\" text-anchor=\"middle\">CHECKED BY ARC</text></svg><ol class=\"mk-fly-list\"><li class=\"row mk-fly-li\"><span class=\"mk-fly-n mono\" aria-hidden=\"true\">01</span><p><b>More products</b> bring more buyers: agents, apps and protocols that pay in USDC.</p></li><li class=\"row mk-fly-li\"><span class=\"mk-fly-n mono\" aria-hidden=\"true\">02</span><p><b>More paid use</b> means more revenue per machine, which brings operators. Each one locks a bond.</p></li><li class=\"row mk-fly-li\"><span class=\"mk-fly-n mono\" aria-hidden=\"true\">03</span><p><b>More bonds</b> raise what the network can pay on enclaves’ word: half of each operator’s available bond (its bond minus any pending withdrawal) per 24 hours, within each product’s cap. Bigger bounties become possible.</p></li><li class=\"row mk-fly-li\"><span class=\"mk-fly-n mono\" aria-hidden=\"true\">04</span><p><b>More trust</b> more operators and verified machines make results safer to rely on, which brings more authors and more products.</p></li></ol></div></section><section class=\"mk-b\" id=\"market-main\" aria-labelledby=\"market-main-h\"><header class=\"mk-bhd\"><h3 class=\"mk-bh\" id=\"market-main-h\"><span class=\"mk-bn mono\" aria-hidden=\"true\">08</span><span>On mainnet: the unit economics</span><span class=\"mk-tag lbl\">Estimate</span></h3><p class=\"mk-blede\">Our pricing for mainnet, computed on 7 Nov from Arc’s gas price and our suppliers’ prices. Prices on testnet today are demo values, set high so that every flow shows on the explorer.</p></header><figure class=\"mk-bar-f\"><figcaption class=\"mk-bar-c\"><span>One typical private AI request, 40,000 tokens in and 2,000 out</span><span class=\"mono tnum mk-bar-tot\">0.0096 USDC for the buyer</span></figcaption><div class=\"mk-bar\" role=\"img\" aria-label=\"Split of 0.0096 USDC: 0.0072 USDC for the model, 0.00192 USDC operator margin, 0.00048 USDC for the network\"><span class=\"mk-seg t-model\" style=\"flex-grow: 7200;\"><span class=\"mk-seg-l mono\">75%</span></span><span class=\"mk-seg t-op\" style=\"flex-grow: 1920;\"><span class=\"mk-seg-l mono\">20%</span></span><span class=\"mk-seg t-net\" style=\"flex-grow: 480;\"></span></div><ul class=\"mk-legend\"><li><i class=\"mk-sw t-model\" aria-hidden=\"true\"></i>The model, paid to the provider <span class=\"mono tnum\">0.0072 USDC</span> <span class=\"muted\">75%</span></li><li><i class=\"mk-sw t-op\" aria-hidden=\"true\"></i>Operator margin <span class=\"mono tnum\">0.00192 USDC</span> <span class=\"muted\">20%</span></li><li><i class=\"mk-sw t-net\" aria-hidden=\"true\"></i>Network, 5% <span class=\"mono tnum\">0.00048 USDC</span> <span class=\"muted\">5%</span></li></ul><p class=\"mk-note\">About a third more than the same model bought directly, for a sealed prompt and a signed receipt. Model gpt-oss-120b through RedPill, at 0.15 $ per million tokens in and 0.60 $ out.</p></figure><dl class=\"kv-list mk-kv\"><div class=\"kv-row\"><dt>Operator break-even</dt><dd>About 835 to 850 typical requests a day, about 8 USDC of sales, for one CPU machine that costs about 1.53 $ a day (VM 1.39 $, daily registration 0.14 USDC).</dd></div><div class=\"kv-row\"><dt>Operator margin at the cap</dt><dd>About 7.9 to 8 $ a day with a 100 USDC bond, which caps sales at 50 USDC a day.</dd></div><div class=\"kv-row\"><dt>Bonds</dt><dd>100 USDC for a CPU machine, 1,000 USDC for a GPU. A cheater can take at most half of its bond a day, and loses all of it once caught.</dd></div><div class=\"kv-row\"><dt>Pay per call</dt><dd>At least 0.10 USDC a call, so that the settlement gas (0.0063 USDC) stays near 6%. Below that, a session.</dd></div><div class=\"kv-row\"><dt>Sessions</dt><dd>A 5 USDC deposit by default, gas about 1.3% of it, settled once 0.50 USDC is owed.</dd></div><div class=\"kv-row\"><dt>Sealed Bounty</dt><dd>The protocol pays the tier plus 15%, only when a payout happens. Pilot pool of 20,000 USDC, tiers of 100, 1,000, 5,000 and 10,000 USDC for losses from 1k, 10k, 50k and 100k.</dd></div><div class=\"kv-row\"><dt>Launch capital</dt><dd>About 410 USDC locked in bonds, a demo vault and a first pool, about 355 of it recoverable.</dd></div><div class=\"kv-row\"><dt>Testnet today</dt><dd>Minimum bond 1 USDC, cap 10 USDC per 24 h, timelock 0, private AI at 100 USDC per million tokens.</dd></div></dl></section><section class=\"mk-b\" id=\"market-not\" aria-labelledby=\"market-not-h\"><header class=\"mk-bhd\"><h3 class=\"mk-bh\" id=\"market-not-h\"><span class=\"mk-bn mono\" aria-hidden=\"true\">09</span><span>Before mainnet</span></h3><p class=\"mk-blede\">What a buyer should know today.</p></header><ul class=\"mk-not\"><li class=\"row\"><span class=\"mk-not-m\" aria-hidden=\"true\"></span><p><b>Mainnet</b> ArcHive runs on Arc testnet. Deploying Intel’s verifier on Arc mainnet takes 37 transactions, about 1.4 USDC.</p></li><li class=\"row\"><span class=\"mk-not-m\" aria-hidden=\"true\"></span><p><b>One operator, one machine</b> On testnet, all verified enclaves run on one machine, under one operator. Every payment so far came from our own wallets.</p></li><li class=\"row\"><span class=\"mk-not-m\" aria-hidden=\"true\"></span><p><b>Live enclaves</b> The verified enclaves of products #1, #2, #3, #4 and #5 run on the v3 stack. Everything already on Arc stays readable.</p></li><li class=\"row\"><span class=\"mk-not-m\" aria-hidden=\"true\"></span><p><b>Before real money</b> Next come state proofs in production, identity checks at payout, a path for payouts above the bond cap, an external audit and our packages on npm.</p></li><li class=\"row\"><span class=\"mk-not-m\" aria-hidden=\"true\"></span><p><b>Agents prepare, people sign</b> AskHive and the MCP server prepare operations. A person signs each one with their own wallet.</p></li></ul></section>"},{"id":"build","cls":"vit-sec vit-build","k":"Build on it","t":"Build on it","plain":"Build on it.","units":"","body":"<h2 aria-label=\"Build on it.\" class=\"vt-h vit-h2\" id=\"build-h\">Build on it.<span class=\"ttl-rule\" aria-hidden=\"true\"></span></h2><p class=\"lede vit-sec-l\">What a product page does, your code can do: read the network, prepare an operation, sign it with your own wallet.</p><div class=\"vit-build-g\"><div class=\"vit-build-c\"><h3 class=\"vit-build-t\">MCP server, online</h3><p class=\"vit-build-d\">16&#160;tools for Claude, Cursor or any MCP client. They read the network and prepare operations. They never sign: you do.</p><p class=\"lbl muted\">Server URL, Streamable HTTP, no account, no key</p><div class=\"cmd\"><code class=\"mono cmd-t\">https://arc-hive.xyz/mcp</code><button class=\"cmd-b\" aria-label=\"Copy: https://arc-hive.xyz/mcp\">Copy</button></div><p class=\"lbl muted\">Claude Code</p><div class=\"cmd\"><code class=\"mono cmd-t\">claude mcp add --transport http archive https://arc-hive.xyz/mcp</code><button class=\"cmd-b\" aria-label=\"Copy: claude mcp add --transport http archive https://arc-hive.xyz/mcp\">Copy</button></div></div><div class=\"vit-build-c\"><h3 class=\"vit-build-t\">Public API</h3><p class=\"vit-build-d\">13 read-only routes, in JSON: products, enclaves, bounties, the proof chain, operator levels.</p><div class=\"cmd\"><code class=\"mono cmd-t\">curl https://arc-hive.xyz/api/products</code><button class=\"cmd-b\" aria-label=\"Copy: curl https://arc-hive.xyz/api/products\">Copy</button></div></div><div class=\"vit-build-c\"><h3 class=\"vit-build-t\">SDK and CLI</h3><p class=\"vit-build-d\">A TypeScript SDK (81&#160;tests) and a CLI with 33&#160;commands, in the project repository. They are not published on npm yet: install them from the repository.</p></div><div class=\"vit-build-c\"><h3 class=\"vit-build-t\">Contracts</h3><p class=\"vit-build-d\">13 contracts in service on Arc testnet. Their addresses and the checks they run are in the Doc.</p><a class=\"tlink\" href=\"/doc.html?c=contracts\">Open the Doc</a></div></div>"},{"id":"faq","cls":"vit-sec vit-faq","k":"Questions","t":"Questions","plain":"Questions","units":"","body":"<h2 aria-label=\"Questions\" class=\"vt-h vit-h2\" id=\"faq-h\">Questions<span class=\"ttl-rule\" aria-hidden=\"true\"></span></h2><div class=\"vit-faq-l\"><details class=\"vit-more vit-q\"><summary><span class=\"vit-more-t\">Is it live?</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><p>On Arc testnet, yes: the contracts of the v3 stack, its five products and every past payment are live and readable now. The verified enclaves of products #1, #2, #3, #4 and #5 run on the v3 stack, so these services can be used now.</p></div></details><details class=\"vit-more vit-q\"><summary><span class=\"vit-more-t\">Has anyone paid yet?</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><p>Only our team. Every payment on Arc so far came from our own test wallets, and no outside customer has paid yet. We are starting with Arc protocols that could fund a pilot bounty pool, then AI teams that cannot use an ordinary API.</p></div></details><details class=\"vit-more vit-q\"><summary><span class=\"vit-more-t\">Who pays whom?</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><p>Buyers pay per use in USDC: a prepaid session, one signature per call, or a bounty pool. The contract splits each payment in the same transaction: on our products, 95% to the operator who runs the machine and 5% to the network. An author can take up to 30%, and the network always keeps at least 5%. On a bounty, the hunter gets the whole tier, plus 10% to the network and 5% to the verifying operators. Verifying a machine costs only gas, and there is no token.</p></div></details><details class=\"vit-more vit-q\"><summary><span class=\"vit-more-t\">Why does it need an enclave?</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><p>Because each product holds something nobody should see or fake: a prompt the operator must not read, an exploit that must stay secret until it is paid, an assistant whose instructions must not change in silence. An Intel TDX enclave runs code its own operator cannot read or alter, and proves which code it is. Arc checks that proof before any money moves.</p></div></details><details class=\"vit-more vit-q\"><summary><span class=\"vit-more-t\">What if an enclave lies?</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><p>Its operator loses everything it put up. Every operator posts a USDC bond. If a lie is proven, by two other operators replaying the work within 3&#160;days or by two conflicting receipts, the contract seizes the whole bond, half to whoever proved it and half to the victim, and bans the operator. It happened on Arc on 10 November, 16&#160;seconds after the lie was accepted. Until then, what an operator can collect on its enclaves’ word is capped at half its available bond (its bond minus any pending withdrawal) over any 24 hours, and at the product’s cap.</p></div></details><details class=\"vit-more vit-q\"><summary><span class=\"vit-more-t\">Can I publish my own product?</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><p>Yes. Publishing is open, with no review: you set the price, your share up to 30%, the machine image Arc will accept and the minimum operator level. Operators then run it, and the contract bills it for you. On testnet a new product is live at once. On mainnet a 48-hour delay is planned.</p></div></details><details class=\"vit-more vit-q\"><summary><span class=\"vit-more-t\">Is it on mainnet?</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><p>Not yet. Everything runs on Arc testnet. Mainnet needs Intel’s verifier deployed on Arc mainnet (37 transactions, about 1.4&#160;USDC), independent operators and a first outside customer.</p></div></details></div>"}]},"fr":{"hero":{"title":"Ce que vous pouvez acheter sur ArcHive.","acc":"acheter","lede":"ArcHive vend des services qui tournent dans des machines Intel TDX scellées. Les protocoles achètent des primes de bugs qui ne paient qu’un exploit rejoué par une machine. Les apps et les agents achètent une IA privée qui répond avec un reçu signé. Avant que le moindre USDC ne bouge, un contrat sur Arc vérifie lui-même la machine, sans service de vérification entre les deux."},"shop":{"k1":"La vitrine","k2":"5 produits sur Arc, en trois familles, et deux histoires de la v2.1","note":"Vert : une enclave vérifiée le fait tourner en ce moment ; ambre : aucune, lu en direct sur Arc. Chaque paiement et chaque preuve passés restent lisibles sur Arc."},"rows":[{"id":"bounty","lamp":"amber","name":"Prime scellée","word":"À l’arrêt","price":"votre palier + 15 %","line":"Les protocoles DeFi ne paient les chasseurs que pour des failles rejouées dans une enclave. Le rapport n’arrive qu’au protocole."},{"id":"private-ai","lamp":"amber","name":"IA privée","word":"À l’arrêt","price":"0,01 USDC l’appel","line":"Pour les apps et les agents d’IA : les réponses de gpt-oss-120b avec un reçu signé, la requête scellée pour une seule enclave vérifiée."},{"id":"attested-copilot","lamp":"amber","name":"Copilote attesté","word":"À l’arrêt","price":"gratuit","line":"Votre navigateur vérifie sur Arc la clé d’enclave du copilote avant que vous écriviez, et même notre serveur web ne voit que du chiffré."},{"id":"refutation","lamp":"red","name":"Tricher coûte","word":"Caution saisie","price":"démo","line":"Le 10 novembre, une enclave conçue pour mentir a été prise par deux autres, et le contrat a saisi la caution de 1,00 USDC de son opérateur."},{"id":"retired","lamp":"off","name":"Retiré","word":"v2.1 : remplacé par le n° 7","price":"jamais payé","line":"Sur la v2.1 : éteint le 10 novembre par notre propre revue de sécurité, avant tout paiement. Le produit n° 7 l’a remplacé ; sur la v3, la prime vérifiée est le n° 5."}],"faces":[{"id":"bounty","title":"Prime scellée","word":"À l’arrêt","lamp":"amber","units":"#2 #5"},{"id":"private-ai","title":"IA privée","word":"À l’arrêt","lamp":"amber","units":"#1 #3"},{"id":"attested-copilot","title":"Copilote attesté","word":"À l’arrêt","lamp":"amber","units":"#4"},{"id":"refutation","title":"Tricher coûte","word":"Caution saisie","lamp":"red","units":"v2.1 #5"},{"id":"retired","title":"Retiré","word":"v2.1 : remplacé par le n° 7","lamp":"off","units":"v2.1 #6"}],"hint":"Survolez une lame pour la sortir, cliquez pour lire sa fiche.","state":{"text":"Sur Arc testnet, les enclaves vérifiées des produits n° 1, 2, 3, 4 et 5 tournent sur la pile v3 : ces services s’utilisent donc dès maintenant. Chaque paiement et chaque preuve passés restent lisibles sur Arc.","link":"Voir un vrai parcours, rejoué"},"chapters":[{"id":"offers","cls":"vit-shop","k":"L’offre","t":"L’offre","plain":"Trois produits à acheter, une règle derrière.","units":"","body":"<h2 class=\"vit-shop-h\" id=\"vit-shop-h\">Trois produits à acheter, une règle derrière.</h2><ol class=\"vit-board\"><li class=\"vit-offer\"><a data-vt-ch=\"bounty\" class=\"vit-offer-face\" href=\"?c=bounty\"><span class=\"blade vit-face\" data-led=\"amber\" data-long=\"0\" aria-hidden=\"true\"><span class=\"blade-face\"><span class=\"bl-led\"><i></i></span><span class=\"bl-title\">Prime scellée</span><span class=\"bl-word\">À l’arrêt</span><span class=\"bl-u\">#2 #5</span></span></span></a><h3 class=\"vit-offer-p\"><a data-vt-ch=\"bounty\" href=\"?c=bounty\">Ne payez que les failles prouvées.</a></h3><div class=\"vit-offer-r\"><p class=\"lbl vit-k\">Pour</p><p class=\"vit-v\">Les protocoles DeFi d’Arc, et les chercheurs en sécurité qui traquent leurs failles.</p></div><div class=\"vit-offer-r vit-offer-price\"><p class=\"lbl vit-k\">Prix</p><p class=\"mono tnum vit-price\">Palier + 15&#160;%</p><p class=\"vit-v vit-price-s\">Sur votre propre cagnotte, et seulement quand un exploit est prouvé. Le chasseur touche tout le palier.</p></div><div class=\"vit-offer-r\"><p class=\"lbl vit-k\">Pourquoi une machine scellée</p><p class=\"vit-v\">L’exploit reste secret jusqu’au paiement, et rien n’est payé avant la preuve. Une machine scellée que les deux côtés peuvent vérifier fait les deux.</p></div><div class=\"vit-offer-r\"><p class=\"lbl vit-k\">Aujourd’hui</p><p class=\"vit-v vit-today\"><span class=\"led led-amber\" aria-hidden=\"true\"></span>En service sur la pile v3. Dernier parcours payé sur Arc&#160;: le 9 novembre.</p></div><div class=\"vit-offer-go\"><a data-vt-ch=\"bounty\" class=\"btn btn-line btn-s\" href=\"?c=bounty\"><span>Voir la Prime scellée</span></a></div></li><li class=\"vit-offer\"><a data-vt-ch=\"private-ai\" class=\"vit-offer-face\" href=\"?c=private-ai\"><span class=\"blade vit-face\" data-led=\"amber\" data-long=\"0\" aria-hidden=\"true\"><span class=\"blade-face\"><span class=\"bl-led\"><i></i></span><span class=\"bl-title\">IA privée</span><span class=\"bl-word\">À l’arrêt</span><span class=\"bl-u\">#1 #3</span></span></span></a><h3 class=\"vit-offer-p\"><a data-vt-ch=\"private-ai\" href=\"?c=private-ai\">L’IA privée, avec un reçu pour chaque réponse.</a></h3><div class=\"vit-offer-r\"><p class=\"lbl vit-k\">Pour</p><p class=\"vit-v\">Les apps qui traitent des textes juridiques, financiers ou médicaux, et les agents d’IA qui paient à l’appel.</p></div><div class=\"vit-offer-r vit-offer-price\"><p class=\"lbl vit-k\">Prix</p><p class=\"mono tnum vit-price\">0,01 USDC</p><p class=\"vit-v vit-price-s\">l’appel, ou 0,10 USDC les 1&#160;000 jetons en session prépayée. Prix du testnet.</p></div><div class=\"vit-offer-r\"><p class=\"lbl vit-k\">Pourquoi une machine scellée</p><p class=\"vit-v\">Votre requête doit rester illisible pour l’opérateur qui fait tourner la machine, et pour nous.</p></div><div class=\"vit-offer-r\"><p class=\"lbl vit-k\">Aujourd’hui</p><p class=\"vit-v vit-today\"><span class=\"led led-amber\" aria-hidden=\"true\"></span>En service sur la pile v3. Dernier appel payé sur Arc&#160;: le 10 novembre.</p></div><div class=\"vit-offer-go\"><a data-vt-ch=\"private-ai\" class=\"btn btn-line btn-s\" href=\"?c=private-ai\"><span>Voir l’IA privée</span></a></div></li><li class=\"vit-offer\"><a data-vt-ch=\"attested-copilot\" class=\"vit-offer-face\" href=\"?c=attested-copilot\"><span class=\"blade vit-face\" data-led=\"amber\" data-long=\"0\" aria-hidden=\"true\"><span class=\"blade-face\"><span class=\"bl-led\"><i></i></span><span class=\"bl-title\">Copilote attesté</span><span class=\"bl-word\">À l’arrêt</span><span class=\"bl-u\">#4</span></span></span></a><h3 class=\"vit-offer-p\"><a data-vt-ch=\"attested-copilot\" href=\"?c=attested-copilot\">Un assistant que vous pouvez vérifier.</a></h3><div class=\"vit-offer-r\"><p class=\"lbl vit-k\">Pour</p><p class=\"vit-v\">Quiconque veut de l’aide sur ArcHive sans faire confiance à notre serveur.</p></div><div class=\"vit-offer-r vit-offer-price\"><p class=\"lbl vit-k\">Prix</p><p class=\"mono tnum vit-price\">Gratuit</p><p class=\"vit-v vit-price-s\">Pas besoin de wallet pour demander.</p></div><div class=\"vit-offer-r\"><p class=\"lbl vit-k\">Pourquoi une machine scellée</p><p class=\"vit-v\">Ses instructions sont mesurées, elles ne peuvent donc pas changer en silence, et la conversation est scellée à l’abri de notre serveur web.</p></div><div class=\"vit-offer-r\"><p class=\"lbl vit-k\">Aujourd’hui</p><p class=\"vit-v vit-today\"><span class=\"led led-amber\" aria-hidden=\"true\"></span>En service dans sa propre enclave, sur la pile v3. Il répond sous le nom d’AskHive, dans le coin de chaque page.</p></div><div class=\"vit-offer-go\"><a data-vt-ch=\"attested-copilot\" class=\"btn btn-line btn-s\" href=\"?c=attested-copilot\"><span>Voir le copilote</span></a></div></li></ol><div class=\"vit-rule\"><a data-vt-ch=\"refutation\" class=\"vit-rule-face\" href=\"?c=refutation\"><span class=\"blade vit-face\" data-led=\"red\" data-long=\"0\" aria-hidden=\"true\"><span class=\"blade-face\"><span class=\"bl-led\"><i></i></span><span class=\"bl-title\">Tricher coûte</span><span class=\"bl-word\">Caution saisie</span><span class=\"bl-u\">v2.1 #5</span></span></span></a><div class=\"vit-rule-b\"><h3 class=\"vit-rule-h\">Derrière les trois&#160;: un mensonge coûte la caution.</h3><p class=\"vit-rule-d\">Le 10 novembre, une enclave construite pour mentir a réclamé une perte de 2&#160;USDC. Deux autres opérateurs ont rejoué l’exploit, prouvé que la vraie perte était de 1&#160;USDC, et le contrat a saisi toute la caution du menteur. 16 secondes entre le mensonge accepté et la caution saisie.</p><a data-vt-ch=\"refutation\" class=\"tlink\" href=\"?c=refutation\">Voir la réfutation</a></div></div><p class=\"vit-retired-line\"><span class=\"led\" aria-hidden=\"true\"></span><span>Retiré sur la v2.1&#160;: le n°&#160;6, la première prime vérifiée. Notre propre revue de sécurité a trouvé une faille dans sa lecture de la puce&#160;: il a été coupé et remplacé par le n°&#160;7, la prime vérifiée qui est le n°&#160;5 sur la v3. <a data-vt-ch=\"retired\" class=\"tlink\" href=\"?c=retired\">Lire l’histoire</a></span></p>"},{"id":"notary","cls":"vit-sec vit-notary","k":"Pourquoi s’y fier","t":"Pourquoi s’y fier","plain":"Pourquoi croire la machine d’un inconnu.","units":"","body":"<div class=\"vit-notary-hd\"><h2 aria-label=\"Pourquoi croire la machine d’un inconnu.\" class=\"vt-h vit-h2\" id=\"vit-notary-h\">Pourquoi croire <span class=\"vt-acc\">la</span> <span class=\"vt-acc\">machine</span> <span class=\"vt-acc\">d’un</span> <span class=\"vt-acc\">inconnu</span>.<span class=\"ttl-rule\" aria-hidden=\"true\"></span></h2><p class=\"lede vit-notary-l\">Arc est le notaire. Aucune plateforme, aucun comité, aucun service de vérification ne se tient entre l’acheteur et la machine&#160;: des contrats sur Arc la vérifient, gardent l’argent et punissent le mensonge.</p></div><ol class=\"vit-notary-p\"><li class=\"row\"><h3 class=\"vit-notary-t\">Intel signe, Arc vérifie.</h3><p class=\"vit-notary-d\">Chaque machine prouve le code qu’elle exécute par une attestation signée par Intel. Avant de l’admettre, un contrat sur Arc vérifie cette signature et rejoue le journal de démarrage de la machine, octet par octet. Cela coûte environ 0,17&#160;USDC de gaz, et aucuns frais.</p><code class=\"mono vit-code\">EnclaveRegistry, TdxAttestationModule, Automata DCAP</code></li><li class=\"row\"><h3 class=\"vit-notary-t\">Le contrat qui paie est celui qui vérifie.</h3><p class=\"vit-notary-d\">Un reçu, un appel ou une réclamation n’est payé que si une clé admise par Arc l’a signé, pour ce produit, à un bloc récent. Dépôts et cagnottes attendent dans le contrat, jamais chez nous.</p><code class=\"mono vit-code\">SessionPay, X402Settler, SealedBounty</code></li><li class=\"row\"><h3 class=\"vit-notary-t\">Un mensonge coûte la caution.</h3><p class=\"vit-notary-d\">Chaque opérateur bloque des USDC. Quand un mensonge est prouvé, par un second rejeu pour une prime ou par deux reçus contradictoires pour l’IA, le contrat saisit toute la caution, moitié pour qui l’a prouvé, moitié pour la victime, et bannit l’opérateur. Un litige est un second rejeu, pas un vote.</p><code class=\"mono vit-code\">OperatorBond.slash</code></li></ol><div class=\"vit-notary-f\"><p class=\"vit-notary-c\">13 de nos contrats sont en service sur Arc. Nous en avons déployé 51 au total, en comptant les versions précédentes et les 15 contrats du vérificateur d’Automata pour les signatures d’Intel. 253&#160;tests.</p><a class=\"btn btn-main\" href=\"/doc.html\"><span>Voir comment Arc vérifie une machine</span></a></div>"},{"id":"bounty","cls":"vit-sec vit-fam","k":"Produits n° 2 et n° 5","t":"Prime scellée","plain":"Prime scellée","units":"#2 #5","body":"<header class=\"vit-fam-hd is-arc\"><h2 aria-label=\"Prime scellée\" class=\"vt-h vit-fam-name\" id=\"bounty-h\">Prime scellée<span class=\"ttl-rule\" aria-hidden=\"true\"></span></h2><p class=\"vit-fam-head\">Ne payez que les failles prouvées.</p><p class=\"lede vit-fam-sub\">Le chasseur scelle son exploit. Une enclave vérifiée par Arc le rejoue sur une copie d’Arc et mesure la perte. Seule une perte réelle est payée, et le rapport n’est remis qu’à vous, dans la même transaction.</p></header><ul class=\"vit-tiers\"><li class=\"vit-tier\" data-pid=\"2\"><span class=\"blade vit-face\" data-led=\"amber\" data-long=\"0\" aria-hidden=\"true\"><span class=\"blade-face\"><span class=\"bl-led\"><i></i></span><span class=\"bl-title\">Prime scellée</span><span class=\"bl-word\">À l’arrêt</span><span class=\"bl-u\">#2</span></span></span><h3 class=\"vit-tier-n\">Niveau ouvert</h3><dl class=\"kv-list vit-kv\"><div class=\"kv-row\"><dt>Qui peut signer une réclamation</dt><dd>Toute enclave admise par Arc pour ce produit, tenue par un opérateur sous caution.</dd></div><div class=\"kv-row\"><dt>Pour</dt><dd>Tout protocole d’Arc, dès sa première cagnotte.</dd></div><div class=\"kv-row\"><dt>Contrat</dt><dd><a class=\"tlink vit-addr\" href=\"https://explorer.testnet.arc.io/address/0xaA229Eda6b535DF6aEe0B4D892f39e0EC006d308\" target=\"_blank\" rel=\"noreferrer\"><span>SealedBounty</span> <span class=\"mono\">0xaA22…d308</span></a></dd></div><div class=\"kv-row\"><dt>Aujourd’hui</dt><dd>En service sur la pile v3. Payée une fois sur Arc, le 9 novembre, sur la v2.1.</dd></div></dl><div class=\"vit-tier-go\"><a class=\"btn btn-main btn-s\" href=\"/space.html?tab=bounties\"><span>Publier une prime</span></a><p class=\"lbl vit-tier-note\">La publication marche dès maintenant, et les machines en service rejouent les réclamations.</p></div></li><li class=\"vit-tier\" data-pid=\"5\"><span class=\"blade vit-face\" data-led=\"amber\" data-long=\"1\" aria-hidden=\"true\"><span class=\"blade-face\"><span class=\"bl-led\"><i></i></span><span class=\"bl-title\">Prime scellée, vérifiée</span><span class=\"bl-word\">À l’arrêt</span><span class=\"bl-u\">#5</span></span></span><h3 class=\"vit-tier-n\">Niveau vérifié</h3><dl class=\"kv-list vit-kv\"><div class=\"kv-row\"><dt>Qui peut signer une réclamation</dt><dd>Seules les enclaves sur une puce que le certificat d’Intel identifie, déclarée dans un datacenter inspecté par l’alliance Proof of Cloud. Arc vérifie les deux.</dd></div><div class=\"kv-row\"><dt>Pour</dt><dd>Les plus grosses cagnottes, et les acheteurs qui n’acceptent que du matériel certifié.</dd></div><div class=\"kv-row\"><dt>Contrat</dt><dd><a class=\"tlink vit-addr\" href=\"https://explorer.testnet.arc.io/address/0x8958EA25c9cF7bbee39B32C43187d854B5d73ee6\" target=\"_blank\" rel=\"noreferrer\"><span>SealedBountyVerified</span> <span class=\"mono\">0x8958…3ee6</span></a><span class=\"lbl muted vit-same\">même code que SealedBounty</span></dd></div><div class=\"kv-row\"><dt>Aujourd’hui</dt><dd data-live-v=\"p7today\">Autorisée à payer depuis le 19 novembre, 20:37 UTC, câblée avec le reste de la pile v3&#160;: sans attente de 8&#160;jours.</dd></div></dl><div class=\"vit-tier-go\"><a class=\"btn btn-line btn-s\" href=\"/service.html?p=5\"><span>Voir le niveau vérifié</span></a></div></li></ul><div class=\"vit-fam-body\"><div class=\"vit-fam-main\"><h3 class=\"vit-h3\">Comment ça marche</h3><ol class=\"path vit-steps\"><li class=\"row path-s\"><span class=\"path-n mono\" aria-hidden=\"true\">01</span><div class=\"path-b\"><h4 class=\"path-t\">Le protocole publie une prime</h4><p class=\"path-d\">Une cagnotte en USDC, une règle de perte qu’une machine peut vérifier (par exemple, le solde en USDC du contrat X baisse d’au moins T), des paliers de paiement et sa clé de chiffrement. En option, un contrat que la prime peut mettre en pause.</p><p class=\"vit-step-c\"><code class=\"mono vit-code\">SealedBounty.createBounty</code></p></div></li><li class=\"row path-s\"><span class=\"path-n mono\" aria-hidden=\"true\">02</span><div class=\"path-b\"><h4 class=\"path-t\">Le chasseur scelle l’exploit</h4><p class=\"path-d\">Il est chiffré pour la seule enclave. Dans Intel TDX, l’enclave le rejoue sur une copie d’Arc à un bloc récent avec arc-anvil de Circle, mesure la perte et signe une réclamation.</p><p class=\"vit-step-c\"><code class=\"mono vit-code\">EIP-712 claim</code></p></div></li><li class=\"row path-s\"><span class=\"path-n mono\" aria-hidden=\"true\">03</span><div class=\"path-b\"><h4 class=\"path-t\">Arc vérifie la réclamation</h4><p class=\"path-d\">Acceptée seulement si une enclave admise par Arc pour ce produit l’a signée, si le bloc est récent, si le palier correspond à la règle et si cet exploit n’a jamais été payé. Le paiement est réservé et la cible mise en pause.</p><p class=\"vit-step-c\"><code class=\"mono vit-code\">SealedBounty.acceptClaim</code></p></div></li><li class=\"row path-s\"><span class=\"path-n mono\" aria-hidden=\"true\">04</span><div class=\"path-b\"><h4 class=\"path-t\">Payé et livré en une transaction</h4><p class=\"path-d\">Le rapport arrive au protocole, chiffré pour lui seul. Le chasseur touche le palier, le réseau 10&#160;%, les opérateurs vérificateurs 5&#160;%, et un verdict ERC-8004 est écrit.</p><p class=\"vit-step-c\"><code class=\"mono vit-code\">SealedBounty.deliver</code></p></div></li><li class=\"row path-s\"><span class=\"path-n mono\" aria-hidden=\"true\">05</span><div class=\"path-b\"><h4 class=\"path-t\">Trois jours pour contester</h4><p class=\"path-d\">Deux autres opérateurs peuvent réfuter une réclamation en rejouant l’exploit. Si elle mentait, son opérateur perd toute sa caution.</p><p class=\"vit-step-c\"><code class=\"mono vit-code\">SealedBounty.refute</code></p></div></li></ol><h3 class=\"vit-h3\">Preuves sur Arc</h3><p class=\"lbl muted vit-h3-l\">De vraies transactions sur Arc testnet, faites sur la pile v2.1 avant le passage à la v3. Chacune s’ouvre sur l’explorateur.</p><div class=\"vit-rcpts\"><figure class=\"vit-rcpt is-arc\"><figcaption class=\"vit-rcpt-h\"><span class=\"vit-rcpt-t\">Reçu de paiement</span><span class=\"mono tnum vit-rcpt-d\">9 nov. 2026, 19:04:58 UTC</span></figcaption><dl class=\"vit-rcpt-l\"><div><dt>Chasseur, tout le palier</dt><dd class=\"mono tnum\">0,500<span class=\"vit-u\"> USDC</span></dd></div><div><dt>Réseau, plus 10&#160;%</dt><dd class=\"mono tnum\">0,050<span class=\"vit-u\"> USDC</span></dd></div><div><dt>Opérateur vérificateur, plus 5&#160;%</dt><dd class=\"mono tnum\">0,025<span class=\"vit-u\"> USDC</span></dd></div><div class=\"is-total\"><dt>Payé par la cagnotte du protocole</dt><dd class=\"mono tnum\">0,575<span class=\"vit-u\"> USDC</span></dd></div><div class=\"is-extra\"><dt>Rapport, chiffré pour le protocole</dt><dd class=\"mono tnum\">livré</dd></div><div class=\"is-extra\"><dt>Verdict ERC-8004</dt><dd class=\"mono tnum\">100</dd></div></dl><p class=\"vit-rcpt-n\">Une seule transaction, 4 secondes après l’acceptation de la réclamation. L’exploit avait été rejoué dans une machine TDX de production en 6,3 secondes.</p><p class=\"vit-rcpt-x\"><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0xecbd089a092edd939ff646fae8d22c0f2616b6a92f58a49928c231c770bb807e\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Ouvrir sur l’explorateur: 0xecbd089a092edd939ff646fae8d22c0f2616b6a92f58a49928c231c770bb807e\">0xecbd089a…807e</a></p></figure></div><ol class=\"vit-proofs\"><li class=\"vit-proof\"><span class=\"mono tnum vit-proof-at\">9 nov., 19:04:42 UTC</span><span class=\"vit-proof-w\">Prime publiée&#160;: cagnotte de 1&#160;USDC, un palier de 0,5&#160;USDC pour une perte d’au moins 1&#160;USDC</span><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0x1c8e42400950540f7ffc1f8f18bc4e4860f7108d18c0e978cead4a5580a1d4e2\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Ouvrir sur l’explorateur: 0x1c8e42400950540f7ffc1f8f18bc4e4860f7108d18c0e978cead4a5580a1d4e2\">0x1c8e4240…d4e2</a></li><li class=\"vit-proof\"><span class=\"mono tnum vit-proof-at\">9 nov., 19:04:54 UTC</span><span class=\"vit-proof-w\">Réclamation acceptée&#160;: exploit rejoué dans TDX en 6,3&#160;s, cible mise en pause</span><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0xfe46faea86254ae63eedfb3c859d928b1d08a9352b851c6b88ab262bcb7ea5d8\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Ouvrir sur l’explorateur: 0xfe46faea86254ae63eedfb3c859d928b1d08a9352b851c6b88ab262bcb7ea5d8\">0xfe46faea…a5d8</a></li><li class=\"vit-proof\"><span class=\"mono tnum vit-proof-at\">9 nov., 19:04:58 UTC</span><span class=\"vit-proof-w\">Chasseur payé, rapport livré, verdict écrit</span><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0xecbd089a092edd939ff646fae8d22c0f2616b6a92f58a49928c231c770bb807e\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Ouvrir sur l’explorateur: 0xecbd089a092edd939ff646fae8d22c0f2616b6a92f58a49928c231c770bb807e\">0xecbd089a…807e</a></li><li class=\"vit-proof\"><span class=\"mono tnum vit-proof-at\">10 nov., 23:01:50 UTC</span><span class=\"vit-proof-w\">Niveau vérifié&#160;: déclaration Proof of Cloud vérifiée sur Arc (Ed25519), valable 7&#160;jours</span><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0x3e2aa32251a7a7cfa7ee69c3fa653cac6dd4272db2ae92d1b4ed760178fdcd35\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Ouvrir sur l’explorateur: 0x3e2aa32251a7a7cfa7ee69c3fa653cac6dd4272db2ae92d1b4ed760178fdcd35\">0x3e2aa322…cd35</a></li><li class=\"vit-proof\"><span class=\"mono tnum vit-proof-at\">11 nov., 17:34:49 UTC</span><span class=\"vit-proof-w\">Niveau vérifié&#160;: enclave liée à sa puce, identifiant lu dans le certificat d’Intel sur Arc</span><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0xd6928088d90f8bbc2585d04564c4a574312593f3f19792a1cdbf819437bb5f4f\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Ouvrir sur l’explorateur: 0xd6928088d90f8bbc2585d04564c4a574312593f3f19792a1cdbf819437bb5f4f\">0xd6928088…5f4f</a></li><li class=\"vit-proof\"><span class=\"mono tnum vit-proof-at\">11 nov., 17:36:09 UTC</span><span class=\"vit-proof-w\">Niveau vérifié&#160;: première prime financée avec 1&#160;USDC</span><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0x52278630d5f4118034d542101467102ce40befdd52d347faaf74cea6f6ee49fb\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Ouvrir sur l’explorateur: 0x52278630d5f4118034d542101467102ce40befdd52d347faaf74cea6f6ee49fb\">0x52278630…49fb</a></li></ol><h3 class=\"vit-h3\">À quoi il servirait</h3><ul class=\"vit-uses\"><li>Une plateforme de contrats perpétuels sur Arc finance une cagnotte de 20 000&#160;USDC sur ses coffres et ne paie que les exploits qui se rejouent. Zéro rapport à trier, son programme actuel inchangé.</li><li>Un jeune protocole d’Arc publie une cagnotte de 1 000 à 5 000&#160;USDC&#160;: la sécurité la moins chère qu’il puisse acheter, puisqu’il ne paie que si une faille est prouvée.</li><li>Un protocole de prêt n’accepte que des machines de niveau vérifié pour les paiements au-delà de 10 000&#160;USDC, signés par deux opérateurs distincts.</li></ul></div><aside class=\"vit-side\"><div class=\"vit-side-b\"><h3 class=\"vit-h4\">Pourquoi une machine scellée</h3><p class=\"vit-side-why\">Le chasseur ne révélera pas l’exploit avant d’être payé, et le protocole ne paiera pas avant d’avoir vu la preuve. Une machine scellée que les deux peuvent vérifier sur Arc exécute l’exploit, puis libère ensemble le paiement et le rapport. Personne ne garde l’un ou l’autre entre les deux.</p></div><div class=\"vit-side-b\"><h3 class=\"vit-h4\">Prix et qui paie</h3><dl class=\"kv-list vit-kv vit-kv-side\"><div class=\"kv-row\"><dt>Qui paie</dt><dd>Le protocole, depuis une cagnotte en USDC qu’il finance sur Arc.</dd></div><div class=\"kv-row\"><dt>Par exploit prouvé</dt><dd>Le palier, plus 10&#160;% au réseau et 5&#160;% aux opérateurs vérificateurs. Le chasseur touche tout le palier.</dd></div><div class=\"kv-row\"><dt>Exemple</dt><dd>Un palier de 10 000&#160;USDC coûte 11 500&#160;USDC, une fois, pour un exploit prouvé. Pas de preuve, pas de paiement.</dd></div><div class=\"kv-row\"><dt>Démo du testnet</dt><dd>Cagnotte de 1&#160;USDC, un palier de 0,5&#160;USDC pour une perte d’au moins 1&#160;USDC.</dd></div><div class=\"kv-row\"><dt>Pilote, une proposition</dt><dd>Cagnotte de 20 000&#160;USDC, paliers de 100 à 10 000&#160;USDC pour des pertes de 1 000 à 100 000&#160;USDC.</dd></div></dl></div><div class=\"vit-side-b\"><h3 class=\"vit-h4\">Aujourd’hui</h3><p class=\"vit-side-today\"><span class=\"led led-amber\" aria-hidden=\"true\"></span>En service sur la pile v3 : une réclamation prouvée peut être rejouée et payée dès maintenant.</p><p class=\"lbl vit-k\">Ce qui marche encore</p><ul class=\"vit-still\"><li>Publier une prime sur Arc, ce qui ne demande aucune machine.</li><li>Le parcours payé complet du 9 novembre, sur l’explorateur.</li></ul></div><div class=\"vit-side-acts\"><a class=\"btn btn-main btn-s\" href=\"/space.html?tab=bounties\"><span>Publier une prime</span></a><a class=\"btn btn-line btn-s\" href=\"/network.html?focus=demo\"><span>Voir le rejeu</span></a><a class=\"tlink\" href=\"/doc.html?c=notary-robot\">Comment Arc le vérifie, en détail</a><a data-vt-ch=\"build\" class=\"tlink\" href=\"?c=build\">Pour les développeurs</a></div></aside></div><div class=\"vit-fam-more\"><p class=\"lbl vit-k vit-more-k\">En détail</p><details class=\"vit-more\"><summary><span class=\"vit-more-t\">Le problème, en chiffres</span><span class=\"mono vit-more-n\">6</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><ul class=\"vit-list\"><li>Les rapports reçus par les programmes d’Immunefi ont augmenté de 135&#160;% en 2025, et la moitié n’était que du bruit sur les programmes triés.</li><li>Chez Cantina, 60 à 80&#160;% des soumissions sont invalides.</li><li>Les concours d’audit d’Immunefi ont été payés 26 à 63&#160;jours après leur clôture.</li><li>1,25&#160;Md$ ont été volés au troisième trimestre 2026, environ 270&#160;$ pour chaque dollar versé en primes par Immunefi ce trimestre.</li><li>Le chasseur doit révéler l’exploit avant d’être payé, et le protocole doit croire le rapport avant de payer.</li><li>107,7&#160;M$ sont arrivés sur Arc avec une seule plateforme d’échange le 22 octobre, et aucun des 219 programmes publics d’Immunefi ne mentionnait Arc.</li></ul><p class=\"lbl muted vit-src-l\">Source&#160;: Notre recherche du 1er novembre 2026&#160;: Immunefi, Cantina, DefiLlama.</p></div></details><details class=\"vit-more\"><summary><span class=\"vit-more-t\">Qui l’achète, et les preuves</span><span class=\"mono vit-more-n\">4</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><dl class=\"vit-personas\"><div><dt>Les protocoles d’Arc qui gardent des USDC dans leurs contrats</dt><dd>107,7&#160;M$ sont arrivés sur Arc avec une seule plateforme en octobre. Une cagnotte transforme un budget sécurité en paiements pour des failles prouvées seulement.</dd></div><div><dt>Les chercheurs en sécurité</dt><dd>Plus de 85 000 sur Immunefi. 160 programmes sur 180 exigent déjà des tests sur une copie locale uniquement, exactement ce que fait l’enclave.</dd></div><div><dt>L’écosystème d’Arc</dt><dd>Arc a son propre programme de primes, jusqu’à 1&#160;M$. La Prime scellée en est la version automatique, payée en quelques secondes.</dd></div><div><dt>Les assureurs et acheteurs qui exigent une garde de niveau datacenter (niveau vérifié)</dt><dd>L’auteur du produit fixe le niveau d’opérateur minimum et les auditeurs acceptés.</dd></div></dl></div></details><details class=\"vit-more\"><summary><span class=\"vit-more-t\">Ce qui est garanti, et par quel contrôle</span><span class=\"mono vit-more-n\">11</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><ul class=\"vit-guar\"><li><p class=\"vit-guar-w\">Payé seulement si une enclave admise par Arc pour ce produit a signé la réclamation, ancrée sur un vrai bloc récent.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Contrôlé par</span> <code class=\"mono vit-code\">SealedBounty.acceptClaim, EnclaveRegistry.activeOperatorAt, History.blockHashAt (EIP-2935)</code></p></li><li><p class=\"vit-guar-w\">Un exploit n’est payé qu’une fois. Un second paiement exige un palier strictement plus haut et un ancrage plus récent.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Contrôlé par</span> <code class=\"mono vit-code\">fingerprintPaid, TierAlreadyPaid, AnchorBeforeLastPayout</code></p></li><li><p class=\"vit-guar-w\">Au-dessus du plafond de la prime, plusieurs opérateurs distincts doivent signer la même réclamation.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Contrôlé par</span> <code class=\"mono vit-code\">NeedMoreEnclaves (k, singleCap)</code></p></li><li><p class=\"vit-guar-w\">Le rapport arrive au protocole chiffré, dans la même transaction que le paiement. Un virement refusé devient un crédit à retirer, jamais un échec.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Contrôlé par</span> <code class=\"mono vit-code\">SealedBounty.deliver, ExploitDelivered, BountyPaid</code></p></li><li><p class=\"vit-guar-w\">Ce qui peut être payé sur la parole des enclaves est plafonné&#160;: la part égale de chaque opérateur signataire compte, sur 24 heures glissantes, contre la moitié de sa caution disponible (sa caution moins tout retrait demandé) et contre le plafond du produit.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Contrôlé par</span> <code class=\"mono vit-code\">OperatorBond.consumeExposure</code></p></li><li><p class=\"vit-guar-w\">Une fausse réclamation peut être réfutée pendant 3&#160;jours par au moins 2 autres opérateurs&#160;: caution saisie, paiement annulé, verdict 0.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Contrôlé par</span> <code class=\"mono vit-code\">SealedBounty.refute, OperatorBond.slash</code></p></li><li><p class=\"vit-guar-w\">Rien ne s’exécute sur la vraie chaîne&#160;: l’exploit est rejoué sur une copie. La mise en pause de la cible a un plafond de gaz et ne peut pas bloquer le paiement.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Contrôlé par</span> <code class=\"mono vit-code\">_pauseTarget, plafonné à 100 000 de gaz</code></p></li><li><p class=\"vit-guar-w\">Niveau vérifié&#160;: seules comptent les enclaves dont la puce est liée et déclarée par un auditeur accepté, contrôlé au moment du règlement.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Contrôlé par</span> <code class=\"mono vit-code\">PolicyEnclaves, MachineRegistry.meetsPolicy</code></p></li><li><p class=\"vit-guar-w\">Niveau vérifié&#160;: l’identifiant de la puce est lu dans le propre certificat d’Intel, décodé exactement comme le vérificateur d’Automata.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Contrôlé par</span> <code class=\"mono vit-code\">PckChip.chipOf, MachineRegistry.bindMachine</code></p></li><li><p class=\"vit-guar-w\">Niveau vérifié&#160;: la signature de l’alliance est vérifiée sur Arc, pas crue sur parole de qui la soumet.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Contrôlé par</span> <code class=\"mono vit-code\">ProofOfCloudAuditor, Ed25519Verifier</code></p></li><li><p class=\"vit-guar-w\">Un nouveau contrat de paiement attend 8&#160;jours avant de pouvoir toucher aux cautions ou écrire des verdicts, pour que les opérateurs puissent partir avant.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Contrôlé par</span> <code class=\"mono vit-code\">OperatorBond.SETTLEMENT_DELAY, VerdictLog.CALLER_DELAY</code></p></li></ul></div></details><details class=\"vit-more\"><summary><span class=\"vit-more-t\">Les limites, sans détour</span><span class=\"mono vit-more-n\">6</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><ul class=\"vit-list\"><li>L’état de la copie est lu par un relais qui recalcule chaque en-tête de bloc et le chaîne à l’ancrage, mais l’état lui-même n’est pas encore prouvé. Les preuves d’état sont codées et testées (23&#160;tests), et s’allument avec un nœud d’archives.</li><li>Calculs déterministes seulement&#160;: un exploit se rejoue à l’identique, une réponse d’IA non.</li><li>Un seul opérateur aujourd’hui, donc une signature par réclamation en pratique. La capacité suit les cautions&#160;: 1&#160;USDC de caution couvre 0,5&#160;USDC de paiements par 24 heures.</li><li>Pas encore de KYC au paiement, que beaucoup de programmes exigent.</li><li>La cible de démo est notre propre coffre volontairement vulnérable. Aucun protocole extérieur n’a encore financé de cagnotte.</li><li>Niveau vérifié&#160;: toutes les enclaves vérifiées sont sur une seule machine pour l’instant.</li></ul></div></details></div>"},{"id":"private-ai","cls":"vit-sec vit-fam","k":"Produits n° 1 et n° 3","t":"IA privée","plain":"IA privée","units":"#1 #3","body":"<header class=\"vit-fam-hd is-arc\"><h2 aria-label=\"IA privée\" class=\"vt-h vit-fam-name\" id=\"private-ai-h\">IA privée<span class=\"ttl-rule\" aria-hidden=\"true\"></span></h2><p class=\"vit-fam-head\">L’IA privée, avec un reçu pour chaque réponse.</p><p class=\"lede vit-fam-sub\">Discutez avec gpt-oss-120b à travers une enclave vérifiée par Arc. Vos messages sont chiffrés pour cette enclave&#160;: ni l’opérateur ni ArcHive ne peuvent les lire. Payez à la session ou à l’appel, en USDC, seulement ce que vous utilisez.</p></header><ul class=\"vit-tiers\"><li class=\"vit-tier\" data-pid=\"1\"><span class=\"blade vit-face\" data-led=\"amber\" data-long=\"0\" aria-hidden=\"true\"><span class=\"blade-face\"><span class=\"bl-led\"><i></i></span><span class=\"bl-title\">IA privée</span><span class=\"bl-word\">À l’arrêt</span><span class=\"bl-u\">#1</span></span></span><h3 class=\"vit-tier-n\">Session prépayée</h3><dl class=\"kv-list vit-kv\"><div class=\"kv-row\"><dt>Pour</dt><dd>Les apps et les équipes qui posent beaucoup de questions.</dd></div><div class=\"kv-row\"><dt>Prix</dt><dd><span class=\"mono tnum vit-tag\">0,10 USDC les 1&#160;000 jetons</span><span class=\"lbl muted vit-same\">prix de démo du testnet</span></dd></div><div class=\"kv-row\"><dt>Comment vous payez</dt><dd>Un dépôt, signé une fois. L’opérateur est payé sur reçus signés, et le reste vous revient à la clôture.</dd></div><div class=\"kv-row\"><dt>Contrat</dt><dd><a class=\"tlink vit-addr\" href=\"https://explorer.testnet.arc.io/address/0x606c379cd8758E3562e7ECC9972d0feF693F0763\" target=\"_blank\" rel=\"noreferrer\"><span>SessionPay</span> <span class=\"mono\">0x606c…0763</span></a></dd></div></dl><div class=\"vit-tier-go\"><a class=\"btn btn-main btn-s\" href=\"/space.html?tab=sessions&amp;p=1\"><span>Ouvrir une session</span></a></div></li><li class=\"vit-tier\" data-pid=\"3\"><span class=\"blade vit-face\" data-led=\"amber\" data-long=\"1\" aria-hidden=\"true\"><span class=\"blade-face\"><span class=\"bl-led\"><i></i></span><span class=\"bl-title\">IA privée, à l’appel</span><span class=\"bl-word\">À l’arrêt</span><span class=\"bl-u\">#3</span></span></span><h3 class=\"vit-tier-n\">Paiement à l’appel, x402</h3><dl class=\"kv-list vit-kv\"><div class=\"kv-row\"><dt>Pour</dt><dd>Les agents d’IA, les bots et les scripts.</dd></div><div class=\"kv-row\"><dt>Prix</dt><dd><span class=\"mono tnum vit-tag\">0,01 USDC l’appel</span><span class=\"lbl muted vit-same\">lu sur Arc</span></dd></div><div class=\"kv-row\"><dt>Comment vous payez</dt><dd>Une signature par appel. Sans compte, sans dépôt, sans gaz&#160;: l’opérateur règle sur Arc environ 20 secondes plus tard.</dd></div><div class=\"kv-row\"><dt>Contrat</dt><dd><a class=\"tlink vit-addr\" href=\"https://explorer.testnet.arc.io/address/0x89B0381B18536f680fD952a0E7D375d7a4EC3fe6\" target=\"_blank\" rel=\"noreferrer\"><span>X402Settler</span> <span class=\"mono\">0x89B0…3fe6</span></a></dd></div></dl><div class=\"vit-tier-go\"><a class=\"btn btn-main btn-s\" href=\"/network.html?focus=use&amp;p=3\"><span>Faire un appel payé</span></a></div></li></ul><div class=\"vit-fam-body\"><div class=\"vit-fam-main\"><h3 class=\"vit-h3\">Comment ça marche</h3><ol class=\"path vit-steps\"><li class=\"row path-s\"><span class=\"path-n mono\" aria-hidden=\"true\">01</span><div class=\"path-b\"><h4 class=\"path-t\">Payez une fois, ou à l’appel</h4><p class=\"path-d\">Une session prend un dépôt, signé une fois, sans étape d’approbation. Un appel porte sa propre autorisation signée, au prix exact. Le prix et le modèle sont fixés au départ.</p><p class=\"vit-step-c\"><code class=\"mono vit-code\">SessionPay.openSession, X402Settler (EIP-3009)</code></p></div></li><li class=\"row path-s\"><span class=\"path-n mono\" aria-hidden=\"true\">02</span><div class=\"path-b\"><h4 class=\"path-t\">Votre app vérifie la machine sur Arc</h4><p class=\"path-d\">Elle lit la clé de l’enclave sur Arc, où ne figurent que des machines vérifiées par Intel et un code autorisé, et chiffre la question pour elle. L’opérateur et notre serveur ne relaient que du chiffré.</p><p class=\"vit-step-c\"><code class=\"mono vit-code\">EnclaveRegistry, HPKE</code></p></div></li><li class=\"row path-s\"><span class=\"path-n mono\" aria-hidden=\"true\">03</span><div class=\"path-b\"><h4 class=\"path-t\">L’enclave vérifie le modèle, puis répond</h4><p class=\"path-d\">Avant chaque appel, elle vérifie l’enclave du fournisseur du modèle et épingle sa clé. Puis elle appelle gpt-oss-120b et scelle la réponse pour vous, avec un reçu signé par une clé née dans l’enclave.</p><p class=\"vit-step-c\"><code class=\"mono vit-code\">EIP-712 receipt</code></p></div></li><li class=\"row path-s\"><span class=\"path-n mono\" aria-hidden=\"true\">04</span><div class=\"path-b\"><h4 class=\"path-t\">L’opérateur règle sur reçus</h4><p class=\"path-d\">Une transaction paie tout ce qui est dû, partagé à 95&#160;% pour l’opérateur et 5&#160;% pour le réseau. Un appel se règle environ 20 secondes après sa réponse.</p><p class=\"vit-step-c\"><code class=\"mono vit-code\">SessionPay.settle, X402Settler.settle</code></p></div></li><li class=\"row path-s\"><span class=\"path-n mono\" aria-hidden=\"true\">05</span><div class=\"path-b\"><h4 class=\"path-t\">Clôture&#160;: remboursement et verdict</h4><p class=\"path-d\">Le dépôt non utilisé revient, et un verdict ERC-8004 est écrit pour l’opérateur, dans la même transaction.</p><p class=\"vit-step-c\"><code class=\"mono vit-code\">SessionPay.closeSession, VerdictLog</code></p></div></li></ol><h3 class=\"vit-h3\">Preuves sur Arc</h3><p class=\"lbl muted vit-h3-l\">De vraies transactions sur Arc testnet, faites sur la pile v2.1 avant le passage à la v3. Chacune s’ouvre sur l’explorateur.</p><div class=\"vit-rcpts is-two\"><figure class=\"vit-rcpt is-arc\"><figcaption class=\"vit-rcpt-h\"><span class=\"vit-rcpt-t\">Reçu de session</span><span class=\"mono tnum vit-rcpt-d\">9 nov. 2026, 19:12:01 UTC</span></figcaption><dl class=\"vit-rcpt-l\"><div><dt>Dépôt</dt><dd class=\"mono tnum\">1,0000<span class=\"vit-u\"> USDC</span></dd></div><div><dt>Utilisé&#160;: 994 jetons à 0,10 USDC les 1&#160;000</dt><dd class=\"mono tnum\">0,0994<span class=\"vit-u\"> USDC</span></dd></div><div class=\"is-sub\"><dt>dont opérateur, 95&#160;%</dt><dd class=\"mono tnum\">0,09443<span class=\"vit-u\"> USDC</span></dd></div><div class=\"is-sub\"><dt>dont réseau, 5&#160;%</dt><dd class=\"mono tnum\">0,00497<span class=\"vit-u\"> USDC</span></dd></div><div class=\"is-total\"><dt>Remboursé à la clôture</dt><dd class=\"mono tnum\">0,9006<span class=\"vit-u\"> USDC</span></dd></div><div class=\"is-extra\"><dt>Verdict ERC-8004</dt><dd class=\"mono tnum\">100</dd></div></dl><p class=\"vit-rcpt-n\">3 réponses chiffrées, réglées par l’opérateur sans le client. Clôturée avec remboursement et verdict en une seule transaction.</p><p class=\"vit-rcpt-x\"><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0x9430e16a5cff9bd099c0a7a5f2b11dc87e4c11ad6444a0cd9c87f71ee72f1bb4\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Ouvrir sur l’explorateur: 0x9430e16a5cff9bd099c0a7a5f2b11dc87e4c11ad6444a0cd9c87f71ee72f1bb4\">0x9430e16a…1bb4</a><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0xb8299f0698992da535648b14fe1cdd59231ade96b70a515acd7314afc2c8d62f\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Ouvrir sur l’explorateur: 0xb8299f0698992da535648b14fe1cdd59231ade96b70a515acd7314afc2c8d62f\">0xb8299f06…d62f</a></p></figure><figure class=\"vit-rcpt is-arc\"><figcaption class=\"vit-rcpt-h\"><span class=\"vit-rcpt-t\">Reçu d’appel</span><span class=\"mono tnum vit-rcpt-d\">9 nov. 2026, 19:25:38 UTC</span></figcaption><dl class=\"vit-rcpt-l\"><div><dt>Opérateur, 95&#160;%</dt><dd class=\"mono tnum\">0,0095<span class=\"vit-u\"> USDC</span></dd></div><div><dt>Réseau, 5&#160;%</dt><dd class=\"mono tnum\">0,0005<span class=\"vit-u\"> USDC</span></dd></div><div class=\"is-total\"><dt>Un appel, signé dans le navigateur</dt><dd class=\"mono tnum\">0,0100<span class=\"vit-u\"> USDC</span></dd></div></dl><p class=\"vit-rcpt-n\">Réglé par l’opérateur environ 20 secondes après la réponse. Le payeur n’a payé aucun gaz.</p><p class=\"vit-rcpt-x\"><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0xa41f1276a9f0b0af98d1991ae1ab06e5f1afb3d9bed71bca486ccea7255c15d9\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Ouvrir sur l’explorateur: 0xa41f1276a9f0b0af98d1991ae1ab06e5f1afb3d9bed71bca486ccea7255c15d9\">0xa41f1276…15d9</a></p></figure></div><ol class=\"vit-proofs\"><li class=\"vit-proof\"><span class=\"mono tnum vit-proof-at\">9 nov., 18:57:24 UTC</span><span class=\"vit-proof-w\">Enclave d’inférence admise&#160;: Arc a vérifié la signature d’Intel et rejoué son journal de démarrage, pour 0,1717&#160;USDC de gaz</span><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0x199c985dee537cfe2948f6c721ad1bdd448d538ff08bc8e93a79036a25f33499\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Ouvrir sur l’explorateur: 0x199c985dee537cfe2948f6c721ad1bdd448d538ff08bc8e93a79036a25f33499\">0x199c985d…3499</a></li><li class=\"vit-proof\"><span class=\"mono tnum vit-proof-at\">9 nov., 19:04:13 UTC</span><span class=\"vit-proof-w\">Session ouverte avec un dépôt de 1&#160;USDC</span><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0x63f6a544d36766b6cb01aab313b223739a04c706c24255ca6d38358b3ed2afd6\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Ouvrir sur l’explorateur: 0x63f6a544d36766b6cb01aab313b223739a04c706c24255ca6d38358b3ed2afd6\">0x63f6a544…afd6</a></li><li class=\"vit-proof\"><span class=\"mono tnum vit-proof-at\">9 nov., 19:12:01 UTC</span><span class=\"vit-proof-w\">3 réponses réglées&#160;: 0,0994&#160;USDC</span><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0x9430e16a5cff9bd099c0a7a5f2b11dc87e4c11ad6444a0cd9c87f71ee72f1bb4\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Ouvrir sur l’explorateur: 0x9430e16a5cff9bd099c0a7a5f2b11dc87e4c11ad6444a0cd9c87f71ee72f1bb4\">0x9430e16a…1bb4</a></li><li class=\"vit-proof\"><span class=\"mono tnum vit-proof-at\">9 nov., 19:25:38 UTC</span><span class=\"vit-proof-w\">Un appel payé depuis le navigateur&#160;: 0,01&#160;USDC</span><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0xa41f1276a9f0b0af98d1991ae1ab06e5f1afb3d9bed71bca486ccea7255c15d9\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Ouvrir sur l’explorateur: 0xa41f1276a9f0b0af98d1991ae1ab06e5f1afb3d9bed71bca486ccea7255c15d9\">0xa41f1276…15d9</a></li><li class=\"vit-proof\"><span class=\"mono tnum vit-proof-at\">9 nov., 21:04:29 UTC</span><span class=\"vit-proof-w\">Session clôturée&#160;: 0,9006&#160;USDC remboursés, verdict 100</span><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0xb8299f0698992da535648b14fe1cdd59231ade96b70a515acd7314afc2c8d62f\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Ouvrir sur l’explorateur: 0xb8299f0698992da535648b14fe1cdd59231ade96b70a515acd7314afc2c8d62f\">0xb8299f06…d62f</a></li><li class=\"vit-proof\"><span class=\"mono tnum vit-proof-at\">10 nov., 21:43:14 UTC</span><span class=\"vit-proof-w\">Enclave admise à nouveau avec le code qui vérifie le fournisseur du modèle avant chaque appel</span><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0xbd5cb0616dae27f9b614ffa6c6eea28423030932c017f9f910099b0129e19a75\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Ouvrir sur l’explorateur: 0xbd5cb0616dae27f9b614ffa6c6eea28423030932c017f9f910099b0129e19a75\">0xbd5cb061…9a75</a></li><li class=\"vit-proof\"><span class=\"mono tnum vit-proof-at\">10 nov., 21:45:24 UTC</span><span class=\"vit-proof-w\">Un appel payé à travers cette enclave</span><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0x1995e88440bf443b32b9df7c1975c7a94ea003bc465999b34cc440570ea978ed\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Ouvrir sur l’explorateur: 0x1995e88440bf443b32b9df7c1975c7a94ea003bc465999b34cc440570ea978ed\">0x1995e884…78ed</a></li></ol><h3 class=\"vit-h3\">À quoi il servirait</h3><ul class=\"vit-uses\"><li>Un cabinet résume 40 contrats confidentiels&#160;: requêtes chiffrées pour une enclave vérifiée, un reçu par réponse, 5&#160;USDC prépayés, le reste remboursé à la clôture.</li><li>Un protocole de crédit DeFi pose ses questions de souscription sur les dossiers d’emprunteurs. Chaque décision porte un reçu signé par l’enclave, à montrer à un auditeur ou à un régulateur.</li><li>Un agent de recherche achète trois réponses privées pour 0,03&#160;USDC au total en comparant des fournisseurs&#160;: sans clé d’API, sans inscription.</li></ul></div><aside class=\"vit-side\"><div class=\"vit-side-b\"><h3 class=\"vit-h4\">Pourquoi une machine scellée</h3><p class=\"vit-side-why\">Votre requête doit rester illisible pour l’opérateur qui fait tourner la machine, et pour nous. Seule l’isolation matérielle, avec une attestation que le contrat vérifie, le permet. Et le reçu lie chaque paiement à cette machine vérifiée.</p></div><div class=\"vit-side-b\"><h3 class=\"vit-h4\">Prix et qui paie</h3><dl class=\"kv-list vit-kv vit-kv-side\"><div class=\"kv-row\"><dt>Session</dt><dd><span class=\"mono tnum vit-tag\">0,10 USDC les 1&#160;000 jetons</span><span class=\"lbl muted vit-same\">prix de démo du testnet, élevé pour que chaque paiement se voie sur l’explorateur</span></dd></div><div class=\"kv-row\"><dt>À l’appel, x402</dt><dd><span class=\"mono tnum vit-tag\">0,01 USDC l’appel</span><span class=\"lbl muted vit-same\">lu sur Arc</span></dd></div><div class=\"kv-row\"><dt>Partage</dt><dd>95&#160;% opérateur, 5&#160;% réseau</dd></div><div class=\"kv-row\"><dt>Qui paie</dt><dd>L’utilisateur ou l’agent, depuis son propre wallet. Un dépôt reste dans le contrat et la part non utilisée revient.</dd></div><div class=\"kv-row\"><dt>Prix prévu sur le mainnet, une proposition</dt><dd>Environ 0,20&#160;$ le million de jetons en entrée et 0,80&#160;$ en sortie. Les appels à partir de 0,10&#160;USDC, en dessous une session.</dd></div></dl></div><div class=\"vit-side-b\"><h3 class=\"vit-h4\">Aujourd’hui</h3><p class=\"vit-side-today\"><span class=\"led led-amber\" aria-hidden=\"true\"></span>En service sur la pile v3 : sessions et paiements à l’appel sont possibles dès maintenant.</p><p class=\"lbl vit-k\">Ce qui marche encore</p><ul class=\"vit-still\"><li>La chaîne de preuves (GET /api/proof) et la vérification des reçus (POST /api/verify-receipt).</li><li>Chaque contrat et chaque paiement passé, sur l’explorateur.</li><li>Le code client du SDK, dans le dépôt.</li></ul></div><div class=\"vit-side-acts\"><a class=\"btn btn-main btn-s\" href=\"/space.html?tab=sessions&amp;p=1\"><span>Ouvrir une session</span></a><a class=\"btn btn-line btn-s\" href=\"/network.html?focus=demo\"><span>Voir le rejeu</span></a><a class=\"tlink\" href=\"/doc.html?c=privacy\">Comment Arc le vérifie, en détail</a><a data-vt-ch=\"build\" class=\"tlink\" href=\"?c=build\">Pour les développeurs</a></div></aside></div><div class=\"vit-fam-more\"><p class=\"lbl vit-k vit-more-k\">En détail</p><details class=\"vit-more\"><summary><span class=\"vit-more-t\">Le problème, en chiffres</span><span class=\"mono vit-more-n\">4</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><ul class=\"vit-list\"><li>Dossiers juridiques, données de santé, dossiers de crédit et code non publié ne peuvent pas partir vers une API d’IA ordinaire&#160;: personne ne peut vérifier qui lit la requête, et rien ne prouve ce qui a été payé.</li><li>Apple, Google et Meta ont fait de l’IA confidentielle attestée la norme pour leurs propres utilisateurs. Un développeur indépendant ne peut pas acheter la même chose à l’usage, en USDC, avec un contrat qui la vérifie.</li><li>Dans l’UE, une IA de notation de crédit devra journaliser ses événements automatiquement à partir du 2 décembre 2027 (AI Act, article 12).</li><li>Les agents ne peuvent ni ouvrir de compte ni taper un numéro de carte. x402 leur permet de payer à la requête, mais sans aucune preuve qu’une machine vérifiée a servi l’appel.</li></ul><p class=\"lbl muted vit-src-l\">Source&#160;: Notre recherche du 1er novembre 2026&#160;: pages des fournisseurs, AI Act européen.</p></div></details><details class=\"vit-more\"><summary><span class=\"vit-more-t\">Qui l’achète, et les preuves</span><span class=\"mono vit-more-n\">4</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><dl class=\"vit-personas\"><div><dt>Les cabinets d’avocats et les équipes juridiques</dt><dd>Ils doivent protéger le secret des documents de leurs clients. Les fournisseurs d’IA en enclave leur vendent déjà, et ils citent la confidentialité comme premier frein à l’IA.</dd></div><div><dt>Les équipes crédit, KYC et fraude, crédit DeFi compris</dt><dd>Dans l’UE, leur IA devra journaliser ses décisions dès décembre 2027. Deux lauréats de hackathons d’Arc en 2026 faisaient déjà tourner une IA de souscription dans des enclaves louées.</dd></div><div><dt>Les auditeurs et développeurs au code privé</dt><dd>Ils veulent qu’un LLM lise un code que personne, pas même l’hébergeur, ne peut voir.</dd></div><div><dt>Les créateurs d’agents d’IA</dt><dd>Une signature par appel, sans compte ni dépôt&#160;: un agent peut payer seul.</dd></div></dl></div></details><details class=\"vit-more\"><summary><span class=\"vit-more-t\">Ce qui est garanti, et par quel contrôle</span><span class=\"mono vit-more-n\">8</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><ul class=\"vit-guar\"><li><p class=\"vit-guar-w\">Seule une enclave admise par Arc (signature d’Intel, code autorisé, opérateur sous caution) peut signer un reçu payable.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Contrôlé par</span> <code class=\"mono vit-code\">SessionPay.settle, EnclaveRegistry.activeOperatorAt</code></p></li><li><p class=\"vit-guar-w\">Une session est liée à une enclave et à un opérateur. Prix, modèle et unité de facturation sont figés à l’ouverture.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Contrôlé par</span> <code class=\"mono vit-code\">WrongEnclave, WrongOperator, ModelMismatch</code></p></li><li><p class=\"vit-guar-w\">Vous ne pouvez jamais être facturé plus que votre dépôt. Le reste revient à la clôture.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Contrôlé par</span> <code class=\"mono vit-code\">SessionPay.settle, SessionPay.closeSession</code></p></li><li><p class=\"vit-guar-w\">Deux reçus différents pour la même étape prouvent la triche&#160;: toute la caution est saisie, moitié au rapporteur, moitié à la victime, et l’opérateur est banni.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Contrôlé par</span> <code class=\"mono vit-code\">SessionPay.reportEquivocation, OperatorBond.slash</code></p></li><li><p class=\"vit-guar-w\">Ce qu’un opérateur peut encaisser sur la seule parole de ses enclaves est plafonné&#160;: la moitié de sa caution disponible (sa caution moins tout retrait demandé) sur 24 heures glissantes, et 10&#160;USDC par produit sur les mêmes 24 heures sur le testnet.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Contrôlé par</span> <code class=\"mono vit-code\">OperatorBond.consumeExposure</code></p></li><li><p class=\"vit-guar-w\">Une autorisation signée paie exactement un appel, exactement à son prix, et ne peut pas être rejouée.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Contrôlé par</span> <code class=\"mono vit-code\">X402Settler.settle, receiveWithAuthorization</code></p></li><li><p class=\"vit-guar-w\">Votre app refuse de chiffrer pour une clé qu’Arc ne connaît pas.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Contrôlé par</span> <code class=\"mono vit-code\">le SDK lit d’abord EnclaveRegistry</code></p></li><li class=\"is-not\"><p class=\"vit-guar-w\">Non garanti&#160;: que la réponse de l’IA soit juste. Une machine ne peut pas vérifier une réponse, elle ne justifie donc jamais de saisir une caution.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Contrôlé par</span> <code class=\"mono vit-code\">par conception</code></p></li></ul></div></details><details class=\"vit-more\"><summary><span class=\"vit-more-t\">Les limites, sans détour</span><span class=\"mono vit-more-n\">6</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><ul class=\"vit-list\"><li>Le modèle ne tourne pas dans notre enclave. Notre enclave vérifie l’enclave du fournisseur du modèle (la passerelle de RedPill, gpt-oss-120b servi par Tinfoil) avant chaque appel. Restent de confiance&#160;: le code de cette passerelle, son propre contrôle en amont, le service de collatéral de Phala et la garde des clés de sa pile.</li><li>Le prix du testnet, 100&#160;USDC le million de jetons, vaut environ 500 fois notre prix prévu sur le mainnet pour les jetons en entrée.</li><li>Un seul opérateur sur une seule machine physique&#160;: pas encore décentralisé.</li><li>Chaque payeur jusqu’ici est notre propre wallet. Aucun client extérieur n’a encore payé.</li><li>Un reçu gonflé par une enclave falsifiée ne peut pas être prouvé faux&#160;: la caution plafonne le dommage par 24 heures, elle ne le rembourse pas.</li><li>Les clients x402 standard ne peuvent pas l’appeler, car la requête est chiffrée&#160;: utilisez le SDK d’ArcHive.</li></ul></div></details></div>"},{"id":"attested-copilot","cls":"vit-sec vit-fam","k":"Produit n° 4","t":"Copilote attesté","plain":"Copilote attesté","units":"#4","body":"<header class=\"vit-fam-hd is-arc\"><h2 aria-label=\"Copilote attesté\" class=\"vt-h vit-fam-name\" id=\"copilot-h\">Copilote attesté<span class=\"ttl-rule\" aria-hidden=\"true\"></span></h2><p class=\"vit-fam-head\">Un assistant que vous pouvez vérifier.</p><p class=\"lede vit-fam-sub\">AskHive, l’assistant d’ArcHive, dans sa propre enclave. Votre navigateur vérifie sa clé sur Arc et chiffre toute la conversation pour elle&#160;: notre serveur web ne relaie que du chiffré. Il est gratuit.</p></header><ul class=\"vit-tiers is-one\"><li class=\"vit-tier\" data-pid=\"4\"><span class=\"blade vit-face\" data-led=\"amber\" data-long=\"0\" aria-hidden=\"true\"><span class=\"blade-face\"><span class=\"bl-led\"><i></i></span><span class=\"bl-title\">Copilote</span><span class=\"bl-word\">À l’arrêt</span><span class=\"bl-u\">#4</span></span></span><h3 class=\"vit-tier-n\">Copilote attesté</h3><dl class=\"kv-list vit-kv\"><div class=\"kv-row\"><dt>Pour</dt><dd>Quiconque veut de l’aide sur ArcHive sans faire confiance à notre serveur.</dd></div><div class=\"kv-row\"><dt>Ce qu’il fait</dt><dd>Il explique, vous montre le site et prépare ce que vous signez. Rien n’est dépensé sans votre signature.</dd></div><div class=\"kv-row\"><dt>Prix</dt><dd>Gratuit, prix 0 sur Arc</dd></div><div class=\"kv-row\"><dt>Contrat</dt><dd><a class=\"tlink vit-addr\" href=\"https://explorer.testnet.arc.io/address/0xc854ebA7C28f4b53f50018EAcF40D617Ba76e38E\" target=\"_blank\" rel=\"noreferrer\"><span>EnclaveRegistry</span> <span class=\"mono\">0xc854…e38E</span></a></dd></div></dl><div class=\"vit-tier-go\"><a data-vt-copilot=\"\" class=\"btn btn-main btn-s\" href=\"#copilot\"><span>Demander au copilote</span></a></div></li></ul><div class=\"vit-fam-body\"><div class=\"vit-fam-main\"><h3 class=\"vit-h3\">Comment ça marche</h3><ol class=\"path vit-steps\"><li class=\"row path-s\"><span class=\"path-n mono\" aria-hidden=\"true\">01</span><div class=\"path-b\"><h4 class=\"path-t\">Votre navigateur lit le copilote sur Arc</h4><p class=\"path-d\">Il lit sur Arc l’enclave du produit 4, l’empreinte de son code et son opérateur, et vérifie sa clé.</p><p class=\"vit-step-c\"><code class=\"mono vit-code\">EnclaveRegistry</code></p></div></li><li class=\"row path-s\"><span class=\"path-n mono\" aria-hidden=\"true\">02</span><div class=\"path-b\"><h4 class=\"path-t\">Il chiffre votre question pour cette clé</h4><p class=\"path-d\">Le proxy du site ne fait suivre que du chiffré, et l’enclave n’accepte les questions que par ce proxy.</p><p class=\"vit-step-c\"><code class=\"mono vit-code\">HPKE</code></p></div></li><li class=\"row path-s\"><span class=\"path-n mono\" aria-hidden=\"true\">03</span><div class=\"path-b\"><h4 class=\"path-t\">L’enclave répond, scellé pour vous</h4><p class=\"path-d\">Elle vérifie d’abord le fournisseur du modèle, répond, et scelle la réponse pour votre navigateur.</p><p class=\"vit-step-c\"><code class=\"mono vit-code\">RedPill gateway</code></p></div></li><li class=\"row path-s\"><span class=\"path-n mono\" aria-hidden=\"true\">04</span><div class=\"path-b\"><h4 class=\"path-t\">Ses instructions ne peuvent pas changer en silence</h4><p class=\"path-d\">De nouvelles instructions, c’est un nouveau code, une nouvelle empreinte et une nouvelle inscription sur Arc.</p><p class=\"vit-step-c\"><code class=\"mono vit-code\">ProductRegistry.isWorkloadAllowed</code></p></div></li></ol><h3 class=\"vit-h3\">Preuves sur Arc</h3><p class=\"lbl muted vit-h3-l\">De vraies transactions sur Arc testnet, faites sur la pile v2.1 avant le passage à la v3. Chacune s’ouvre sur l’explorateur.</p><div class=\"vit-rcpts\"><figure class=\"vit-rcpt is-arc\"><figcaption class=\"vit-rcpt-h\"><span class=\"vit-rcpt-t\">Admission sur Arc</span><span class=\"mono tnum vit-rcpt-d\">10 nov. 2026, 22:01:26 UTC</span></figcaption><dl class=\"vit-rcpt-l\"><div><dt>Signature d’Intel sur la machine</dt><dd class=\"mono tnum\">vérifiée</dd></div><div><dt>Journal de démarrage, octet par octet</dt><dd class=\"mono tnum\">rejoué</dd></div><div><dt>Empreinte du code</dt><dd class=\"mono tnum\">autorisée</dd></div><div class=\"is-total\"><dt>Gaz, payé par l’opérateur</dt><dd class=\"mono tnum\">6 849 050</dd></div></dl><p class=\"vit-rcpt-n\">L’enclave du copilote, avec le code qui vérifie son fournisseur de modèle. De bout en bout le 9 novembre&#160;: clé vérifiée sur Arc, question chiffrée, réponse scellée, en anglais et en français.</p><p class=\"vit-rcpt-x\"><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0xad8b9780689513b1f68b8aba1a99f1b3156b4038a86aff46cad5ff96e294005e\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Ouvrir sur l’explorateur: 0xad8b9780689513b1f68b8aba1a99f1b3156b4038a86aff46cad5ff96e294005e\">0xad8b9780…005e</a></p></figure></div><ol class=\"vit-proofs\"><li class=\"vit-proof\"><span class=\"mono tnum vit-proof-at\">10 nov., 22:01:26 UTC</span><span class=\"vit-proof-w\">Enclave du copilote admise par la signature d’Intel et le rejeu de son journal de démarrage</span><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0xad8b9780689513b1f68b8aba1a99f1b3156b4038a86aff46cad5ff96e294005e\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Ouvrir sur l’explorateur: 0xad8b9780689513b1f68b8aba1a99f1b3156b4038a86aff46cad5ff96e294005e\">0xad8b9780…005e</a></li><li class=\"vit-proof\"><span class=\"mono tnum vit-proof-at\">19 nov., 22:37:58 UTC</span><span class=\"vit-proof-w\">Enclave d’AskHive admise de nouveau, de la même façon</span><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0xde9628b23d0483bb666a0cd13c55c4f32a1204151323a80da9451b0aeb330176\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Ouvrir sur l’explorateur: 0xde9628b23d0483bb666a0cd13c55c4f32a1204151323a80da9451b0aeb330176\">0xde9628b2…0176</a></li></ol><h3 class=\"vit-h3\">À quoi il servirait</h3><ul class=\"vit-uses\"><li>Un utilisateur demande si une enclave est vérifiée et ce que coûterait une caution, sans que le site apprenne sa stratégie.</li><li>Le support d’une DAO reprend le même schéma&#160;: les membres peuvent vérifier à quelle consigne et quelle base de connaissances ils parlent.</li><li>L’accueil des opérateurs et des auteurs&#160;: le copilote explique chaque étape et prépare la transaction, l’humain signe.</li></ul></div><aside class=\"vit-side\"><div class=\"vit-side-b\"><h3 class=\"vit-h4\">Pourquoi une machine scellée</h3><p class=\"vit-side-why\">Les instructions de l’assistant sont mesurées, elles ne peuvent donc pas changer en silence, et la conversation est scellée à l’abri de notre serveur web.</p></div><div class=\"vit-side-b\"><h3 class=\"vit-h4\">Prix et qui paie</h3><dl class=\"kv-list vit-kv vit-kv-side\"><div class=\"kv-row\"><dt>Prix</dt><dd>Gratuit&#160;: le produit 4 a un prix de 0 sur Arc.</dd></div><div class=\"kv-row\"><dt>Qui paie</dt><dd>Personne. Aucun wallet n’est nécessaire pour demander.</dd></div></dl></div><div class=\"vit-side-b\"><h3 class=\"vit-h4\">Aujourd’hui</h3><p class=\"vit-side-today\"><span class=\"led led-amber\" aria-hidden=\"true\"></span>AskHive, l’assistant dans le coin de chaque page, tourne dans cette enclave. Il montre les pages en expliquant et prépare les opérations que vous signez avec votre propre wallet.</p><p class=\"lbl vit-k\">Où le trouver</p><ul class=\"vit-still\"><li>AskHive, dans le coin de chaque page.</li><li>Son inscription et son code, lisibles sur Arc.</li></ul></div><div class=\"vit-side-acts\"><a data-vt-copilot=\"\" class=\"btn btn-main btn-s\" href=\"#copilot\"><span>Demander au copilote</span></a><a class=\"btn btn-line btn-s\" href=\"/network.html?focus=demo\"><span>Voir le rejeu</span></a><a class=\"tlink\" href=\"/doc.html\">Comment Arc le vérifie, en détail</a><a data-vt-ch=\"build\" class=\"tlink\" href=\"?c=build\">Pour les développeurs</a></div></aside></div><div class=\"vit-fam-more\"><p class=\"lbl vit-k vit-more-k\">En détail</p><details class=\"vit-more\"><summary><span class=\"vit-more-t\">Le problème, en chiffres</span><span class=\"mono vit-more-n\">1</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><ul class=\"vit-list\"><li>L’assistant d’un site voit tout ce que vous tapez, et le site peut changer ce qu’il dit. Vous ne pouvez vérifier ni l’un ni l’autre.</li></ul><p class=\"lbl muted vit-src-l\">Source&#160;: Notre analyse.</p></div></details><details class=\"vit-more\"><summary><span class=\"vit-more-t\">Qui l’achète, et les preuves</span><span class=\"mono vit-more-n\">3</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><dl class=\"vit-personas\"><div><dt>Les utilisateurs de wallets et de dApps aux questions sensibles</dt><dd>Le serveur intermédiaire ne voit que du chiffré.</dd></div><div><dt>Les équipes qui veulent un assistant de support auditable</dt><dd>Le code du copilote, consigne comprise, est épinglé sur Arc par son empreinte. Chaque changement de consigne a donné un nouveau code.</dd></div><div><dt>Les juges et développeurs qui découvrent ArcHive</dt><dd>Gratuit, et dans le coin de chaque page.</dd></div></dl></div></details><details class=\"vit-more\"><summary><span class=\"vit-more-t\">Ce qui est garanti, et par quel contrôle</span><span class=\"mono vit-more-n\">4</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><ul class=\"vit-guar\"><li><p class=\"vit-guar-w\">Votre navigateur ne parle qu’à une clé admise par Arc pour le produit 4, avec un code autorisé.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Contrôlé par</span> <code class=\"mono vit-code\">EnclaveRegistry, lu par votre navigateur</code></p></li><li><p class=\"vit-guar-w\">Notre serveur web ne peut pas lire la conversation.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Contrôlé par</span> <code class=\"mono vit-code\">HPKE, vers la clé de l’enclave</code></p></li><li><p class=\"vit-guar-w\">Changer ses instructions, c’est un nouveau code, une nouvelle empreinte et une nouvelle inscription sur Arc.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Contrôlé par</span> <code class=\"mono vit-code\">ProductRegistry.isWorkloadAllowed</code></p></li><li class=\"is-not\"><p class=\"vit-guar-w\">Non garanti&#160;: que les réponses soient justes. Les enclaves attestées du fournisseur du modèle voient la conversation.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Contrôlé par</span> <code class=\"mono vit-code\">par conception</code></p></li></ul></div></details><details class=\"vit-more\"><summary><span class=\"vit-more-t\">Les limites, sans détour</span><span class=\"mono vit-more-n\">2</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><ul class=\"vit-list\"><li>Il explique et prépare, il ne signe jamais.</li><li>Ses connaissances peuvent être en retard sur le produit.</li></ul></div></details></div>"},{"id":"refutation","cls":"vit-sec vit-fam is-red","k":"Produit n° 5 de la v2.1","t":"Tricher coûte","plain":"Tricher coûte","units":"v2.1 #5","body":"<header class=\"vit-fam-hd is-red\"><h2 aria-label=\"Tricher coûte\" class=\"vt-h vit-fam-name\" id=\"refutation-h\">Tricher coûte<span class=\"ttl-rule\" aria-hidden=\"true\"></span></h2><p class=\"vit-fam-head\">Qui triche perd sa caution.</p><p class=\"lede vit-fam-sub\">Un vrai test sur Arc, sur la pile v2.1, où c’était le produit 5&#160;: une enclave construite pour mentir a gonflé une perte. Deux autres enclaves ont rejoué l’exploit et prouvé que la réclamation était fausse. Rien n’a été payé, toute la caution du menteur a été saisie et son opérateur banni.</p></header><div class=\"vit-refute\" data-pid=\"v21-5\"><span class=\"blade vit-face\" data-led=\"red\" data-long=\"0\" aria-hidden=\"true\"><span class=\"blade-face\"><span class=\"bl-led\"><i></i></span><span class=\"bl-title\">Pris à mentir</span><span class=\"bl-word\">Caution saisie</span><span class=\"bl-u\">v2.1 #5</span></span></span><div class=\"vit-tl-w\"><p class=\"lbl vit-k\">Quatre transactions, 10 novembre 2026, UTC</p><ol class=\"vit-tl\"><li class=\"row\"><span class=\"mono tnum vit-tl-at\">00:06:17</span><div class=\"vit-tl-b\"><h3 class=\"vit-tl-t\">Le menteur est admis comme les autres</h3><p class=\"vit-tl-d\">Son code fautif est mesuré par Intel et Arc, pas caché. Trois opérateurs avec 1&#160;USDC de caution chacun&#160;: un ment, deux sont honnêtes.</p><p class=\"vit-tl-x\"><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0xd73094e863eccd11500410b8041ba696b7a63d0628d9ac8d077d89434b98a23e\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Ouvrir sur l’explorateur: 0xd73094e863eccd11500410b8041ba696b7a63d0628d9ac8d077d89434b98a23e\">0xd73094e8…a23e</a></p></div></li><li class=\"row\"><span class=\"mono tnum vit-tl-at\">00:07:12</span><div class=\"vit-tl-b\"><h3 class=\"vit-tl-t\">Une prime est publiée</h3><p class=\"vit-tl-d\">Cagnotte de 1&#160;USDC, palier de 0,5&#160;USDC pour une perte d’au moins 1&#160;USDC, sur un coffre de démo qui contient 1&#160;USDC.</p><p class=\"vit-tl-x\"><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0x1b8511cc75871cf79e09b011a0598fc333cba4a0900155ce6c7acbaafaa2de99\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Ouvrir sur l’explorateur: 0x1b8511cc75871cf79e09b011a0598fc333cba4a0900155ce6c7acbaafaa2de99\">0x1b8511cc…de99</a></p></div></li><li class=\"row\"><span class=\"mono tnum vit-tl-at\">00:07:24</span><div class=\"vit-tl-b\"><h3 class=\"vit-tl-t\">Le mensonge est accepté</h3><p class=\"vit-tl-d\">Le menteur réclame une perte de 2&#160;USDC. Arc vérifie sa signature et accepte la réclamation&#160;: le paiement est réservé, pas versé.</p><p class=\"vit-tl-x\"><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0x6aee80e974458ba251d75d7d82f8bfe361006fc328fc1416816221a2e76eb0ea\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Ouvrir sur l’explorateur: 0x6aee80e974458ba251d75d7d82f8bfe361006fc328fc1416816221a2e76eb0ea\">0x6aee80e9…b0ea</a><span class=\"lbl muted\">bloc 71 620 107</span></p></div></li><li class=\"row\"><span class=\"mono tnum vit-tl-at\">00:07:40</span><div class=\"vit-tl-b\"><h3 class=\"vit-tl-t\">Réfuté, 16 secondes plus tard</h3><p class=\"vit-tl-d\">Les deux enclaves honnêtes rejouent l’exploit au même bloc et trouvent une perte de 1&#160;USDC. Le contrat saisit toute la caution du menteur, bannit son opérateur, rétablit la cagnotte et écrit le verdict 0.</p><p class=\"vit-tl-x\"><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0x0ffca5433186735bf5525e525995f3589d842681da8ffcaa82acb5993025051f\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Ouvrir sur l’explorateur: 0x0ffca5433186735bf5525e525995f3589d842681da8ffcaa82acb5993025051f\">0x0ffca543…051f</a><span class=\"lbl muted\">bloc 71 620 138</span></p></div></li></ol></div></div><div class=\"vit-fam-body\"><div class=\"vit-fam-main\"><h3 class=\"vit-h3\">Preuves sur Arc</h3><p class=\"lbl muted vit-h3-l\">De vraies transactions sur Arc testnet, faites sur la pile v2.1 avant le passage à la v3. Chacune s’ouvre sur l’explorateur.</p><div class=\"vit-rcpts\"><figure class=\"vit-rcpt is-red\"><figcaption class=\"vit-rcpt-h\"><span class=\"vit-rcpt-t\">Reçu de réfutation</span><span class=\"mono tnum vit-rcpt-d\">10 nov. 2026, 00:07:40 UTC</span></figcaption><dl class=\"vit-rcpt-l\"><div><dt>Perte réclamée par le menteur</dt><dd class=\"mono tnum\">2,00<span class=\"vit-u\"> USDC</span></dd></div><div><dt>Perte réelle, rejouée par 2 autres opérateurs</dt><dd class=\"mono tnum\">1,00<span class=\"vit-u\"> USDC</span></dd></div><div><dt>Payé au menteur</dt><dd class=\"mono tnum\">0,00<span class=\"vit-u\"> USDC</span></dd></div><div class=\"is-total\"><dt>Caution saisie</dt><dd class=\"mono tnum\">1,00<span class=\"vit-u\"> USDC</span></dd></div><div class=\"is-extra\"><dt>à qui l’a prouvé</dt><dd class=\"mono tnum\">0,50&#160;USDC</dd></div><div class=\"is-extra\"><dt>à la victime</dt><dd class=\"mono tnum\">0,50&#160;USDC</dd></div><div class=\"is-extra\"><dt>Opérateur</dt><dd class=\"mono tnum\">banni</dd></div><div class=\"is-extra\"><dt>Verdict ERC-8004</dt><dd class=\"mono tnum\">0</dd></div></dl><p class=\"vit-rcpt-n\">16 secondes entre le mensonge accepté et la caution saisie. Le parcours complet tient en 29 transactions sur Arc.</p><p class=\"vit-rcpt-x\"><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0x0ffca5433186735bf5525e525995f3589d842681da8ffcaa82acb5993025051f\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Ouvrir sur l’explorateur: 0x0ffca5433186735bf5525e525995f3589d842681da8ffcaa82acb5993025051f\">0x0ffca543…051f</a></p></figure></div><h3 class=\"vit-h3\">À quoi il servirait</h3><ul class=\"vit-uses\"><li>Un assureur paie des sinistres sur des pertes rejouées par des enclaves, car une fausse réclamation peut être renversée en 3&#160;jours et le menteur perd sa caution.</li><li>Un protocole exige que deux opérateurs distincts signent ses gros paliers.</li><li>Tout acheteur lit le dossier public ERC-8004 d’un opérateur avant de lui faire confiance. Le menteur y a 0.</li></ul></div><aside class=\"vit-side\"><div class=\"vit-side-b\"><h3 class=\"vit-h4\">Pourquoi c’est important</h3><p class=\"vit-side-why\">Une enclave peut être attaquée par quelqu’un qui a accès physiquement au serveur. Un résultat est donc fiable parce qu’un mensonge est pris et coûte de l’argent, pas parce que le matériel est parfait.</p></div><div class=\"vit-side-b\"><h3 class=\"vit-h4\">Prix et qui paie</h3><dl class=\"kv-list vit-kv vit-kv-side\"><div class=\"kv-row\"><dt>Prix</dt><dd>Pas à vendre. Une démonstration gardée sur Arc comme preuve. Sa règle s’applique à chaque produit.</dd></div><div class=\"kv-row\"><dt>La règle de caution</dt><dd>Toute la caution, moitié pour qui prouve la faute, moitié pour la victime. Retirer une caution prend 7&#160;jours&#160;: un opérateur ne peut pas fuir avant.</dd></div><div class=\"kv-row\"><dt>Le plafond</dt><dd>Sur la seule parole de ses enclaves, un opérateur encaisse au plus la moitié de sa caution disponible (sa caution moins tout retrait demandé) sur 24 heures glissantes, et au plus le plafond du produit. Une enclave falsifiée ne peut pas prendre plus avant de tout perdre.</dd></div></dl></div><div class=\"vit-side-b\"><h3 class=\"vit-h4\">Aujourd’hui</h3><p class=\"vit-side-today\"><span class=\"led led-red\" aria-hidden=\"true\"></span>Fait le 10 novembre, lisible pour toujours sur Arc. Le rejouer en direct demande trois machines.</p><p class=\"lbl vit-k\">Ce qui marche encore</p><ul class=\"vit-still\"><li>Les quatre transactions, sur l’explorateur.</li><li>Le menteur, affiché comme pris à mentir dans la Ruche de la console et dans la salle 3D.</li></ul></div><div class=\"vit-side-acts\"><a class=\"btn btn-main btn-s\" href=\"https://explorer.testnet.arc.io/tx/0x0ffca5433186735bf5525e525995f3589d842681da8ffcaa82acb5993025051f\" target=\"_blank\" rel=\"noreferrer\"><span>Ouvrir la réfutation sur Arc</span></a><a class=\"btn btn-line btn-s\" href=\"@hive\"><span>Voir le menteur dans la Ruche</span></a><a class=\"tlink\" href=\"/doc.html?c=stakes\">Comment Arc le vérifie, en détail</a><a class=\"tlink\" href=\"@dc\">Le voir dans la salle 3D</a></div></aside></div><div class=\"vit-fam-more\"><p class=\"lbl vit-k vit-more-k\">En détail</p><details class=\"vit-more\"><summary><span class=\"vit-more-t\">Le problème, en chiffres</span><span class=\"mono vit-more-n\">2</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><ul class=\"vit-list\"><li>Des attaques avec accès physique ont falsifié des attestations d’enclave en 2025 et 2026 (TEE.fail, Battering RAM, Wiretap), l’une avec moins de 200&#160;$ de matériel.</li><li>Les acheteurs doivent savoir qu’un mensonge est détecté et puni, pas seulement que le matériel est de confiance.</li></ul><p class=\"lbl muted vit-src-l\">Source&#160;: Notre recherche du 1er novembre 2026, attaques publiées.</p></div></details><details class=\"vit-more\"><summary><span class=\"vit-more-t\">Qui l’achète, et les preuves</span><span class=\"mono vit-more-n\">3</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><dl class=\"vit-personas\"><div><dt>Les protocoles et assureurs qui se demandent s’ils peuvent s’appuyer sur des résultats d’enclave</dt><dd>Tout le chemin de preuve de faute, de bout en bout, sur Arc.</dd></div><div><dt>Les opérateurs</dt><dd>Il montre la règle qu’ils acceptent en déposant une caution.</dd></div><div><dt>Les juges</dt><dd>Le parcours complet tient en 29 transactions sur Arc.</dd></div></dl></div></details><details class=\"vit-more\"><summary><span class=\"vit-more-t\">Ce qui est garanti, et par quel contrôle</span><span class=\"mono vit-more-n\">3</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><ul class=\"vit-guar\"><li><p class=\"vit-guar-w\">Une réfutation demande au moins 2 opérateurs distincts, plus que les signataires de la réclamation et aucun d’entre eux, dans les 3&#160;jours.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Contrôlé par</span> <code class=\"mono vit-code\">SealedBounty.refute, REFUTE_QUORUM, REFUTE_WINDOW</code></p></li><li><p class=\"vit-guar-w\">Toute la caution est saisie et l’opérateur est banni de toute nouvelle caution.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Contrôlé par</span> <code class=\"mono vit-code\">OperatorBond.slash, banned</code></p></li><li><p class=\"vit-guar-w\">Un paiement non livré est annulé et la cagnotte rétablie.</p><p class=\"vit-guar-c\"><span class=\"lbl vit-k\">Contrôlé par</span> <code class=\"mono vit-code\">SealedBounty.refute, livraison bloquée</code></p></li></ul></div></details><details class=\"vit-more\"><summary><span class=\"vit-more-t\">Les limites, sans détour</span><span class=\"mono vit-more-n\">2</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><ul class=\"vit-list\"><li>Les trois opérateurs étaient des clés de démo tenues par notre équipe, sous des adresses distinctes.</li><li>Des opérateurs distincts, pas encore des machines distinctes&#160;: les trois enclaves tournaient sur le même serveur physique.</li></ul></div></details></div>"},{"id":"retired","cls":"vit-sec vit-fam is-off","k":"Produit n° 6 de la v2.1","t":"Retiré","plain":"Retiré","units":"v2.1 #6","body":"<header class=\"vit-fam-hd is-off\"><h2 aria-label=\"Retiré\" class=\"vt-h vit-fam-name\" id=\"retired-h\">Retiré<span class=\"ttl-rule\" aria-hidden=\"true\"></span></h2><p class=\"vit-fam-head\">La première prime vérifiée, coupée par notre propre revue.</p><p class=\"lede vit-fam-sub\">Notre propre revue de sécurité a durci sa lecture de la puce, et les contrats corrigés ont été redéployés en quelques heures. Le contrat de paiement d’un produit ne change jamais&#160;: le produit 6 a été coupé le 10 novembre et la prime vérifiée est revenue comme produit 7, sur la pile v2.1. Sur la pile v3, déployée le 19 novembre, c’est le produit 5.</p></header><div class=\"vit-retired\" data-pid=\"v21-6\"><ol class=\"path vit-steps\"><li class=\"row path-s\"><span class=\"path-n mono\" aria-hidden=\"true\">01</span><div class=\"path-b\"><h4 class=\"path-t\">La faille</h4><p class=\"path-d\">Un morceau falsifié et non signé du certificat d’Intel pouvait faire lire au contrat un identifiant de puce choisi par l’attaquant, et passer pour une machine d’un datacenter connu.</p><p class=\"vit-step-c\"><code class=\"mono vit-code\">PckChip</code></p></div></li><li class=\"row path-s\"><span class=\"path-n mono\" aria-hidden=\"true\">02</span><div class=\"path-b\"><h4 class=\"path-t\">Le correctif</h4><p class=\"path-d\">La lecture de la puce décode désormais le certificat exactement comme le vérificateur d’Intel et n’accepte qu’un seul certificat. Trois agents adverses ont réattaqué le correctif sans trouver de nouvelle faille.</p><p class=\"vit-step-c\"><code class=\"mono vit-code\">test_chip_rejectsForgedPpid</code></p></div></li><li class=\"row path-s\"><span class=\"path-n mono\" aria-hidden=\"true\">03</span><div class=\"path-b\"><h4 class=\"path-t\">La bascule</h4><p class=\"path-d\">La politique du produit 6 pointe désormais vers un auditeur mort&#160;: aucune machine ne peut plus s’y qualifier. Il n’a jamais rien payé, et aucune caution n’a jamais été en jeu.</p><p class=\"vit-step-c\"><code class=\"mono vit-code\">meetsPolicy(6, any) = false</code></p></div></li></ol><div class=\"vit-retired-side\"><span class=\"blade vit-face\" data-led=\"off\" data-long=\"1\" aria-hidden=\"true\"><span class=\"blade-face\"><span class=\"bl-led\"><i></i></span><span class=\"bl-title\">Prime scellée, vérifiée</span><span class=\"bl-word\">v2.1&#160;: remplacé par le n°&#160;7</span><span class=\"bl-u\">v2.1 #6</span></span></span><ol class=\"vit-proofs\"><li class=\"vit-proof\"><span class=\"mono tnum vit-proof-at\">10 nov.</span><span class=\"vit-proof-w\">Produit 6 proposé</span><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0x5c1afdd6147572257c9627b349b9472b548453025e161bcbd5bfc8f30115c545\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Ouvrir sur l’explorateur: 0x5c1afdd6147572257c9627b349b9472b548453025e161bcbd5bfc8f30115c545\">0x5c1afdd6…c545</a></li><li class=\"vit-proof\"><span class=\"mono tnum vit-proof-at\">10 nov.</span><span class=\"vit-proof-w\">Coupure proposée&#160;: sa politique pointée vers un auditeur mort</span><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0xf91db064e176beafcecfec37f578898919526daed11e1b1fb181b8da86685be3\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Ouvrir sur l’explorateur: 0xf91db064e176beafcecfec37f578898919526daed11e1b1fb181b8da86685be3\">0xf91db064…5be3</a></li><li class=\"vit-proof\"><span class=\"mono tnum vit-proof-at\">10 nov.</span><span class=\"vit-proof-w\">Coupure appliquée&#160;: aucune machine ne peut s’y qualifier</span><a class=\"tlink mono vit-tx\" href=\"https://explorer.testnet.arc.io/tx/0x190d464ee073cb9582c303c291c120aa53c48f9b00b127a1487c0dd08484b4cb\" target=\"_blank\" rel=\"noreferrer\" aria-label=\"Ouvrir sur l’explorateur: 0x190d464ee073cb9582c303c291c120aa53c48f9b00b127a1487c0dd08484b4cb\">0x190d464e…b4cb</a></li></ol><p class=\"lbl muted vit-retired-n\">Le registre l’affiche encore comme actif, car l’état d’un produit ne change pas en le rebranchant. C’est sa politique qui le coupe.</p><a class=\"btn btn-line btn-s\" href=\"/service.html?p=5\"><span>Utiliser le produit 5, sur la v3</span></a></div></div>"},{"id":"compare","cls":"vit-sec vit-compare","k":"Comparer","t":"Comparer","plain":"ArcHive face à l’existant.","units":"","body":"<h2 aria-label=\"ArcHive face à l’existant.\" class=\"vt-h vit-h2\" id=\"compare-h\">ArcHive face à l’existant.<span class=\"ttl-rule\" aria-hidden=\"true\"></span></h2><p class=\"lede vit-sec-l\">Honnête dans les deux sens. D’après notre recherche du 1er novembre 2026.</p><div class=\"tbl-w vit-cmp-w\"><table class=\"tbl vit-cmp\"><thead><tr><th scope=\"col\"><span class=\"sr-only\">Critère</span></th><th scope=\"col\" class=\"is-us\"><span class=\"vit-cmp-t\">ArcHive</span><span class=\"lbl muted vit-cmp-s\">sur Arc testnet</span></th><th scope=\"col\"><span class=\"vit-cmp-t\">API d’IA centralisées</span><span class=\"lbl muted vit-cmp-s\">une API de modèle ordinaire</span></th><th scope=\"col\"><span class=\"vit-cmp-t\">Clouds et marchés d’enclaves</span><span class=\"lbl muted vit-cmp-s\">Phala, 0G, Marlin, iExec, Oasis</span></th><th scope=\"col\"><span class=\"vit-cmp-t\">Plateformes de primes de bugs</span><span class=\"lbl muted vit-cmp-s\">Immunefi, Cantina</span></th></tr></thead><tbody><tr><th scope=\"row\">Qui vérifie la machine</th><td class=\"is-us\" data-l=\"ArcHive\">Un contrat sur Arc vérifie lui-même la signature d’Intel, avant tout paiement.</td><td data-l=\"API d’IA centralisées\">Personne de visible. Vous croyez le fournisseur sur parole.</td><td data-l=\"Clouds et marchés d’enclaves\">Leur propre service&#160;: un gestionnaire de clés, un routeur ou leur propre chaîne. Souvent optionnel.</td><td data-l=\"Plateformes de primes de bugs\">Pas de machine&#160;: des humains trient les rapports.</td></tr><tr><th scope=\"row\">Comment on paie</th><td class=\"is-us\" data-l=\"ArcHive\">En USDC à l’usage sur Arc. Le contrat partage chaque paiement dans la même transaction. Aucun jeton.</td><td data-l=\"API d’IA centralisées\">Un compte, une clé d’API et une carte.</td><td data-l=\"Clouds et marchés d’enclaves\">Un compte par carte ou crypto, ou leur propre jeton.</td><td data-l=\"Plateformes de primes de bugs\">Après le tri. Les concours d’Immunefi ont payé 26 à 63&#160;jours après la clôture.</td></tr><tr><th scope=\"row\">Si le résultat est faux</th><td class=\"is-us\" data-l=\"ArcHive\">Un second rejeu ou deux reçus contradictoires le prouvent, et toute la caution de l’opérateur est saisie.</td><td data-l=\"API d’IA centralisées\">Un ticket au support.</td><td data-l=\"Clouds et marchés d’enclaves\">Aucune caution liée à un résultat.</td><td data-l=\"Plateformes de primes de bugs\">À la discrétion du programme.</td></tr><tr><th scope=\"row\">Preuve à conserver</th><td class=\"is-us\" data-l=\"ArcHive\">Un reçu signé par l’enclave pour chaque réponse, et un verdict public ERC-8004.</td><td data-l=\"API d’IA centralisées\">Une facture.</td><td data-l=\"Clouds et marchés d’enclaves\">Un rapport d’attestation, vérifié hors chaîne.</td><td data-l=\"Plateformes de primes de bugs\">Les registres de la plateforme.</td></tr><tr><th scope=\"row\">Là où ils sont devant aujourd’hui</th><td class=\"is-us\" data-l=\"ArcHive\">Nous sommes sur le testnet, avec un seul opérateur et aucun client extérieur pour l’instant.</td><td data-l=\"API d’IA centralisées\">L’échelle et le choix des modèles.</td><td data-l=\"Clouds et marchés d’enclaves\">En production avec des clients payants&#160;: Phala a fait environ 3,1&#160;M$ en 2025 avec 398 d’entre eux. Des GPU aussi.</td><td data-l=\"Plateformes de primes de bugs\">144,7&#160;M$ payés par Immunefi, plus de 85 000 chercheurs, KYC au paiement.</td></tr></tbody></table></div><p class=\"vit-cmp-edge\">Ce que personne d’autre ne faisait au 1er novembre, d’après notre recherche&#160;: sur Arc, le contrat qui paie est celui qui vérifie l’enclave. Il contrôle la signature d’Intel, paie en USDC quand le résultat est accepté, et saisit la caution quand le résultat est prouvé faux.</p><p class=\"lbl muted vit-cmp-also\">Aussi comparés&#160;: Chainlink CRE, dont les contrats croient les signatures de Chainlink plutôt que le matériel. UMA et Kleros, où les litiges vont à des votes de jetons ou à des jurés. Les preuves à divulgation nulle, qui selon notre lecture ne savent pas encore réexécuter une transaction EVM sur l’état réel à ce coût.</p>"},{"id":"market","cls":"mk","k":"Le marché","t":"Marché","plain":"Qui paie qui.","units":"","body":"<header class=\"mk-head\"><p class=\"lbl mk-kick\">Le marché</p><h2 aria-label=\"Qui paie qui.\" class=\"vt-h mk-h\" id=\"market-h\">Qui paie <span class=\"vt-acc\">qui</span>.<span class=\"ttl-rule\" aria-hidden=\"true\"></span></h2><div class=\"mk-head-g\"><p class=\"lede mk-lede\">ArcHive est un marché sans jeton, réglé en USDC sur Arc. Les acheteurs paient à l’usage. Les opérateurs louent des machines Intel TDX scellées et bloquent une caution qu’ils perdent s’ils trichent. Les auteurs publient des services et fixent leur propre part. Le contrat qui vérifie la machine est celui qui paie, et il partage chaque paiement dans la même transaction.</p><div class=\"verdict-w cote-in mk-thesis\"><span class=\"cote-l\" aria-hidden=\"true\"></span><p class=\"verdict-l cote-v\">Des enclaves pour des produits, pas des enclaves pour elles-mêmes. Vérifier une machine est gratuit&#160;: le réseau ne gagne que quand un produit est payé.</p><p data-live-v=\"shares\" class=\"lbl mk-live\"></p><p class=\"lbl mk-tok\">Chaque part, produit par produit, et les règles de la caution&#160;: <a class=\"tlink\" href=\"/doc.html?c=tokenomics\">Tokenomics, dans la Doc</a></p></div></div><nav class=\"mk-nav\" aria-label=\"Dans cette section\"><a data-vt-in=\"market-sides\" class=\"mk-nav-a\" href=\"#market-sides\"><span class=\"mono\" aria-hidden=\"true\">01</span>Trois côtés</a><a data-vt-in=\"market-flows\" class=\"mk-nav-a\" href=\"#market-flows\"><span class=\"mono\" aria-hidden=\"true\">02</span>Suivre l’argent</a><a data-vt-in=\"market-so\" class=\"mk-nav-a\" href=\"#market-so\"><span class=\"mono\" aria-hidden=\"true\">03</span>L’argent à ce jour</a><a data-vt-in=\"market-rules\" class=\"mk-nav-a\" href=\"#market-rules\"><span class=\"mono\" aria-hidden=\"true\">04</span>Les règles</a><a data-vt-in=\"market-why\" class=\"mk-nav-a\" href=\"#market-why\"><span class=\"mono\" aria-hidden=\"true\">05</span>Pourquoi des enclaves</a><a data-vt-in=\"market-first\" class=\"mk-nav-a\" href=\"#market-first\"><span class=\"mono\" aria-hidden=\"true\">06</span>Premiers acheteurs</a><a data-vt-in=\"market-grow\" class=\"mk-nav-a\" href=\"#market-grow\"><span class=\"mono\" aria-hidden=\"true\">07</span>La croissance</a><a data-vt-in=\"market-main\" class=\"mk-nav-a\" href=\"#market-main\"><span class=\"mono\" aria-hidden=\"true\">08</span>Chiffres du mainnet</a><a data-vt-in=\"market-not\" class=\"mk-nav-a\" href=\"#market-not\"><span class=\"mono\" aria-hidden=\"true\">09</span>Avant le mainnet</a></nav></header><section class=\"mk-b\" id=\"market-sides\" aria-labelledby=\"market-sides-h\"><header class=\"mk-bhd\"><h3 class=\"mk-bh\" id=\"market-sides-h\"><span class=\"mk-bn mono\" aria-hidden=\"true\">01</span><span>Trois côtés, un contrat</span></h3><p class=\"mk-blede\">Ils se rencontrent sur Arc sans avoir à se faire confiance, ni à nous&#160;: le contrat vérifie la machine, garde la caution et paie.</p></header><ol class=\"mk-sides\"><li class=\"row mk-side\"><h4 class=\"mk-side-n\">Acheteurs</h4><dl class=\"mk-side-l\"><div><dt class=\"lbl\">Qui</dt><dd>Des personnes, des apps et des agents d’IA qui ont besoin d’une IA privée. Des protocoles qui veulent un exploit prouvé avant de payer.</dd></div><div><dt class=\"lbl\">Paie</dt><dd>À l’usage, en USDC&#160;: une session prépayée, une signature par appel, ou une réserve de prime qui ne paie qu’un exploit prouvé.</dd></div><div><dt class=\"lbl\">Reçoit</dt><dd>Une réponse signée par une enclave vérifiée par Arc, avec un reçu, et le dépôt non utilisé rendu. Un protocole reçoit le rapport d’exploit, chiffré pour lui seul.</dd></div></dl><p class=\"mk-side-tag\"><span class=\"lbl\">Lu sur Arc</span> <span data-live-v=\"p3price\" class=\"mono tnum\">0,01 USDC l’appel, #3</span></p></li><li class=\"row mk-side\"><h4 class=\"mk-side-n\">Opérateurs</h4><dl class=\"mk-side-l\"><div><dt class=\"lbl\">Qui</dt><dd>Toute personne qui a une machine Intel TDX, une VM chez un cloud ou son propre serveur. Installation en une ligne, appairée à son wallet.</dd></div><div><dt class=\"lbl\">Paie</dt><dd>Une caution en USDC, bloquée et jamais dépensée sauf en cas de triche, rendue 7 jours après la demande. Le gaz d’inscription de chaque enclave, environ 0,14 à 0,17 USDC par jour.</dd></div><div><dt class=\"lbl\">Reçoit</dt><dd>95&#160;% de chaque usage payé, moins la part de l’auteur sur le service d’un autre, plus 5&#160;% en sus de chaque prime que leurs enclaves ont signée.</dd></div></dl><p class=\"mk-side-tag\"><span class=\"lbl\">Lu sur Arc</span> <span data-live-v=\"op\" class=\"mono tnum\">95&#160;%</span></p></li><li class=\"row mk-side\"><h4 class=\"mk-side-n\">Auteurs</h4><dl class=\"mk-side-l\"><div><dt class=\"lbl\">Qui</dt><dd>Quiconque a un service à vendre. Publier sur Arc est ouvert, sans revue ni portier.</dd></div><div><dt class=\"lbl\">Paie</dt><dd>Seulement le gaz pour publier. Pas besoin de machine&#160;: les opérateurs font tourner le service.</dd></div><div><dt class=\"lbl\">Reçoit</dt><dd>La part qu’ils fixent, de 0 à 30&#160;%, une place dans le catalogue, la facturation en USDC faite pour eux et la vérification au prix coûtant. Ils choisissent le niveau d’opérateur autorisé à le faire tourner.</dd></div></dl><p class=\"mk-side-tag\"><span class=\"lbl\">Lu sur Arc</span> <span data-live-v=\"au\" class=\"mono tnum\">0&#160;%</span></p></li></ol><div class=\"mk-sides-more\"><p><i class=\"mk-sw t-net\" aria-hidden=\"true\"></i>Le réseau garde 5&#160;% de chaque usage payé et 10&#160;% en sus de chaque prime payée. Inscrire et vérifier une enclave est sans frais.</p><p><i class=\"mk-sw t-hunt\" aria-hidden=\"true\"></i>Deux autres personnes sont payées par les règles&#160;: le chasseur touche tout le palier de la prime dans la transaction de paiement, et qui prouve qu’un opérateur a triché touche la moitié de sa caution.</p></div></section><section class=\"mk-b\" id=\"market-flows\" aria-labelledby=\"market-flows-h\"><header class=\"mk-bhd\"><h3 class=\"mk-bh\" id=\"market-flows-h\"><span class=\"mk-bn mono\" aria-hidden=\"true\">02</span><span>Suivre l’argent</span></h3><p class=\"mk-blede\">Trois paiements faits sur Arc, dessinés à l’échelle. Chacun est une seule transaction, à ouvrir sur l’explorateur.</p></header><div class=\"mk-flows\"><article class=\"mk-flow\" id=\"market-flow-ai\" aria-labelledby=\"market-flow-ai-t\"><div class=\"mk-flow-t\"><h4 class=\"mk-ft\" id=\"market-flow-ai-t\">Une réponse d’IA payée</h4><p class=\"mk-fd\">L’IA privée, à l’appel ou à la session. Le contrat ne paie que contre un reçu signé par une enclave vérifiée par Arc, et partage le paiement dans cette même transaction.</p><p class=\"mk-ex\"><span class=\"lbl mk-exl\">Exemple</span> Un appel au prix lu sur Arc</p></div><div class=\"mk-flow-d\"><div class=\"mk-dia\"><svg class=\"mk-svg\" width=\"672\" height=\"378\" viewBox=\"0 0 672 378\" role=\"img\" aria-label=\"App ou agent, 0,01 USDC: Opérateur 0,0095 USDC, Auteur 0,00 USDC, Réseau 0,0005 USDC\"><g class=\"mk-grow\"><rect class=\"mk-band t-src\" x=\"8\" y=\"99.6\" width=\"198\" height=\"176\" /><path class=\"mk-dash t-src\" d=\"M8,187.6 L206,187.6\" style=\"stroke-width: 2;\" /></g><g class=\"mk-o\"><rect class=\"mk-hit\" x=\"456\" y=\"42\" width=\"216\" height=\"175.2\" /><g class=\"mk-grow\"><path class=\"mk-band t-op\" d=\"M218,99.6 C343,99.6 343,46 468,46 L468,213.2 C343,213.2 343,266.79999999999995 218,266.79999999999995 Z\" /><path class=\"mk-dash t-op\" d=\"M218,183.2 C343,183.2 343,129.6 468,129.6\" style=\"stroke-width: 2;\" /></g><rect class=\"mk-node t-op\" x=\"468\" y=\"46\" width=\"8\" height=\"167.2\" /><g class=\"mk-fade\"><text class=\"mk-tl\" x=\"486\" y=\"125.6\">OPÉRATEUR 95&#160;%</text><text class=\"mk-tv\" x=\"486\" y=\"142.6\">0,0095 USDC</text></g></g><g class=\"mk-o\"><rect class=\"mk-hit\" x=\"456\" y=\"221.2\" width=\"216\" height=\"54\" /><g class=\"mk-grow\"><path class=\"mk-zero\" d=\"M218,266.79999999999995 C343,266.79999999999995 343,248.2 468,248.2\" /></g><rect class=\"mk-node t-au\" x=\"468\" y=\"247.7\" width=\"8\" height=\"1\" /><g class=\"mk-fade\"><text class=\"mk-tl\" x=\"486\" y=\"244.2\">AUTEUR 0&#160;%</text><text class=\"mk-tv\" x=\"486\" y=\"261.2\">0,00 USDC</text></g></g><g class=\"mk-o\"><rect class=\"mk-hit\" x=\"456\" y=\"279.2\" width=\"216\" height=\"54\" /><g class=\"mk-grow\"><path class=\"mk-band t-net\" d=\"M218,266.79999999999995 C343,266.79999999999995 343,301.8 468,301.8 L468,310.6 C343,310.6 343,275.59999999999997 218,275.59999999999997 Z\" /><path class=\"mk-dash t-net\" d=\"M218,271.19999999999993 C343,271.19999999999993 343,306.2 468,306.2\" style=\"stroke-width: 2;\" /></g><rect class=\"mk-node t-net\" x=\"468\" y=\"301.8\" width=\"8\" height=\"8.8\" /><g class=\"mk-fade\"><text class=\"mk-tl\" x=\"486\" y=\"302.2\">RÉSEAU 5&#160;%</text><text class=\"mk-tv\" x=\"486\" y=\"319.2\">0,0005 USDC</text></g></g><rect class=\"mk-node t-src\" x=\"0\" y=\"99.6\" width=\"8\" height=\"176\" /><g class=\"mk-fade\"><text class=\"mk-tl\" x=\"0\" y=\"297.6\">APP OU AGENT</text><text class=\"mk-tv\" x=\"0\" y=\"314.6\">0,01 USDC</text></g><rect class=\"mk-via\" x=\"206\" y=\"99.6\" width=\"12\" height=\"176\" /><text class=\"mk-tk\" x=\"212\" y=\"73.6\" text-anchor=\"middle\">SUR ARC</text><text class=\"mk-tn\" x=\"212\" y=\"89.6\" text-anchor=\"middle\">X402Settler</text></svg></div></div><div class=\"mk-flow-v\"><dl class=\"mk-list\" aria-label=\"Qui reçoit quoi\"><div class=\"mk-li\" tabindex=\"0\"><dt><i class=\"mk-sw t-op\" aria-hidden=\"true\"></i>Opérateur</dt><dd><span class=\"mono tnum\">0,0095 USDC</span><span class=\"mk-sh\">95&#160;%</span></dd></div><div class=\"mk-li\" tabindex=\"0\"><dt><i class=\"mk-sw t-au\" aria-hidden=\"true\"></i>Auteur</dt><dd><span class=\"mono tnum\">0,00 USDC</span><span class=\"mk-sh\">0&#160;%</span></dd></div><div class=\"mk-li\" tabindex=\"0\"><dt><i class=\"mk-sw t-net\" aria-hidden=\"true\"></i>Réseau</dt><dd><span class=\"mono tnum\">0,0005 USDC</span><span class=\"mk-sh\">5&#160;%</span></dd></div></dl><p class=\"lbl mk-st\">Parts lues sur Arc le 20 novembre, sur la pile v3&#160;: les mêmes que sur la v2.1. L’opérateur paie le gaz du règlement, environ 0,005 USDC au prix du gaz du testnet aujourd’hui.</p><p class=\"mk-proof\"><span class=\"lbl mk-pl\">Preuve</span><span><a class=\"tlink mono mk-tx\" href=\"https://explorer.testnet.arc.io/tx/0xa41f1276a9f0b0af98d1991ae1ab06e5f1afb3d9bed71bca486ccea7255c15d9\" target=\"_blank\" rel=\"noreferrer\">0xa41f12…15d9</a> Payé le 9 nov. depuis un navigateur&#160;: 0,0095 USDC pour l’opérateur, 0,0005 USDC pour le réseau.</span></p></div></article><article class=\"mk-flow\" id=\"market-flow-bounty\" aria-labelledby=\"market-flow-bounty-t\"><div class=\"mk-flow-t\"><h4 class=\"mk-ft\" id=\"market-flow-bounty-t\">Un exploit prouvé</h4><p class=\"mk-fd\">Prime scellée. La réserve du protocole ne paie que quand une enclave admise a rejoué l’exploit sur une copie d’Arc et mesuré la perte. Le chasseur touche tout le palier, et les frais viennent en plus.</p></div><div class=\"mk-flow-d\"><div class=\"mk-dia\"><svg class=\"mk-svg\" width=\"672\" height=\"364\" viewBox=\"0 0 672 364\" role=\"img\" aria-label=\"Réserve du protocole, 0,575 USDC: Chasseur 0,5 USDC, Réseau, +10 % 0,05 USDC, Opérateurs signataires, +5 % 0,025 USDC\"><g class=\"mk-grow\"><rect class=\"mk-band t-src\" x=\"8\" y=\"92.52173913043478\" width=\"198\" height=\"176\" /><path class=\"mk-dash t-src\" d=\"M8,180.52173913043478 L206,180.52173913043478\" style=\"stroke-width: 2;\" /></g><g class=\"mk-o\"><rect class=\"mk-hit\" x=\"456\" y=\"42\" width=\"216\" height=\"161.04347826086956\" /><g class=\"mk-grow\"><path class=\"mk-band t-hunt\" d=\"M218,92.52173913043478 C343,92.52173913043478 343,46 468,46 L468,199.04347826086956 C343,199.04347826086956 343,245.56521739130434 218,245.56521739130434 Z\" /><path class=\"mk-dash t-hunt\" d=\"M218,169.04347826086956 C343,169.04347826086956 343,122.52173913043478 468,122.52173913043478\" style=\"stroke-width: 2;\" /></g><rect class=\"mk-node t-hunt\" x=\"468\" y=\"46\" width=\"8\" height=\"153.04347826086956\" /><g class=\"mk-fade\"><text class=\"mk-tl\" x=\"486\" y=\"118.52173913043478\">CHASSEUR</text><text class=\"mk-tv\" x=\"486\" y=\"135.52173913043478\">0,5 USDC</text></g></g><g class=\"mk-o\"><rect class=\"mk-hit\" x=\"456\" y=\"207.04347826086956\" width=\"216\" height=\"54\" /><g class=\"mk-grow\"><path class=\"mk-band t-net\" d=\"M218,245.56521739130434 C343,245.56521739130434 343,226.3913043478261 468,226.3913043478261 L468,241.69565217391306 C343,241.69565217391306 343,260.8695652173913 218,260.8695652173913 Z\" /><path class=\"mk-dash t-net\" d=\"M218,253.2173913043478 C343,253.2173913043478 343,234.04347826086956 468,234.04347826086956\" style=\"stroke-width: 2;\" /></g><rect class=\"mk-node t-net\" x=\"468\" y=\"226.3913043478261\" width=\"8\" height=\"15.304347826086957\" /><g class=\"mk-fade\"><text class=\"mk-tl\" x=\"486\" y=\"230.04347826086956\">RÉSEAU +10&#160;%</text><text class=\"mk-tv\" x=\"486\" y=\"247.04347826086956\">0,05 USDC</text></g></g><g class=\"mk-o\"><rect class=\"mk-hit\" x=\"456\" y=\"265.04347826086956\" width=\"216\" height=\"54\" /><g class=\"mk-grow\"><path class=\"mk-band t-ops\" d=\"M218,260.8695652173913 C343,260.8695652173913 343,288.2173913043478 468,288.2173913043478 L468,295.8695652173913 C343,295.8695652173913 343,268.5217391304348 218,268.5217391304348 Z\" /><path class=\"mk-dash t-ops\" d=\"M218,264.69565217391306 C343,264.69565217391306 343,292.04347826086956 468,292.04347826086956\" style=\"stroke-width: 2;\" /></g><rect class=\"mk-node t-ops\" x=\"468\" y=\"288.2173913043478\" width=\"8\" height=\"7.6521739130434785\" /><g class=\"mk-fade\"><text class=\"mk-tl\" x=\"486\" y=\"288.04347826086956\">OPÉRATEURS +5&#160;%</text><text class=\"mk-tv\" x=\"486\" y=\"305.04347826086956\">0,025 USDC</text></g></g><rect class=\"mk-node t-src\" x=\"0\" y=\"92.52173913043478\" width=\"8\" height=\"176\" /><g class=\"mk-fade\"><text class=\"mk-tl\" x=\"0\" y=\"290.52173913043475\">RÉSERVE DU PROTOCOLE</text><text class=\"mk-tv\" x=\"0\" y=\"307.52173913043475\">0,575 USDC</text></g><rect class=\"mk-via\" x=\"206\" y=\"92.52173913043478\" width=\"12\" height=\"176\" /><text class=\"mk-tk\" x=\"212\" y=\"66.52173913043478\" text-anchor=\"middle\">SUR ARC</text><text class=\"mk-tn\" x=\"212\" y=\"82.52173913043478\" text-anchor=\"middle\">SealedBounty</text></svg></div></div><div class=\"mk-flow-v\"><dl class=\"mk-list\" aria-label=\"Qui reçoit quoi\"><div class=\"mk-li\" tabindex=\"0\"><dt><i class=\"mk-sw t-hunt\" aria-hidden=\"true\"></i>Chasseur</dt><dd><span class=\"mono tnum\">0,5 USDC</span></dd></div><div class=\"mk-li\" tabindex=\"0\"><dt><i class=\"mk-sw t-net\" aria-hidden=\"true\"></i>Réseau, +10&#160;%</dt><dd><span class=\"mono tnum\">0,05 USDC</span></dd></div><div class=\"mk-li\" tabindex=\"0\"><dt><i class=\"mk-sw t-ops\" aria-hidden=\"true\"></i>Opérateurs signataires, +5&#160;%</dt><dd><span class=\"mono tnum\">0,025 USDC</span></dd></div></dl><p class=\"mk-proof\"><span class=\"lbl mk-pl\">Preuve</span><span><a class=\"tlink mono mk-tx\" href=\"https://explorer.testnet.arc.io/tx/0xecbd089a092edd939ff646fae8d22c0f2616b6a92f58a49928c231c770bb807e\" target=\"_blank\" rel=\"noreferrer\">0xecbd08…807e</a> Payé le 9 nov., avec le rapport chiffré et le verdict ERC-8004 dans la même transaction.</span></p><p class=\"mk-note\">Le niveau vérifié (n°&#160;5) a les mêmes frais. Ses paiements sont autorisés sur Arc depuis le 19&#160;nov. à 20&#160;h&#160;37&#160;UTC, quand la pile v3 a été initialisée.</p></div></article><article class=\"mk-flow\" id=\"market-flow-slash\" aria-labelledby=\"market-flow-slash-t\"><div class=\"mk-flow-t\"><h4 class=\"mk-ft\" id=\"market-flow-slash-t\">Un mensonge prouvé</h4><p class=\"mk-fd\">Tricher coûte la caution. Le 10 nov., une enclave construite pour mentir a gonflé une perte. Les enclaves de deux autres opérateurs ont rejoué l’exploit et l’ont réfuté. Rien n’a été versé, toute la caution du menteur a été saisie et son opérateur banni.</p></div><div class=\"mk-flow-d\"><div class=\"mk-dia\"><svg class=\"mk-svg\" width=\"672\" height=\"302\" viewBox=\"0 0 672 302\" role=\"img\" aria-label=\"Caution du menteur, 1,00 USDC, Banni: Qui l’a prouvé 0,5 USDC, Victime, ou la trésorerie 0,5 USDC\"><g class=\"mk-grow\"><rect class=\"mk-band t-src\" x=\"8\" y=\"52\" width=\"198\" height=\"176\" /><path class=\"mk-dash t-src\" d=\"M8,140 L206,140\" style=\"stroke-width: 2;\" /></g><g class=\"mk-o\"><rect class=\"mk-hit\" x=\"456\" y=\"42\" width=\"216\" height=\"96\" /><g class=\"mk-grow\"><path class=\"mk-band t-rep\" d=\"M218,52 C343,52 343,46 468,46 L468,134 C343,134 343,140 218,140 Z\" /><path class=\"mk-dash t-rep\" d=\"M218,96 C343,96 343,90 468,90\" style=\"stroke-width: 2;\" /></g><rect class=\"mk-node t-rep\" x=\"468\" y=\"46\" width=\"8\" height=\"88\" /><g class=\"mk-fade\"><text class=\"mk-tl\" x=\"486\" y=\"86\">QUI PROUVE 50&#160;%</text><text class=\"mk-tv\" x=\"486\" y=\"103\">0,5 USDC</text></g></g><g class=\"mk-o\"><rect class=\"mk-hit\" x=\"456\" y=\"142\" width=\"216\" height=\"96\" /><g class=\"mk-grow\"><path class=\"mk-band t-vic\" d=\"M218,140 C343,140 343,146 468,146 L468,234 C343,234 343,228 218,228 Z\" /><path class=\"mk-dash t-vic\" d=\"M218,184 C343,184 343,190 468,190\" style=\"stroke-width: 2;\" /></g><rect class=\"mk-node t-vic\" x=\"468\" y=\"146\" width=\"8\" height=\"88\" /><g class=\"mk-fade\"><text class=\"mk-tl\" x=\"486\" y=\"186\">VICTIME 50&#160;%</text><text class=\"mk-tv\" x=\"486\" y=\"203\">0,5 USDC</text></g></g><rect class=\"mk-node t-src\" x=\"0\" y=\"52\" width=\"8\" height=\"176\" /><g class=\"mk-fade\"><text class=\"mk-tl\" x=\"0\" y=\"250\">CAUTION DU MENTEUR</text><text class=\"mk-tv\" x=\"0\" y=\"267\">1,00 USDC</text><rect class=\"mk-led-red\" x=\"0\" y=\"279\" width=\"18\" height=\"5\" /><text class=\"mk-tl mk-red\" x=\"26\" y=\"285\">BANNI</text></g><rect class=\"mk-via\" x=\"206\" y=\"52\" width=\"12\" height=\"176\" /><text class=\"mk-tk\" x=\"212\" y=\"26\" text-anchor=\"middle\">SUR ARC</text><text class=\"mk-tn\" x=\"212\" y=\"42\" text-anchor=\"middle\">OperatorBond</text></svg></div></div><div class=\"mk-flow-v\"><dl class=\"mk-list\" aria-label=\"Qui reçoit quoi\"><div class=\"mk-li\" tabindex=\"0\"><dt><i class=\"mk-sw t-rep\" aria-hidden=\"true\"></i>Qui l’a prouvé</dt><dd><span class=\"mono tnum\">0,5 USDC</span><span class=\"mk-sh\">50&#160;%</span></dd></div><div class=\"mk-li\" tabindex=\"0\"><dt><i class=\"mk-sw t-vic\" aria-hidden=\"true\"></i>Victime, ou la trésorerie</dt><dd><span class=\"mono tnum\">0,5 USDC</span><span class=\"mk-sh\">50&#160;%</span></dd></div></dl><p class=\"mk-proof\"><span class=\"lbl mk-pl\">Preuve</span><span><a class=\"tlink mono mk-tx\" href=\"https://explorer.testnet.arc.io/tx/0x0ffca5433186735bf5525e525995f3589d842681da8ffcaa82acb5993025051f\" target=\"_blank\" rel=\"noreferrer\">0x0ffca5…051f</a> Réfuté et saisi le 10 nov., 16 s après l’acceptation du mensonge.</span></p><p class=\"mk-note\">Seulement pour une faute qu’une machine peut prouver&#160;: deux reçus pour la même étape, deux réclamations pour les mêmes entrées, ou une réclamation réfutée par au moins 2 autres opérateurs sous 3 jours. Jamais pour une mauvaise réponse d’IA.</p></div></article></div></section><section class=\"mk-b\" id=\"market-so\" aria-labelledby=\"market-so-h\"><header class=\"mk-bhd\"><h3 class=\"mk-bh\" id=\"market-so-h\"><span class=\"mk-bn mono\" aria-hidden=\"true\">03</span><span>L’argent à ce jour</span></h3><p class=\"mk-blede\">Lu en direct dans l’index ArcHive des événements d’Arc.</p></header><dl class=\"mk-figs\"><div class=\"row\"><dt class=\"lbl\">Payé pour l’IA privée</dt><dd data-live-v=\"settled\" class=\"mk-fig\">0,1494 USDC</dd><dd class=\"lbl mk-fig-d\">aux opérateurs et au réseau</dd></div><div class=\"row\"><dt class=\"lbl\">Payé à un chasseur</dt><dd data-live-v=\"bounty\" class=\"mk-fig\">0,5 USDC</dd><dd class=\"lbl mk-fig-d\">tout le palier, frais en plus</dd></div><div class=\"row\"><dt class=\"lbl\">Appels payés (x402)</dt><dd data-live-v=\"x402\" class=\"mk-fig\">5</dd><dd class=\"lbl mk-fig-d\">une signature chacun</dd></div><div class=\"row\"><dt class=\"lbl\">Sessions prépayées</dt><dd data-live-v=\"sessions\" class=\"mk-fig\">1</dd><dd class=\"lbl mk-fig-d\">dépôt non utilisé rendu</dd></div><div class=\"row\"><dt class=\"lbl\">Verdicts ERC-8004</dt><dd data-live-v=\"verdicts\" class=\"mk-fig\">3</dd><dd class=\"lbl mk-fig-d\">scores publics dans le registre de Circle</dd></div><div class=\"row\"><dt class=\"lbl\">Revenu du réseau</dt><dd class=\"mk-fig\">0,05747 USDC</dd><dd class=\"lbl mk-fig-d\">sur la v2.1, calculé sur les transferts de l’explorateur le 18 novembre</dd></div><div class=\"row\"><dt class=\"lbl\">Caution saisie</dt><dd class=\"mk-fig\">1,00 USDC</dd><dd class=\"lbl mk-fig-d\">à l’enclave prise à mentir</dd></div></dl><p class=\"mk-honest\">Tout est venu de nos propres wallets de test, sur testnet. Aucun client extérieur n’a encore payé&#160;: c’est le client numéro 0.</p></section><section class=\"mk-b\" id=\"market-rules\" aria-labelledby=\"market-rules-h\"><header class=\"mk-bhd\"><h3 class=\"mk-bh\" id=\"market-rules-h\"><span class=\"mk-bn mono\" aria-hidden=\"true\">04</span><span>Les règles, écrites dans les contrats</span></h3><p class=\"mk-blede\">Prix, parts et cautions sont des paramètres sur Arc que chacun peut lire. Le plancher des frais et les plafonds sont des constantes du code.</p></header><div class=\"tbl-w\"><table class=\"tbl mk-rules\"><thead><tr><th scope=\"col\">Règle</th><th scope=\"col\">Ce que dit le code</th><th scope=\"col\">Aujourd’hui sur Arc</th><th scope=\"col\">Appliqué par</th></tr></thead><tbody><tr><th scope=\"row\" data-l=\"Règle\">Part du réseau</th><td data-l=\"Ce que dit le code\">Au moins 5&#160;% de chaque usage payé.</td><td data-l=\"Aujourd’hui sur Arc\" class=\"mk-now\">5&#160;% sur les 5 produits</td><td data-l=\"Appliqué par\" class=\"mono mk-where\">ProductRegistry, MIN_NETWORK_BPS</td></tr><tr><th scope=\"row\" data-l=\"Règle\">Part de l’auteur</th><td data-l=\"Ce que dit le code\">Fixée par l’auteur, 30&#160;% au plus.</td><td data-l=\"Aujourd’hui sur Arc\" class=\"mk-now\">0&#160;%, les 5 produits sont les nôtres</td><td data-l=\"Appliqué par\" class=\"mono mk-where\">ProductRegistry, MAX_AUTHOR_BPS</td></tr><tr><th scope=\"row\" data-l=\"Règle\">Part de l’opérateur</th><td data-l=\"Ce que dit le code\">Le reste de chaque usage payé.</td><td data-l=\"Aujourd’hui sur Arc\" class=\"mk-now\">95&#160;%</td><td data-l=\"Appliqué par\" class=\"mono mk-where\">ProductRegistry</td></tr><tr><th scope=\"row\" data-l=\"Règle\">Paiement d’une prime</th><td data-l=\"Ce que dit le code\">Le chasseur touche tout le palier. En plus, sur la même réserve, 10&#160;% pour le réseau et 5&#160;% pour les opérateurs signataires.</td><td data-l=\"Aujourd’hui sur Arc\" class=\"mk-now\">1 000 et 500 points de base, sur les deux contrats de prime</td><td data-l=\"Appliqué par\" class=\"mono mk-where\">SealedBounty, SealedBountyVerified, fixés au déploiement</td></tr><tr><th scope=\"row\" data-l=\"Règle\">Vérifier une machine</th><td data-l=\"Ce que dit le code\">Sans frais. Inscrire une enclave ne coûte que son gaz.</td><td data-l=\"Aujourd’hui sur Arc\" class=\"mk-now\">Environ 0,14 à 0,17 USDC</td><td data-l=\"Appliqué par\" class=\"mono mk-where\">EnclaveRegistry</td></tr><tr><th scope=\"row\" data-l=\"Règle\">Caution</th><td data-l=\"Ce que dit le code\">Bloquée, pas dépensée. Sur la seule parole de ses enclaves, un opérateur n’encaisse jamais plus de la moitié de sa caution disponible (sa caution moins tout retrait demandé) sur 24 heures glissantes, ni plus que le plafond d’un produit. Elle est rendue 7 jours après la demande, une fois que plus rien n’en dépend.</td><td data-l=\"Aujourd’hui sur Arc\" class=\"mk-now\">Dès 1,00 USDC par enclave, plafond de 10,00 USDC par 24 h (valeurs de testnet)</td><td data-l=\"Appliqué par\" class=\"mono mk-where\">OperatorBond, UNBOND_DELAY</td></tr><tr><th scope=\"row\" data-l=\"Règle\">Faute prouvée</th><td data-l=\"Ce que dit le code\">Toute la caution est saisie&#160;: moitié à qui l’a prouvée, moitié à la victime. L’opérateur est banni.</td><td data-l=\"Aujourd’hui sur Arc\" class=\"mk-now\">1 USDC saisi le 10 nov.</td><td data-l=\"Appliqué par\" class=\"mono mk-where\">OperatorBond, slash</td></tr><tr><th scope=\"row\" data-l=\"Règle\">Publication</th><td data-l=\"Ce que dit le code\">Ouverte à tous, sans revue. Un nouveau produit ou une nouvelle version n’entre en service qu’après son délai.</td><td data-l=\"Aujourd’hui sur Arc\" class=\"mk-now\">0 sur testnet, 48 h prévues sur le mainnet</td><td data-l=\"Appliqué par\" class=\"mono mk-where\">ProductRegistry, propose</td></tr><tr><th scope=\"row\" data-l=\"Règle\">Sessions</th><td data-l=\"Ce que dit le code\">Un dépôt prépayé, sans caution pour l’acheteur. Ce qui n’est pas utilisé revient à la clôture.</td><td data-l=\"Aujourd’hui sur Arc\" class=\"mk-now\">De 10 min à 30 jours</td><td data-l=\"Appliqué par\" class=\"mono mk-where\">SessionPay</td></tr><tr><th scope=\"row\" data-l=\"Règle\">Un nouveau contrat de paiement</th><td data-l=\"Ce que dit le code\">Attend 8 jours avant de pouvoir toucher une caution, pour que les opérateurs puissent partir avant. Le retirer est immédiat.</td><td data-l=\"Aujourd’hui sur Arc\" class=\"mk-now\">8 jours</td><td data-l=\"Appliqué par\" class=\"mono mk-where\">OperatorBond, SETTLEMENT_DELAY</td></tr></tbody></table></div></section><section class=\"mk-b\" id=\"market-why\" aria-labelledby=\"market-why-h\"><header class=\"mk-bhd\"><h3 class=\"mk-bh\" id=\"market-why-h\"><span class=\"mk-bn mono\" aria-hidden=\"true\">05</span><span>Pourquoi les produits ont besoin d’enclaves, et les enclaves d’un marché</span></h3></header><div class=\"mk-why\"><div class=\"mk-why-p\"><h4 class=\"mk-sub\">Chaque produit a besoin d’une machine scellée</h4><dl class=\"mk-why-l\"><div class=\"row\"><dt>Prime scellée</dt><dd>Le chasseur ne montrera pas l’exploit avant d’être payé, et le protocole ne paiera pas avant la preuve. Une machine scellée que tous deux peuvent vérifier sur Arc exécute l’exploit, puis libère ensemble le paiement et le rapport&#160;: un échange équitable, sans intermédiaire.</dd></div><div class=\"row\"><dt>IA privée</dt><dd>La requête doit rester illisible pour l’opérateur et pour nous. Seule l’isolation matérielle, avec une attestation que le contrat vérifie, le permet. Chaque reçu lie le paiement à cette machine-là.</dd></div><div class=\"row\"><dt>Copilote attesté</dt><dd>Ses instructions sont mesurées, et la conversation est scellée face à notre propre serveur web.</dd></div><div class=\"row\"><dt>Tricher coûte</dt><dd>Elle rend la parole d’une enclave utilisable pour de l’argent&#160;: un mensonge qu’une machine peut prouver coûte toute la caution.</dd></div></dl></div><div class=\"mk-why-m\"><h4 class=\"mk-sub\">Les enclaves seules ne se vendent pas</h4><p class=\"mk-blede\">Vérifier des machines trouve peu d’utilisateurs à lui seul. Les services qu’on paie, si.</p><div class=\"mk-vs\"><div class=\"mk-vs-c mk-vs-a\"><p class=\"lbl mk-vs-h\">La vérification seule</p><ul><li><span class=\"mk-vs-n\">Point d’entrée DCAP d’Automata sur Ethereum</span><span class=\"mk-vs-v\">utilisé une fois en quatre mois</span></li><li><span class=\"mk-vs-n\">Marlin Oyster Serverless</span><span class=\"mk-vs-v\">0 événement en 56 heures</span></li><li><span class=\"mk-vs-n\">Sui Nautilus</span><span class=\"mk-vs-v\">519 vérifications en 17 mois</span></li><li><span class=\"mk-vs-n\">Marché de preuves de Boundless</span><span class=\"mk-vs-v\">arrêté après 0,12&#160;% d’usage</span></li></ul></div><div class=\"mk-vs-c mk-vs-b\"><p class=\"lbl mk-vs-h\">Les services payés</p><ul><li><span class=\"mk-vs-n\">Phala</span><span class=\"mk-vs-v\">environ 3,1 M$ de revenus en 2025, 398 clients payants</span></li><li><span class=\"mk-vs-n\">Chutes</span><span class=\"mk-vs-v\">3,7 M$ de frais</span></li><li><span class=\"mk-vs-n\">Targon</span><span class=\"mk-vs-v\">10,4 M$ par an, déclarés par l’entreprise</span></li></ul></div></div><p class=\"mk-so\">ArcHive donne donc la vérification et gagne sur les produits.</p><p class=\"lbl muted mk-src\">Notre recherche du 1er nov. 2026, sur sources publiques. Certains revenus sont déclarés par les entreprises elles-mêmes.</p></div></div></section><section class=\"mk-b\" id=\"market-first\" aria-labelledby=\"market-first-h\"><header class=\"mk-bhd\"><h3 class=\"mk-bh\" id=\"market-first-h\"><span class=\"mk-bn mono\" aria-hidden=\"true\">06</span><span>Qui achète en premier</span></h3><p class=\"mk-blede\">Nous ouvrons avec la Prime scellée, le seul produit dont l’acheteur paie déjà pour sa sécurité. Puis l’IA privée, pour les équipes qui ne peuvent pas utiliser l’IA sans confidentialité.</p></header><dl class=\"mk-big\"><div class=\"row\"><dt class=\"mk-big-v\">144,7 M$</dt><dd class=\"mk-big-d\">versés aux chasseurs sur Immunefi, au total</dd></div><div class=\"row\"><dt class=\"mk-big-v\">1,25 Md$</dt><dd class=\"mk-big-d\">volés au 3ᵉ trimestre 2026, environ 270 $ pour 1 $ de prime versé</dd></div><div class=\"row\"><dt class=\"mk-big-v\">+135&#160;%</dt><dd class=\"mk-big-d\">de rapports de bugs en 2025, et 60 à 80&#160;% invalides chez Cantina</dd></div></dl><ol class=\"mk-who\"><li class=\"row mk-who-c\"><span class=\"mk-who-n mono\" aria-hidden=\"true\">01</span><h4 class=\"mk-who-t\">Les protocoles sur Arc</h4><p class=\"mk-who-d\">Une réserve pilote sur un ou deux contrats, à côté de leur prime actuelle. 107,7 M$ sont arrivés sur Arc avec Extended en octobre, et aucun des 219 programmes publics d’Immunefi ne cite Arc.</p></li><li class=\"row mk-who-c\"><span class=\"mk-who-n mono\" aria-hidden=\"true\">02</span><h4 class=\"mk-who-t\">Les créateurs d’agents d’IA</h4><p class=\"mk-who-d\">Le paiement à l’appel avec une signature, sans compte ni dépôt. Quelques USDC de crédit suffisent à une équipe pour l’essayer depuis son agent.</p></li><li class=\"row mk-who-c\"><span class=\"mk-who-n mono\" aria-hidden=\"true\">03</span><h4 class=\"mk-who-t\">Les équipes aux données privées</h4><p class=\"mk-who-d\">Juridique, crédit, KYC et fraude&#160;: des équipes qui ont besoin d’un modèle privé et d’une trace de chaque réponse. L’AI Act européen impose aux IA de notation de crédit de journaliser automatiquement à partir de décembre 2027.</p></li><li class=\"row mk-who-c\"><span class=\"mk-who-n mono\" aria-hidden=\"true\">04</span><h4 class=\"mk-who-t\">Les propriétaires de machines</h4><p class=\"mk-who-d\">Les détenteurs de machines Intel TDX, dans le cloud ou chez eux, qui veulent une demande payée pour elles.</p></li></ol><p class=\"mk-honest\">Aucun payeur extérieur n’a encore dit oui. Un pilote nommé est notre prochaine étape.</p><p class=\"lbl muted mk-src\">Chiffres du marché&#160;: notre recherche du 1er nov. 2026 (Immunefi, DefiLlama, Cantina).</p></section><section class=\"mk-b\" id=\"market-grow\" aria-labelledby=\"market-grow-h\"><header class=\"mk-bhd\"><h3 class=\"mk-bh\" id=\"market-grow-h\"><span class=\"mk-bn mono\" aria-hidden=\"true\">07</span><span>Comment ça grandit</span></h3><p class=\"mk-blede\">Notre lecture de la boucle. La règle de capacité de l’étape 3 est dans le code.</p></header><div class=\"mk-fly\"><svg class=\"mk-fly-svg\" viewBox=\"0 0 320 320\" role=\"img\" aria-label=\"Une boucle en quatre étapes : plus de produits, plus d’usage payé, plus de cautions, plus de confiance, puis de nouveau plus de produits.\"><circle class=\"mk-fly-ring\" cx=\"160\" cy=\"160\" r=\"116\" /><circle class=\"mk-fly-run\" cx=\"160\" cy=\"160\" r=\"116\" pathLength=\"360\" /><g class=\"mk-fly-arc\"><path d=\"M190.02300923189242,47.952604150468076 A116,116 0 0 1 272.04739584953194,129.97699076810758\" /><polygon points=\"273.85912916524956,136.73847155213107 276.10056784566973,125.78511806372778 266.441309582779,128.37330851475298\" /></g><g class=\"mk-fly-arc\"><path d=\"M272.04739584953194,190.02300923189242 A116,116 0 0 1 190.02300923189242,272.04739584953194\" /><polygon points=\"183.26152844786893,273.85912916524956 194.2148819362722,276.10056784566973 191.62669148524702,266.441309582779\" /></g><g class=\"mk-fly-arc\"><path d=\"M129.97699076810758,272.04739584953194 A116,116 0 0 1 47.95260415046809,190.02300923189244\" /><polygon points=\"46.140870834750444,183.26152844786895 43.89943215433031,194.21488193627223 53.558690417221,191.62669148524705\" /></g><g class=\"mk-fly-arc\"><path d=\"M47.95260415046806,129.97699076810764 A116,116 0 0 1 129.9769907681076,47.952604150468076\" /><polygon points=\"136.7384715521311,46.14087083475043 125.78511806372781,43.89943215433029 128.373308514753,53.55869041722098\" /></g><g class=\"mk-fly-node\"><rect x=\"143\" y=\"27\" width=\"34\" height=\"34\" /><text x=\"160\" y=\"48.5\" text-anchor=\"middle\">01</text></g><g class=\"mk-fly-node\"><rect x=\"259\" y=\"143\" width=\"34\" height=\"34\" /><text x=\"276\" y=\"164.5\" text-anchor=\"middle\">02</text></g><g class=\"mk-fly-node\"><rect x=\"143\" y=\"259\" width=\"34\" height=\"34\" /><text x=\"160\" y=\"280.5\" text-anchor=\"middle\">03</text></g><g class=\"mk-fly-node\"><rect x=\"27\" y=\"143\" width=\"34\" height=\"34\" /><text x=\"44\" y=\"164.5\" text-anchor=\"middle\">04</text></g><text class=\"mk-fly-c1\" x=\"160\" y=\"156\" text-anchor=\"middle\">PAYÉ EN USDC</text><text class=\"mk-fly-c2\" x=\"160\" y=\"175\" text-anchor=\"middle\">VÉRIFIÉ PAR ARC</text></svg><ol class=\"mk-fly-list\"><li class=\"row mk-fly-li\"><span class=\"mk-fly-n mono\" aria-hidden=\"true\">01</span><p><b>Plus de produits</b> amènent plus d’acheteurs&#160;: agents, apps et protocoles qui paient en USDC.</p></li><li class=\"row mk-fly-li\"><span class=\"mk-fly-n mono\" aria-hidden=\"true\">02</span><p><b>Plus d’usage payé</b> veut dire plus de revenu par machine, ce qui attire des opérateurs. Chacun bloque une caution.</p></li><li class=\"row mk-fly-li\"><span class=\"mk-fly-n mono\" aria-hidden=\"true\">03</span><p><b>Plus de cautions</b> augmentent ce que le réseau peut payer sur la parole des enclaves&#160;: la moitié de la caution disponible de chaque opérateur (sa caution moins tout retrait demandé) par 24 heures, dans le plafond de chaque produit. De plus grosses primes deviennent possibles.</p></li><li class=\"row mk-fly-li\"><span class=\"mk-fly-n mono\" aria-hidden=\"true\">04</span><p><b>Plus de confiance</b> plus d’opérateurs et de machines vérifiées rendent les résultats plus sûrs, ce qui amène plus d’auteurs et plus de produits.</p></li></ol></div></section><section class=\"mk-b\" id=\"market-main\" aria-labelledby=\"market-main-h\"><header class=\"mk-bhd\"><h3 class=\"mk-bh\" id=\"market-main-h\"><span class=\"mk-bn mono\" aria-hidden=\"true\">08</span><span>Sur le mainnet&#160;: l’économie unitaire</span><span class=\"mk-tag lbl\">Estimation</span></h3><p class=\"mk-blede\">Notre tarification pour le mainnet, calculée le 7 nov. à partir du prix du gaz d’Arc et des prix de nos fournisseurs. Les prix du testnet sont aujourd’hui des valeurs de démo, réglées haut pour que chaque flux se voie sur l’explorateur.</p></header><figure class=\"mk-bar-f\"><figcaption class=\"mk-bar-c\"><span>Une requête typique d’IA privée, 40 000 jetons en entrée et 2 000 en sortie</span><span class=\"mono tnum mk-bar-tot\">0,0096 USDC pour l’acheteur</span></figcaption><div class=\"mk-bar\" role=\"img\" aria-label=\"Partage de 0,0096 USDC : 0,0072 USDC pour le modèle, 0,00192 USDC de marge pour l’opérateur, 0,00048 USDC pour le réseau\"><span class=\"mk-seg t-model\" style=\"flex-grow: 7200;\"><span class=\"mk-seg-l mono\">75&#160;%</span></span><span class=\"mk-seg t-op\" style=\"flex-grow: 1920;\"><span class=\"mk-seg-l mono\">20&#160;%</span></span><span class=\"mk-seg t-net\" style=\"flex-grow: 480;\"></span></div><ul class=\"mk-legend\"><li><i class=\"mk-sw t-model\" aria-hidden=\"true\"></i>Le modèle, payé au fournisseur <span class=\"mono tnum\">0,0072 USDC</span> <span class=\"muted\">75&#160;%</span></li><li><i class=\"mk-sw t-op\" aria-hidden=\"true\"></i>Marge de l’opérateur <span class=\"mono tnum\">0,00192 USDC</span> <span class=\"muted\">20&#160;%</span></li><li><i class=\"mk-sw t-net\" aria-hidden=\"true\"></i>Réseau, 5&#160;% <span class=\"mono tnum\">0,00048 USDC</span> <span class=\"muted\">5&#160;%</span></li></ul><p class=\"mk-note\">Environ un tiers de plus que le même modèle acheté directement, pour une requête scellée et un reçu signé. Modèle gpt-oss-120b via RedPill, à 0,15 $ par million de jetons en entrée et 0,60 $ en sortie.</p></figure><dl class=\"kv-list mk-kv\"><div class=\"kv-row\"><dt>Seuil de rentabilité</dt><dd>Environ 835 à 850 requêtes typiques par jour, soit environ 8 USDC de ventes, pour une machine CPU qui coûte environ 1,53 $ par jour (VM 1,39 $, inscription quotidienne 0,14 USDC).</dd></div><div class=\"kv-row\"><dt>Marge au plafond</dt><dd>Environ 7,9 à 8 $ par jour avec une caution de 100 USDC, qui plafonne les ventes à 50 USDC par jour.</dd></div><div class=\"kv-row\"><dt>Cautions</dt><dd>100 USDC pour une machine CPU, 1 000 USDC pour un GPU. Un tricheur peut prendre au plus la moitié de sa caution par jour, et la perd entière une fois pris.</dd></div><div class=\"kv-row\"><dt>Paiement à l’appel</dt><dd>Au moins 0,10 USDC l’appel, pour que le gaz de règlement (0,0063 USDC) reste près de 6&#160;%. En dessous, une session.</dd></div><div class=\"kv-row\"><dt>Sessions</dt><dd>Un dépôt de 5 USDC par défaut, un gaz d’environ 1,3&#160;% de ce dépôt, réglé dès que 0,50 USDC est dû.</dd></div><div class=\"kv-row\"><dt>Prime scellée</dt><dd>Le protocole paie le palier plus 15&#160;%, seulement quand un paiement a lieu. Réserve pilote de 20 000 USDC, paliers de 100, 1 000, 5 000 et 10 000 USDC pour des pertes à partir de 1 k, 10 k, 50 k et 100 k.</dd></div><div class=\"kv-row\"><dt>Capital de lancement</dt><dd>Environ 410 USDC bloqués en cautions, coffre de démo et première réserve, dont environ 355 récupérables.</dd></div><div class=\"kv-row\"><dt>Le testnet aujourd’hui</dt><dd>Caution minimale de 1 USDC, plafond de 10 USDC par 24 h, délai 0, IA privée à 100 USDC le million de jetons.</dd></div></dl></section><section class=\"mk-b\" id=\"market-not\" aria-labelledby=\"market-not-h\"><header class=\"mk-bhd\"><h3 class=\"mk-bh\" id=\"market-not-h\"><span class=\"mk-bn mono\" aria-hidden=\"true\">09</span><span>Avant le mainnet</span></h3><p class=\"mk-blede\">Ce qu’un acheteur doit savoir aujourd’hui.</p></header><ul class=\"mk-not\"><li class=\"row\"><span class=\"mk-not-m\" aria-hidden=\"true\"></span><p><b>Le mainnet</b> ArcHive tourne sur Arc testnet. Déployer le vérificateur d’Intel sur le mainnet d’Arc prend 37 transactions, environ 1,4 USDC.</p></li><li class=\"row\"><span class=\"mk-not-m\" aria-hidden=\"true\"></span><p><b>Un opérateur, une machine</b> Sur le testnet, toutes les enclaves vérifiées tournent sur une seule machine, chez un seul opérateur. Chaque paiement jusqu’ici est venu de nos propres wallets.</p></li><li class=\"row\"><span class=\"mk-not-m\" aria-hidden=\"true\"></span><p><b>Des enclaves en service</b> Les enclaves vérifiées des produits n° 1, 2, 3, 4 et 5 tournent sur la pile v3. Tout ce qui est déjà sur Arc reste lisible.</p></li><li class=\"row\"><span class=\"mk-not-m\" aria-hidden=\"true\"></span><p><b>Avant l’argent réel</b> Viennent ensuite les preuves d’état en production, la vérification d’identité au paiement, une voie pour les paiements au-delà du plafond de caution, un audit externe et nos paquets sur npm.</p></li><li class=\"row\"><span class=\"mk-not-m\" aria-hidden=\"true\"></span><p><b>Les agents préparent, une personne signe</b> AskHive et le serveur MCP préparent les opérations. Une personne signe chacune avec son propre wallet.</p></li></ul></section>"},{"id":"build","cls":"vit-sec vit-build","k":"Construire dessus","t":"Construire dessus","plain":"Construire dessus.","units":"","body":"<h2 aria-label=\"Construire dessus.\" class=\"vt-h vit-h2\" id=\"build-h\">Construire dessus.<span class=\"ttl-rule\" aria-hidden=\"true\"></span></h2><p class=\"lede vit-sec-l\">Ce que fait une page produit, votre code peut le faire&#160;: lire le réseau, préparer une opération, la signer avec votre propre wallet.</p><div class=\"vit-build-g\"><div class=\"vit-build-c\"><h3 class=\"vit-build-t\">Serveur MCP, en ligne</h3><p class=\"vit-build-d\">16&#160;outils pour Claude, Cursor ou tout client MCP. Ils lisent le réseau et préparent les opérations. Ils ne signent jamais&#160;: c’est vous.</p><p class=\"lbl muted\">URL du serveur, Streamable HTTP, sans compte ni clé</p><div class=\"cmd\"><code class=\"mono cmd-t\">https://arc-hive.xyz/mcp</code><button class=\"cmd-b\" aria-label=\"Copier: https://arc-hive.xyz/mcp\">Copier</button></div><p class=\"lbl muted\">Claude Code</p><div class=\"cmd\"><code class=\"mono cmd-t\">claude mcp add --transport http archive https://arc-hive.xyz/mcp</code><button class=\"cmd-b\" aria-label=\"Copier: claude mcp add --transport http archive https://arc-hive.xyz/mcp\">Copier</button></div></div><div class=\"vit-build-c\"><h3 class=\"vit-build-t\">API publique</h3><p class=\"vit-build-d\">13&#160;routes en lecture seule, en JSON&#160;: produits, enclaves, primes, chaîne de preuves, niveaux d’opérateur.</p><div class=\"cmd\"><code class=\"mono cmd-t\">curl https://arc-hive.xyz/api/products</code><button class=\"cmd-b\" aria-label=\"Copier: curl https://arc-hive.xyz/api/products\">Copier</button></div></div><div class=\"vit-build-c\"><h3 class=\"vit-build-t\">SDK et CLI</h3><p class=\"vit-build-d\">Un SDK TypeScript (81&#160;tests) et une CLI de 33 commandes, dans le dépôt du projet. Ils ne sont pas encore publiés sur npm&#160;: installez-les depuis le dépôt.</p></div><div class=\"vit-build-c\"><h3 class=\"vit-build-t\">Contrats</h3><p class=\"vit-build-d\">13 contrats en service sur Arc testnet. Leurs adresses et les contrôles qu’ils font sont dans la Doc.</p><a class=\"tlink\" href=\"/doc.html?c=contracts\">Ouvrir la Doc</a></div></div>"},{"id":"faq","cls":"vit-sec vit-faq","k":"Questions","t":"Questions","plain":"Questions","units":"","body":"<h2 aria-label=\"Questions\" class=\"vt-h vit-h2\" id=\"faq-h\">Questions<span class=\"ttl-rule\" aria-hidden=\"true\"></span></h2><div class=\"vit-faq-l\"><details class=\"vit-more vit-q\"><summary><span class=\"vit-more-t\">Est-ce en ligne&#160;?</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><p>Sur Arc testnet, oui&#160;: les contrats de la pile v3, ses cinq produits et chaque paiement passé sont en ligne et lisibles dès maintenant. Les enclaves vérifiées des produits n° 1, 2, 3, 4 et 5 tournent sur la pile v3 : ces services s’utilisent dès maintenant.</p></div></details><details class=\"vit-more vit-q\"><summary><span class=\"vit-more-t\">Quelqu’un a-t-il déjà payé&#160;?</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><p>Seulement notre équipe. Chaque paiement sur Arc jusqu’ici vient de nos propres wallets de test, et aucun client extérieur n’a encore payé. Nous commençons par les protocoles d’Arc qui pourraient financer une cagnotte pilote, puis les équipes d’IA qui ne peuvent pas utiliser une API ordinaire.</p></div></details><details class=\"vit-more vit-q\"><summary><span class=\"vit-more-t\">Qui paie qui&#160;?</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><p>Les acheteurs paient à l’usage en USDC&#160;: une session prépayée, une signature par appel, ou une cagnotte de prime. Le contrat partage chaque paiement dans la même transaction&#160;: sur nos produits, 95&#160;% pour l’opérateur qui fait tourner la machine et 5&#160;% pour le réseau. Un auteur peut prendre jusqu’à 30&#160;%, et le réseau garde toujours au moins 5&#160;%. Sur une prime, le chasseur touche tout le palier, plus 10&#160;% au réseau et 5&#160;% aux opérateurs vérificateurs. Vérifier une machine ne coûte que du gaz, et il n’y a aucun jeton.</p></div></details><details class=\"vit-more vit-q\"><summary><span class=\"vit-more-t\">Pourquoi faut-il une enclave&#160;?</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><p>Parce que chaque produit garde quelque chose que personne ne doit voir ni falsifier&#160;: une requête que l’opérateur ne doit pas lire, un exploit qui doit rester secret jusqu’au paiement, un assistant dont les instructions ne doivent pas changer en silence. Une enclave Intel TDX exécute un code que son propre opérateur ne peut ni lire ni modifier, et prouve de quel code il s’agit. Arc vérifie cette preuve avant que le moindre argent ne bouge.</p></div></details><details class=\"vit-more vit-q\"><summary><span class=\"vit-more-t\">Et si une enclave ment&#160;?</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><p>Son opérateur perd tout ce qu’il a déposé. Chaque opérateur dépose une caution en USDC. Si un mensonge est prouvé, par deux autres opérateurs qui rejouent le travail dans les 3&#160;jours ou par deux reçus contradictoires, le contrat saisit toute la caution, moitié pour qui l’a prouvé, moitié pour la victime, et bannit l’opérateur. C’est arrivé sur Arc le 10 novembre, 16 secondes après l’acceptation du mensonge. En attendant, ce qu’un opérateur peut encaisser sur la parole de ses enclaves est plafonné à la moitié de sa caution disponible (sa caution moins tout retrait demandé) sur 24 heures glissantes, et au plafond du produit.</p></div></details><details class=\"vit-more vit-q\"><summary><span class=\"vit-more-t\">Puis-je publier mon propre produit&#160;?</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><p>Oui. La publication est ouverte, sans revue&#160;: vous fixez le prix, votre part jusqu’à 30&#160;%, le code de machine qu’Arc acceptera et le niveau d’opérateur minimum. Des opérateurs le font ensuite tourner, et le contrat le facture pour vous. Sur le testnet, un nouveau produit est en ligne aussitôt. Sur le mainnet, un délai de 48 heures est prévu.</p></div></details><details class=\"vit-more vit-q\"><summary><span class=\"vit-more-t\">Est-ce sur le mainnet&#160;?</span><span class=\"vit-more-i\" aria-hidden=\"true\"></span></summary><div class=\"vit-more-b\"><p>Pas encore. Tout tourne sur Arc testnet. Le mainnet demande le vérificateur d’Intel déployé sur Arc mainnet (37 transactions, environ 1,4&#160;USDC), des opérateurs indépendants et un premier client extérieur.</p></div></details></div>"}]}}
